/* DFA -> C code generation, two engines (see docs/dev/decisions.md D3/D7):
 *
 * ENG_UNANCH (patterns without `^`, including `$`-bearing ones since M2.7):
 * one O(n) forward pass over the
 * subject with the unanchored priority DFA (finds the leftmost-first match
 * END), then a backward pass with the non-pruning reverse DFA (earliest
 * accepting position = match START). Emitted TABLE-DRIVEN — int16 transition
 * tables + a generic loop — because gcc's compile time on huge computed-goto
 * functions is superlinear (R1 A-3) while data initializers stay flat. A
 * memchr (single escape byte) or bitmap skip loop runs while the machine is
 * parked in the start state (M2.1 prefilter).
 *
 * ENG_ATTEMPT (patterns containing `^`): per-start-position computed-goto
 * attempt loop with EOL-variant states (R1 S-C1/S-C2). `^` needs a
 * position-dependent BOT variant in the REVERSE machine, which the DFA does
 * not build yet, so these stay here; fully-anchored patterns get the
 * start_max=0 fast path, so the slow shape is `^` on only SOME branches.
 *
 * Generated code is self-contained: no dependency on pcrec at build or run
 * time.
 *
 * [M4.4] (docs/design/match_api_m4.md, the MATCH-API FREEZE): the API BREAK
 * lands mechanically here. `<prefix>_span`/`emit_span_typedef` are RETIRED
 * (D44.2) in favor of a caps-array `<prefix>_search` parameter that is
 * already its FINAL shape; the fixed-literal ABI types (`rx_ctx`,
 * `rx_matchfn`, `rx_callout_ref`, `rx_group_entry`, `rx_info`,
 * `rx_renderfn`) are emitted once per file; `<prefix>_match` and
 * `<prefix>_match_caps` are new unconditional exports, retrofitted onto the
 * existing DFA matchers by calling through `<prefix>_search` rather than by
 * building a second, genuinely-anchored automaton (nothing at [M4.4]
 * requires the VM); and `<prefix>_info` is a new `.rodata` reflection
 * structure. See that document's §11 for the itemized checklist this file
 * discharges. */

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "core/internal.h"
#include "gen/enc/enc.h"

static void emit_pattern_comment(StrBuf *sb, const char *pat)
{
    sb_puts(sb, "/* Generated by pcrec. Pattern: ");
    int prev = 0;
    for (const char *q = pat; *q; q++) {
        unsigned char ch = (unsigned char)*q;
        if (ch >= 32 && ch < 127 && !(prev == '*' && ch == '/'))
            sb_putc(sb, (char)ch);
        else
            sb_printf(sb, "\\x%02x", ch);
        prev = ch;
    }
    sb_puts(sb, " */\n");
}

/* [M4.4] (match_api_m4.md §5, A-11): rx_info.pattern is emitted as a real C
 * STRING LITERAL, not a comment — a wholly different escaping obligation
 * from emit_pattern_comment above, which is NOT this escaper: it avoids the
 * comment-close sequence and hex-escapes non-printables so the text is safe
 * inside a C comment, but does nothing about a double quote or a backslash,
 * both legal and unescaped in a PCRE pattern and both of which would
 * terminate or corrupt a C string literal if copied through verbatim
 * (e.g. a class like [^"]*" ).
 *
 * Non-printables use a fixed THREE-DIGIT OCTAL escape, never `\xNN`: a hex
 * escape consumes every hex digit that follows with no length limit, so a
 * non-printable byte immediately before a literal hex digit ('0'-'9',
 * 'a'-'f', 'A'-'F') would glue onto it and silently corrupt the next byte
 * of the string. `\NNN`, always emitted zero-padded to exactly three
 * digits, consumes exactly three digits and so can never glue with
 * whatever follows.
 *
 * `?` is ALSO always escaped as `\?`, found failing-first against the
 * corpus (tests/base/review_r21.rxt's `(b??(a*)*)*`): two literal `?`
 * followed by one of `( ) < > = / ' ! -` forms a TRIGRAPH, and gcc treats
 * an unescaped trigraph-looking sequence inside a string literal as a
 * `-Wtrigraphs` warning, `-Werror` under the harness's GENCFLAGS. `\?` is
 * an ordinary escape for a plain `?` in every C dialect this project
 * targets, so escaping every `?` unconditionally is simpler and no less
 * correct than detecting the nine specific trigraph-forming sequences. */
static void emit_c_string_literal(StrBuf *sb, const char *s, size_t len)
{
    sb_putc(sb, '"');
    for (size_t i = 0; i < len; i++) {
        unsigned char ch = (unsigned char)s[i];
        switch (ch) {
            case '"':  sb_puts(sb, "\\\""); break;
            case '\\': sb_puts(sb, "\\\\"); break;
            case '?':  sb_puts(sb, "\\?");  break;
            case '\n': sb_puts(sb, "\\n");  break;
            case '\t': sb_puts(sb, "\\t");  break;
            case '\r': sb_puts(sb, "\\r");  break;
            default:
                if (ch >= 32 && ch < 127)
                    sb_putc(sb, (char)ch);
                else
                    sb_printf(sb, "\\%03o", ch);
        }
    }
    sb_putc(sb, '"');
}

/* D37 (docs/dev/decisions.md): emitted C is SELF-DESCRIBING about which
 * feature modules were enabled at generation time — the comment for a
 * human, the macros for a machine (or a future pcrec: pass
 * PCREC_FEATURE_MODULES's value to --features and get the same gate state
 * this artifact was built with, even if a named set's own meaning, or
 * "all"'s membership, has since changed). Both values come from
 * src/parse/enabled.c's OWN render of the currently-installed set — there
 * is no second copy of "what does this mask mean as names" here. Every
 * value in play (a named set's name, "all"/"none"/"explicit", and every
 * module name) comes from pcrec's own fixed vocabulary, never from the
 * pattern text, so unlike emit_pattern_comment above nothing here needs
 * escaping. */
static void emit_feature_comment(StrBuf *sb)
{
    const char *label = pcrec_enabled_set_label();
    const char *mods = pcrec_enabled_set_modules();
    sb_printf(sb, "/* Feature set: %s (modules: %s) */\n",
              label, *mods ? mods : "none");
}

/* Macros, ONCE PER FILE like the ABI-types block below — the enabled set is
 * process-wide (one set for the whole compile), so every engine a future
 * multi-engine file carries (OS-0b) shares one stamp. Lives only in the .c:
 * a paired .h gets the comment (emit_header, matching its existing
 * pattern-comment convention) but not these, so a .c that #includes its own
 * .h never sees the pair twice. */
static void emit_feature_macros(StrBuf *sb)
{
    sb_printf(sb, "#define PCREC_FEATURE_SET \"%s\"\n",
              pcrec_enabled_set_label());
    sb_printf(sb, "#define PCREC_FEATURE_MODULES \"%s\"\n",
              pcrec_enabled_set_modules());
}

/* [DD-13] (D46, and the D76 abi-4 event) THE ENGINE STAMP, EMITTED FROM ONE
 * PLACE FOR BOTH ENGINES.
 *
 * `<PREFIX>_ENGINE` is the D46 family's first SELECTION FACT and since this
 * change it is UNCONDITIONAL — present on every artifact pcrec emits, with an
 * engine-appropriate value. It used to be a `sb_printf` inside `emit_vm.c`'s
 * stamp block and nowhere else, which is precisely the shape that made a DFA
 * artifact silent about its own engine: the macro belonged to the emitter that
 * happened to write it rather than to the fact.
 *
 * (The stamp lives in the emitted .c, not the .h — a header-only consumer
 * cannot `#if` on it yet; §6.3 records header emission as an open question.)
 *
 * ONE FUNCTION AND NOT TWO CALL SITES SPELLING THE SAME `#define`, because the
 * whole value of an unconditional stamp is that a consumer may write
 * `#if RX_ENGINE ...` without knowing which engine it got, and two independent
 * `sb_printf`s are two chances for the spelling to drift. The VM's call passes
 * `"vm"` and the DFA's `"dfa"`; those two strings are `rx_info.engine`'s
 * PCREC_ENGINE_VM/_DFA in words, and match_api.md §6.3 states the mirror.
 *
 * WHAT IS *NOT* SHARED, deliberately: `<PREFIX>_ENGINE_WHY`. It names the
 * construct that FORCED the VM, and a DFA artifact was not forced — its
 * `rx_info.engine_why` is NULL for the same reason — so the macro's absence
 * on a DFA artifact mirrors the struct rather than hiding anything. The
 * per-engine PREFILTER stamps are not shared either: their VALUE SETS are
 * different (§6.3's (a)/(b) split rules the NAMES engine-specific), and a
 * shared emitter for two different vocabularies would only be a switch. */
/* [DD-13c] THE DFA SCAN'S TWO FACTS, forward-declared: their definitions sit
 * beside the derivations they read (`unanch_start`/`attempt_cand`, far below),
 * and THREE emitters call them from above — the DFA artifact's stamp block, the
 * VM hybrid's (src/gen/emit_vm.c), and `emit_info_def`'s runtime mirror. Three
 * readers of ONE derivation is this file's standing rule; a forward declaration
 * is the cheap way to keep the definition next to what it derives from rather
 * than hoisting forty lines of start analysis to the top of the file. */
static const char *dfa_scan_name(Ctx *cx);
static const char *dfa_prefilter_name(Ctx *cx);
/* [ENG-ABS] AXIS G's chosen object's name — the third fact with the same
 * shape and the same reason for the forward declaration: the selection lives
 * beside the candidate list far below, and THREE readers call it from above
 * (the `<PREFIX>_DFA_MATCH` stamp, `rx_info.match_form`, and the dispatch that
 * decides WHICH `<prefix>_match` body is written). One derivation, three
 * readers, so the stamp cannot disagree with the emitted entry. */
static const char *dfa_match_name(Ctx *cx);
/* The same selection asked as a yes/no, for the two sites that need the
 * ANSWER rather than the name (the entry dispatch, and `RX_DFA_TABLE`'s
 * composition, which must include the anchored machine iff it was emitted).
 * Spelling it once here is what stops a `strcmp(name, "unwrapped")` growing
 * somewhere as a second reading of the same selection. */
static bool dfa_match_is_unwrapped(Ctx *cx);

/* [OPT-5 STEP 2] AXIS J's chosen object's name, forward-declared for axis G's
 * reason exactly: the selection lives beside its candidate list far below and
 * FIVE readers call it from above — `<PREFIX>_DFA_START`, `rx_info.
 * search_form`, `emit_unanchored`'s own dispatch, and the two stamp folds
 * (`dfa_table_name`, `dfa_scan_edge_name`) that must stop naming a machine a
 * pinned artifact no longer contains. One derivation, five readers, so no
 * reader can disagree with the body that was emitted. */
static const char *dfa_search_start_name(Ctx *cx);
/* The same selection asked as a yes/no, for the four sites that need the
 * ANSWER rather than the name. Spelled once here so that no
 * `strcmp(name, "pinned")` grows anywhere as a second reading. */
static bool dfa_search_is_pinned(Ctx *cx);

/* [DD-13c] DOES THIS ARTIFACT CONTAIN A DFA SCAN AT ALL?
 *
 * THE CONDITION IS src/core/compile.c's, VERBATIM AND ON PURPOSE: that file
 * builds `job->dfa`/`job->rdfa` and sets `job->engine` under exactly
 * `fit.chosen == ENGM_DFA || fit.prefilter`, so this predicate is not a claim
 * about the artifact that happens to agree — it IS the condition that made the
 * machine exist. Everything downstream depends on that: `dfa_scan_name` and
 * `dfa_prefilter_name` read fields that were never written when this is false,
 * so both the hybrid's stamp gate and the runtime mirror ask HERE rather than
 * spelling a test of their own.
 *
 * True on every DFA artifact and on every VM HYBRID; false on a non-hybrid VM
 * artifact, which carries no DFA and therefore stamps neither macro and mirrors
 * NULL. docs/spec/match_api.md §6.3 (a) states the iff this implements. */
bool pcrec_artifact_has_dfa_scan(Ctx *cx)
{
    return cx->job->fit.chosen == ENGM_DFA || cx->job->fit.prefilter;
}

/* [OPT-4] `<PREFIX>_ENGINE_SEL`'s value, from `EngineFit.engine_sel`. ONE
 * spelling of each token, read by the stamp and by nothing else yet — when a
 * second reader appears (an `rx_info` mirror, say) it calls this rather than
 * re-listing the strings, which is the rule `dfa_scan_name` and friends above
 * already follow. */
const char *pcrec_engine_sel_name(Ctx *cx)
{
    switch (cx->job->fit.engine_sel) {
    case ESEL_FORCED:                    return "forced";
    /* [OPT-4.2] the RUNGLESS twin of ESEL_DECLINED_NULLABLE below: an
     * ordinary auto-selected (or forced --engine=vm) hybrid whose own EXACT
     * language is nullable, so no prefilter was ever built at all. */
    case ESEL_DECLINED_NULLABLE_DEFAULT: return "declined-nullable-default";
    case ESEL_OVERFLOWED_DFA:            return "overflowed-dfa";
    case ESEL_OVERFLOWED_PREFILTER:      return "overflowed-prefilter";
    case ESEL_COLLAPSED_PREFILTER:       return "collapsed-prefilter";
    case ESEL_DECLINED_NULLABLE:         return "declined-nullable";
    case ESEL_SIZE_CAP_RETRY:            return "size-cap-retry";
    default:                             return "selected";
    }
}

/* [OPT-4] `_ENGINE_SEL` rides THIS function rather than getting call sites of
 * its own, for the reason stated above it: it is the second UNCONDITIONAL
 * per-artifact stamp, on both engines, and two independent `sb_printf`s are
 * two chances for the spelling to drift. It is emitted immediately after
 * `_ENGINE` and BEFORE `_ENGINE_WHY` (which only the VM stamps), so the
 * closed-value token and the prose sit together on the artifacts that have
 * both and the token still appears alone on a DFA artifact — which is the
 * whole point of it being unconditional. */
void pcrec_emit_engine_stamp(StrBuf *c, const char *upper, const char *engine,
                             const char *sel)
{
    sb_printf(c, "#define %s_ENGINE \"%s\"\n", upper, engine);
    sb_printf(c, "#define %s_ENGINE_SEL \"%s\"\n", upper, sel);
}

/* [OPT-ALTCLS] D46's observability half for src/opt/altcls.c, in the SAME
 * PLACEMENT as the feature stamp immediately above and for the SAME reason
 * (STD1's own precedent): the pass runs before either engine is built, so
 * unlike possessify/revdet/prefilter's VM-only stamps this one belongs in
 * the SHARED prologue, once per file, read on both the DFA-only path and
 * the VM path (pcrec_emit_prologue is one of the five entry points
 * emit_vm.c shares rather than forks — src/gen/CLAUDE.md).
 *
 * COUNTS, not booleans or a single scalar: a pattern can carry more than one
 * mergeable/factorable alternation run (RX_VM_RUNGS's reasoning one level
 * up — a scalar would lie on a multi-run pattern by picking one run's
 * answer to speak for all of them, while a count cannot). Read straight off
 * `job->altcls_merges`/`job->altcls_factored`, which src/opt/altcls.c
 * increments at the exact points it acts and never otherwise — so the
 * stamp cannot disagree with what the rewrite actually did. Both stages'
 * denial flags (`PCREC_NO_ALTCLS_MERGE`/`PCREC_NO_ALTCLS_FACTOR`) leave
 * their counter at 0 by construction (the pass checks the flag before
 * touching the counter, never after), which is the "denial leaves no
 * trace" rule possessify's `-fno-possessify` already follows — a denied
 * build's stamp is indistinguishable from "this pattern had nothing to
 * merge/factor," so it does not disturb the byte-identity gate a denied
 * build is meant to serve as ground truth for. Emitted unconditionally
 * (STD1's own rule: no artifact should be ambiguous about what it was
 * built with), including the `0`/`0` case a pattern with no alternation
 * at all stamps honestly. */
static void emit_altcls_macros(StrBuf *sb, const char *upper, int merges, int factored)
{
    sb_printf(sb, "#define %s_ALTCLS_MERGES %d\n", upper, merges);
    sb_printf(sb, "#define %s_ALTCLS_FACTORED %d\n", upper, factored);
}

/* ---- the multi-engine naming surface (OS-0b; D18 measured, D20 owns it) ----
 *
 * One output file may eventually carry SEVERAL engines — one per point of the
 * option product, chosen by a generated selector (D18/D20). Almost nothing
 * here needs to change for that, because every identifier either emitter
 * produces is a FUNCTION-LOCAL static except the ones named below: the
 * unanchored engine's forward_byte_class/forward_next_state/
 * forward_is_accepting/forward_eol_view/can_begin_match/forward_stay<N>/
 * reverse_byte_class/reverse_next_state/reverse_is_accepting/
 * reverse_eol_view/reverse_stay<N>
 * and the attempt engine's cls/t<N> are all declared inside the engine
 * function, so two engines in two functions cannot collide on them however
 * similar their patterns. (D18 measured this on `.*=.*$`: 15 emitted
 * identifiers, 12 function-local.)
 *
 * That leaves the FILE-SCOPE names, which go through the helpers below:
 *
 *   emit_rx_abi_types  ONCE PER FILE, shared by every engine in it, guarded
 *                      by a PREFIX-INDEPENDENT `PCREC_RX_ABI_H` (D44/A-2) so
 *                      two differently-prefixed generated headers compile
 *                      together in one TU without a redefinition error.
 *   emit_ncaps_macros  ONCE PER FILE, per-prefix (RX_NCAPS under the file's
 *                      own --prefix). RX_UNSET/RX_ERR_STEPS/RX_ERR_FRAMES/
 *                      RX_ERR_WORK/RX_ERR_FLOOR moved OUT of this function
 *                      at [ABI-NS] (D60) to emit_rx_abi_types' shared block
 *                      as PCREC_UNSET/PCREC_ERR_* — they are pcrec-contract
 *                      facts, not per-prefix ones.
 *   emit_search_decl,
 *   emit_match_decl,
 *   emit_match_caps_decl,
 *   emit_info_decl     ONCE PER ENGINE, under that engine's own entry name.
 *
 * The entry name is produced by engine_entry_name() and read from nowhere
 * else, so a finder can hand each engine a distinct name (`rx_search_ci`)
 * without any emitter knowing that options have a product. Today there is one
 * engine per file and the name is "<prefix>_search". */

/* [M4.4] (D44.2, match_api_m4.md §1.0/§11 item 1): RETIRES emit_span_typedef
 * and its `<prefix>_span` out-struct — the search entry's fourth parameter
 * is now `ptrdiff_t (*caps)[2]` directly, already its FINAL shape (no
 * further signature change is owed when RX_NCAPS grows past 1 at [M4.5]). */
static void emit_search_decl(StrBuf *sb, const char *fn)
{
    sb_printf(sb, "int %s(const unsigned char *subject, size_t subject_length, "
                  "size_t search_from, ptrdiff_t (*capture_spans)[2]);\n", fn);
}

/* The definition's signature, kept next to the declaration it must match.
 *
 * [M4.5b] `storage` is "" for the exported entry and "static " for the VM
 * hybrid's PREFILTER (engine_m4.md §6.1), which is this same engine emitted
 * under a private name inside a VM artifact. Passing the storage class rather
 * than forking the emitter is the M2.12 lesson applied ahead of time: the `$`
 * fork is exactly how the prefilter and skip loops silently went missing from
 * one path for a whole milestone. `emit_search_head`'s two callers below both
 * pass it straight through from their own caller, so the DFA-only path's
 * output is unchanged byte for byte (storage == "").
 *
 * [K24] `noclone` IS THE FIX FOR K24 AND MUST NOT BE DELETED — it is not
 * decoration and it is not a micro-optimization. Full evidence chain:
 * docs/dev/known_issues.md K24 (closure entry) and
 * docs/design/k24bisect_impl/ (the bisect note plus this lane's head-to-head).
 *
 * WHAT IT PREVENTS: gcc -O2's partial-inlining pass (`-fpartial-inlining`,
 * on by default) sees this function's cheap entry guard in front of a large
 * scan body and SPLITS it into a trampoline plus a separately-placed
 * `<prefix>_search.part.0` clone carrying the loop. The split loop's
 * instructions are IDENTICAL — the cost is pure code placement, and it is
 * real and reproducible: MEASURED at 1.33x on the compare.sh case-(c) shape
 * (`(alpha|beta|gamma|delta|epsilon)`, 8 MB nomatch subject: 293.5 MB/s split
 * vs 391.6 unsplit, pinned, 10 trials, <1% spread), which is what took that
 * case's D12 floor red for three days. `noclone` forbids exactly the one
 * thing the pass needs — duplicating this body — and the emitted assembly is
 * then BYTE-IDENTICAL to the same source compiled `-O2
 * -fno-partial-inlining`, which is the causal control the bisect used.
 *
 * WHY THIS ATTRIBUTE AND NOT ANOTHER, all measured head-to-head on that same
 * case (the table is in the K24 closure entry):
 *   - `noipa`/`noinline` on the two COLD WRAPPERS (`<prefix>_match`,
 *     `<prefix>_match_caps`) do NOT work — 292.7 and 295.3 MB/s, the split
 *     still present in `nm`. This refutes the obvious theory: gcc's
 *     `pass_split_functions` runs on the CALLEE and does not consult its
 *     callers' attributes, so severing IPA at the call site leaves the clone
 *     standing. It has to be denied at THIS function.
 *   - `hot` here, or `cold` on the wrappers, recovers the number (397) while
 *     LEAVING the split in place — luck about placement in one particular
 *     link, not a fix. The two combined measured 288.7, WORSE than doing
 *     nothing: layout steering is exactly as unpredictable as the mechanism
 *     it would be steering around, and a stranger's link is not this one.
 *   - `optimize("no-partial-inlining")` works (390.9) but replaces this
 *     function's whole optimization environment to fix one pass.
 *   - `noipa` works (390.8) but is far wider than needed, and would forbid
 *     the VM hybrid's inlining of this same emitter's static prefilter into
 *     `<prefix>_search`, which is a real inline gcc performs today.
 * `noclone` is the smallest denial that is about the mechanism rather than
 * about this box's layout. It cannot be moved to the caller side, and a
 * user's CFLAGS cannot be dictated, which is why the lever lives here in the
 * emitted text.
 *
 * PORTABILITY: `noclone` is documented in GCC's manual since 4.5, and is
 * inside the gcc-dialect mandate this emitter already lives under (computed
 * goto, `__builtin_expect`). MEASURED, because a silently-IGNORED attribute
 * would make this fix a no-op that still looks landed: gcc 15.2.0 accepts it
 * under `-Wattributes -Werror` without an ignored-attribute diagnostic. It
 * also rides the STATIC prefilter, deliberately — measured neutral on the
 * VM+prefilter case (j), and the prefilter is the same split-eligible
 * shape. */
/* [DD-14 wave G] HOW MANY CAPTURE PAIRS THIS ARTIFACT PROMISES, in ONE place
 * both emitters read (`src/gen/emit_vm.c` had the only copy and now calls
 * this). `ncaps` is `ngroups + 1` — group 0 is the whole match — or 1 when the
 * caller asked for no captures.
 *
 * IT USED TO BE THE CONSTANT 1 ON THE DFA PATH, and the comment that said so
 * ("RX_NCAPS > 1 implies the VM — one checkable line") was true only while
 * every capture-bearing pattern forced the VM. Wave G's DEAD-CAPTURE ELISION
 * broke that implication in the direction that matters: a group whose only
 * lexical occurrence sits under a zero-count repeat can never be WRITTEN, so
 * it cannot force an engine — but PCRE2 still COUNTS it and still reports it
 * UNSET (MEASURED on 10.46: `(?(DEFINE)(?<g>a))(?&g)` has CAPTURECOUNT 1 and
 * answers g1 = unset after a match), so the artifact must still promise it.
 * A DFA artifact with `ncaps > 1` is exactly that pattern: every group above 0
 * is PERMANENTLY unset, which `emit_search_head` writes once at entry. */
static int dfa_artifact_ncaps(Ctx *cx)
{
    return cx->want_caps ? (int)cx->ncap + 1 : 1;
}

static void emit_search_head(Ctx *cx, StrBuf *c, const char *fn,
                             const char *storage)
{
    /* [CC-CLANG] `noclone` is a gcc extension (documented since 4.5) with no
     * clang equivalent, so a strange compiler's `-Wattributes -Werror` must
     * not see it at all rather than see it and warn. The `__has_attribute`
     * guard is the general, compiler-name-free way to ask "does THIS
     * toolchain support this attribute" (the same idiom used to detect any
     * attribute across compilers) rather than a clang-specific `#ifdef`, and
     * it degrades safely on a pre-`__has_attribute` compiler via the
     * `#ifndef` fallback definition. */
    sb_puts(c, "/* K24: noclone denies gcc's partial-inlining pass the\n"
               "   .part clone of this function -- the split costs a\n"
               "   measured 1.33x on a scan-bound pattern, with identical\n"
               "   instructions, purely from code placement. Do not remove;\n"
               "   see pcrec docs/dev/known_issues.md K24. Guarded by\n"
               "   __has_attribute: gcc has this attribute, clang does not. */\n"
               "#ifndef __has_attribute\n"
               "# define __has_attribute(x) 0\n"
               "#endif\n"
               "#if __has_attribute(noclone)\n"
               "__attribute__((noclone))\n"
               "#endif\n");
    sb_printf(c, "%sint %s(const unsigned char *subject, size_t subject_length, "
                 "size_t search_from, ptrdiff_t (*capture_spans)[2])\n{\n", storage, fn);
    /* [DD-14 wave G] THE DEAD GROUPS, DECLARED AND PERMANENTLY UNSET. Emitted
     * only when this artifact promises more than the whole match, which on
     * this engine means every promised group is dead (a live one would have
     * forced the VM), so the honest value for all of them is the same constant
     * and it can be written once at entry rather than on each exit. Writing it
     * HERE rather than in `rx_match_caps` is what makes it true for a caller
     * that drives `rx_search` directly, which tests/codegen's K27 fixture
     * does. The failure paths below cast `capture_spans` to void; that stays
     * correct — a redundant cast is not a diagnostic.
     *
     * `fit.chosen == ENGM_DFA` IS LOAD-BEARING AND WAS MEASURED THE HARD WAY.
     * This emitter has TWO customers: it writes the artifact's own engine, and
     * it writes the VM hybrid's internal DFA PREFILTER (`pcrec_emit_dfa_engine`
     * with `static` storage). The prefilter's search function takes the same
     * `capture_spans` parameter and never reports a group — the VM does that —
     * so filling there would put this loop into every capture-bearing VM
     * artifact in the corpus. It did: the first version of this line moved 558
     * of the identity gate's 2442 call-free patterns, including `(((a)))`,
     * which has nothing to do with wave G. The gate caught it on its first
     * run, which is the argument for the gate. */
    if (cx->job->fit.chosen == ENGM_DFA && dfa_artifact_ncaps(cx) > 1) {
        GenNames gn;
        pcrec_gen_names(cx, &gn);
        sb_printf(c,
            "    if (capture_spans)\n"
            "        for (int rx_g = 1; rx_g < %s_NCAPS; rx_g++) {\n"
            "            /* every group this artifact promises is reached only\n"
            "               through a subroutine call or sits under a {0}, so no\n"
            "               match can set it (PCRE2 reports the same) */\n"
            "            capture_spans[rx_g][0] = PCREC_UNSET;\n"
            "            capture_spans[rx_g][1] = PCREC_UNSET;\n"
            "        }\n", gn.upper);
    }
}

static void emit_match_decl(StrBuf *sb, const char *fn)
{
    sb_printf(sb, "ptrdiff_t %s(const rx_ctx *ctx);\n", fn);
}

static void emit_match_caps_decl(StrBuf *sb, const char *fn)
{
    sb_printf(sb, "ptrdiff_t %s(const rx_ctx *ctx, ptrdiff_t (*capture_spans_out)[2]);\n", fn);
}

/* [DEVIATION, REPORTED] spelled `struct rx_info`, not the bare `rx_info`
 * match_api_m4.md §5's literal C snippet shows — see emit_rx_abi_types'
 * comment on the type declaration itself. `<prefix>_info` under the
 * DEFAULT prefix "rx" is the literal identifier "rx_info": a bare typedef
 * of that same name and a variable of that same name cannot coexist in one
 * C scope (verified against gcc: "redeclared as different kind of
 * symbol"), so the type is a tagged struct with no typedef alias and every
 * reference to it — here and in emit_info_def below — uses the tag. This
 * is the ONE of the six [M4.4] ABI types where the collision is reachable,
 * because "info" is the only per-artifact entry-point suffix that is also,
 * verbatim, a whole fixed ABI type name. */
static void emit_info_decl(StrBuf *sb, const char *infoname)
{
    sb_printf(sb, "extern const struct rx_info %s;\n", infoname);
}

/* Every identifier this file derives from --prefix beyond `<prefix>_search`
 * itself (match, match_caps, info) is built the same way: prefix + suffix,
 * arena-owned so it outlives the emission calls that read it. */
static const char *derived_name(Ctx *cx, const char *suffix)
{
    const char *p = cx->opt->prefix;
    size_t sz = strlen(p) + strlen(suffix) + 1;
    char *fn = arena_alloc(&cx->arena, sz);
    snprintf(fn, sz, "%s%s", p, suffix);
    return fn;
}

static const char *engine_entry_name(Ctx *cx) { return derived_name(cx, "_search"); }
static const char *match_entry_name(Ctx *cx)  { return derived_name(cx, "_match"); }
static const char *match_caps_entry_name(Ctx *cx) { return derived_name(cx, "_match_caps"); }
static const char *info_entry_name(Ctx *cx)   { return derived_name(cx, "_info"); }

/* The OS-0 uppercased-prefix spelling (`<PREFIX>_NCAPS` etc., match_api_m4.md
 * §0/§2.1) — every prefix byte is a valid C identifier byte already
 * (validated by compile.c's valid_prefix), so a plain per-byte toupper is
 * exact; no replacement pass is needed the way emit_header's include-guard
 * computation needs one (that one also has to survive an ARBITRARY guard
 * namespace collision, this one does not). */
static void prefix_upper(const char *p, char *buf, size_t bufsz)
{
    size_t i = 0;
    for (; p[i] && i + 1 < bufsz; i++)
        buf[i] = (char)toupper((unsigned char)p[i]);
    buf[i] = 0;
}

/* [M4.4] (match_api_m4.md §11 item 2, D44/A-2): the five fixed-literal ABI
 * types plus rx_renderfn (D44/A-14) — shared, BYTE-FOR-BYTE, by every
 * generated matcher regardless of its own --prefix, which is the entire
 * point of the callout ABI's composability (a compiled matcher links
 * directly as a callout for another). Emitting this block more than once
 * IDENTICALLY in one file is a harmless no-op only by luck of them all
 * matching; emitting it divergently (two prefixes, two headers, one TU) is
 * a hard redefinition error — the same class emit_span_typedef used to
 * document for itself before it retired. So this is ONCE PER FILE, guarded
 * by an include guard that does NOT depend on --prefix, so two
 * differently-prefixed generated headers still agree on the guard name and
 * only the first one's body wins. */
static void emit_rx_abi_types(StrBuf *sb)
{
    sb_puts(sb,
        "#ifndef PCREC_RX_ABI_H\n"
        "#define PCREC_RX_ABI_H\n"
        "\n"
        "typedef struct rx_ctx {\n"
        "    const unsigned char *subject;   /* whole subject, not a slice */\n"
        "    size_t                len;      /* subject length */\n"
        "    size_t                pos;      /* where to match, anchored */\n"
        "    size_t                ncap;     /* capture slots known so far (watermark\n"
        "                                        mid-match; ncaps on completion) */\n"
        "    const ptrdiff_t     (*caps)[2]; /* [start,end); {-1,-1} = unset */\n"
        "    void                 *user;     /* per-binding user data */\n"
        "} rx_ctx;\n"
        "\n"
        "/* returns matched length >= 0 (anchored at ctx->pos), -1 (fail), or a\n"
        " * typed give-up code in [PCREC_ERR_FLOOR, -2] -- one per way the\n"
        " * engine can give up (PCREC_ERR_STEPS/_FRAMES/_WORK/_RECURSE). D49: those\n"
        " * codes PROPAGATE, they are not collapsed to -1, and a caller doing\n"
        " * an exact `== -1` test sees them as distinct values. Values\n"
        " * strictly BELOW PCREC_ERR_FLOOR stay RESERVED for a future abort\n"
        " * semantic; PCREC_ERR_INTERNAL ([DD-14] wave A commit 2, D71\n"
        " * item 1) is its first producer -- the artifact's own\n"
        " * inconsistency check firing, never a resource give-up -- and a\n"
        " * generated call site that invokes an rx_matchfn traps on one.\n"
        " * Self-contained: must accept ctx->ncap == 0, ctx->caps == NULL. */\n"
        "typedef ptrdiff_t rx_matchfn(const rx_ctx *ctx);\n"
        "\n"
        /* [ABI-NS] (D60 + addendum, 2026-08-18): the give-up code space is a
         * pcrec-contract fact, not a per-artifact one -- every artifact means
         * the same thing by -2/-3/-4/-5, so it is spelled ONCE here rather
         * than once per --prefix. Formerly <PREFIX>_ERR_STEPS/_FRAMES/_WORK/
         * _FLOOR (emit_ncaps_macros); DELETED there, no alias -- the house
         * rule D44.2/PCREC_ENC_BYTE already set.
         *
         * [DD-14 wave A, D71 item 1] PCREC_ERR_RECURSE (-5) joins the block
         * and PCREC_ERR_FLOOR moves -4 -> -5 (D49's own re-open clause,
         * exercised): the recursion-depth GIVE-UP CODE is reserved now, but
         * its COUNTER is not in the default artifact (D71 item 1 -- a
         * future [V-H] diagnostic-generation axis). No producer emits
         * PCREC_ERR_RECURSE yet; the code exists so the ABI does not need a
         * second pre-release renumber when module 'recursion' lands one. */
        "#define PCREC_ERR_STEPS   (-2)\n"
        "#define PCREC_ERR_FRAMES  (-3)\n"
        "#define PCREC_ERR_WORK    (-4)\n"
        "#define PCREC_ERR_RECURSE (-5)  /* [DD-14] reserved: no producer "
        "yet (D71 item 1) */\n"
        "#define PCREC_ERR_FLOOR   (-5)  /* give-ups: [FLOOR,-2]; "
        "below: reserved (D49) */\n"
        "\n"
        /* [DD-14 wave A commit 2, D71 item 1] BELOW THE FLOOR: NOT A
         * GIVE-UP. D49 reserves everything strictly below PCREC_ERR_FLOOR
         * for "a future abort semantic" -- this is that semantic's first
         * producer. PCREC_ERR_INTERNAL means the artifact detected its OWN
         * inconsistency (a width analysis disagreeing with what the
         * emitter walked, src/gen/emit_vm.c's lookbehind negative-arm
         * end-check), never a resource give-up. F2's obligation
         * (docs/design/design_callout_abi.md) is exactly this: a composed
         * call site invoking an rx_matchfn must enforce
         * `if (ret < PCREC_ERR_FLOOR) __builtin_trap();`, and trapping on
         * PCREC_ERR_INTERNAL IS the design, not a gap. A TOP-LEVEL search
         * entry is not such a call site, so it still PROPAGATES the code
         * to its own caller rather than trapping -- see the search entry's
         * collapse in emit_vm.c. */
        "#define PCREC_ERR_INTERNAL (-6)  /* [DD-14] below PCREC_ERR_FLOOR: "
        "NOT a give-up, D71 item 1 */\n"
        "\n"
        /* Same D60 move: the caps-array unset sentinel is a pcrec-contract
         * fact, formerly <PREFIX>_UNSET. */
        "#define PCREC_UNSET ((ptrdiff_t)-1)\n"
        "\n"
        "typedef struct rx_callout_ref {\n"
        "    rx_matchfn *fn;\n"
        "    void       *user;\n"
        "} rx_callout_ref;\n"
        "\n"
        "/* Emitted ONLY when a substitution template names it. Renders one\n"
        " * template segment from the same rx_ctx a callout receives. Writes at\n"
        " * most outcap bytes to out; returns the number of bytes produced, or\n"
        " * -1 to fail. Called with out == NULL and outcap == 0, it returns the\n"
        " * length it WOULD produce, writing nothing. */\n"
        "typedef ptrdiff_t rx_renderfn(const rx_ctx *ctx,\n"
        "                              unsigned char *out, size_t outcap);\n"
        "\n"
        "typedef struct {\n"
        "    const char *name;\n"
        "    int         number;\n"
        "    int         slot;   /* caps[] index this entry delivers, or -1 if\n"
        "                           this build delivers no slot for it */\n"
        "    const char *ref;    /* NULL/empty for the primary's own groups */\n"
        "} rx_group_entry;\n"
        "\n"
        /* NOT `typedef struct { ... } rx_info;` like the other five ABI
         * types above (a deliberate, REPORTED deviation from the literal
         * spelling in match_api_m4.md §5 — see the emit_info_decl/
         * emit_info_def comment below for why: a bare typedef alias here
         * would make every DEFAULT-prefix artifact's own `<prefix>_info`
         * instance, "rx_info", an illegal redeclaration of this type's own
         * name in the same scope). `struct rx_info` is a TAG, which C keeps
         * in a namespace separate from ordinary identifiers (typedef names,
         * variable names, function names) — so a struct TAGGED rx_info and
         * a variable NAMED rx_info coexist with no conflict, verified
         * directly against gcc. */
        "struct rx_info {\n"
        "    unsigned      abi;             /* layout version */\n"
        "    uint64_t      flags;           /* PCREC_* option bits, as compiled */\n"
        "    int           encoding;        /* PCREC_ENC_* */\n"
        "    int           ncaps;           /* == this artifact's own\n"
        "                                       <PREFIX>_NCAPS: its caps[]\n"
        "                                       slot count, all-in */\n"
        "    int           ngroups;         /* capturing groups in the pattern's\n"
        "                                       own TEXT (a lexical fact) */\n"
        "    int           nnames;          /* entries in groups[], named only */\n"
        "    unsigned      engine;          /* PCREC_ENGINE_DFA=1 /\n"
        "                                       PCREC_ENGINE_VM=2 */\n"
        "    int64_t       step_budget;     /* -1 = none */\n"
        "    int64_t       work_budget;     /* -1 = none. The THIRD bound (D47\n"
        "                                       SECOND ADDENDUM): per-iteration\n"
        "                                       forward work the fail label\n"
        "                                       never sees, in work units. A\n"
        "                                       step is a backtrack resumption\n"
        "                                       and is counted separately. */\n"
        "    int64_t       frame_capacity;  /* -1 = unbounded */\n"
        "    int64_t       subject_ceiling; /* 0 = unset/not applicable */\n"
        /* [DD-14.FB] (D71 item 2, spec §10.4) THE SIZING SURFACE'S FOUR
         * FACTS, for a consumer that has no C header to read the macros
         * from -- an FFI, ctypes or dlopen binding, which is exactly the
         * consumer most likely to want a large reservation and the one
         * that cannot use <PREFIX>_RESUME_FRAME_SIZE. All four read 0 on a
         * DFA artifact, which has neither array.
         *
         * `resume_frames` IS NOT REDUNDANT WITH `frame_capacity` two lines
         * up, and the difference is the sentinel: `frame_capacity` answers
         * "what bound does this artifact enforce", reading -1 for "no bound
         * at all", where this answers "how many frames does the default
         * storage hold", reading 0 for "there is no such storage". A
         * caller sizing a buffer needs the second question. */
        "    int64_t       resume_frames;   /* stamped DEFAULT capacity, in\n"
        "                                       frames; 0 = no resume stack */\n"
        "    int64_t       trail_frames;    /* ditto, in trail entries */\n"
        "    int32_t       resume_frame_size; /* bytes per resume frame */\n"
        "    int32_t       trail_frame_size;  /* bytes per trail entry */\n"
        "    const char           *pattern;     /* source pattern text */\n"
        "    size_t                pattern_len; /* companion length (K9-proof) */\n"
        "    const rx_group_entry *groups;       /* sorted, bsearch-able */\n"
        "    const char           *engine_why;   /* forcing construct/reason, or NULL */\n"
        /* [DD-13c] (D40 addendum) THE SELECTION FACTS' RUNTIME MIRRORS, so a
         * consumer with no header to read the macros from -- dlopen, an FFI
         * binding, a multi-artifact linker walking several `<prefix>_info`
         * symbols -- can read them the way it already reads `engine` and
         * `engine_why`. APPENDED at the END of the struct, after the three
         * pointers, so no existing member's offset moves; the `abi` bump
         * announces the growth (see emit_info_def's abi comment).
         *
         * STRINGS AND NOT ENUMS, matching `engine_why` rather than `engine`:
         * the value sets are the macros' value sets, the macros are strings,
         * and one derivation feeding two spellings of the same fact is the
         * whole point. A consumer compares with strcmp; the sets are closed
         * and docs/spec/match_api.md S6.3 lists them. */
        "    const char           *scan;         /* the DFA scan this artifact\n"
        "                                           CONTAINS: \"unanchored\" /\n"
        "                                           \"attempt\" / \"empty\",\n"
        "                                           mirroring <PREFIX>_DFA_SCAN.\n"
        "                                           NULL when there is none --\n"
        "                                           i.e. on a VM artifact that is\n"
        "                                           not a hybrid. A non-NULL\n"
        "                                           value on a VM artifact IS\n"
        "                                           \"this is a hybrid\". */\n"
        "    const char           *prefilter;    /* this artifact's CANDIDATE-START\n"
        "                                           mechanism, in whichever\n"
        "                                           engine's vocabulary applies:\n"
        "                                           the DFA's five values\n"
        "                                           (<PREFIX>_DFA_PREFILTER) when\n"
        "                                           `scan` is non-NULL, and the\n"
        "                                           VM's \"none\"\n"
        "                                           (<PREFIX>_VM_PREFILTER) when\n"
        "                                           it is NULL. Never NULL. */\n"
        /* [ENG-ABS] AXIS G's runtime mirror, appended after `prefilter` on the
         * same terms and for the same reason (a consumer with no header). It
         * is a fact about the artifact's `<prefix>_match` ENTRY, which is a
         * different question from `scan`'s: NULL means "this artifact's
         * anchored entry is not one this axis describes", which is every VM
         * artifact INCLUDING a hybrid — a hybrid's `_match` is the VM's own
         * anchored body, not a filtered search. */
        /* THE COMMENT SITS ABOVE THE MEMBER, NOT AFTER IT, and that is a
         * MEASURED choice rather than a style one. `tests/lib/size_count.sh`s
         * comment classifier is LINE-BASED: it recognises a line that STARTS a
         * block and tracks the block to its end, so a comment ABOVE a member
         * costs zero counted bytes — while the continuation lines of a TRAILING
         * multi-line comment do not start a block and are counted as CODE.
         * Measured at this row: the trailing shape put +691 B of prose into
         * every artifact in the corpus (2,875 of them), the above-the-member
         * shape puts in 0. `scan` and `prefilter` above keep the trailing shape
         * — changing them is not this row's to do, and the observation is
         * recorded in docs/design/anchored_match_unwrapped.md §8 instead. */
        "    /* [ENG-ABS] HOW <prefix>_match answers: \"unwrapped\" (its own\n"
        "       anchored machine, run from ctx->pos) or \"search-filter\" (the\n"
        "       unanchored search, with non-ctx->pos starts rejected),\n"
        "       mirroring <PREFIX>_DFA_MATCH. NULL on every artifact whose\n"
        "       _match this engine did not write. */\n"
        "    const char           *match_form;\n"
        /* [DD-13b.W1.2] THE ARTIFACT'S OWN NAME, and the count of every row
         * in `groups[]`. APPENDED AT THE END, after `match_form`, so no
         * existing member's offset moves — the [DD-13c] append precedent
         * rather than abi 2's and abi 3's insertions; the `abi` bump
         * announces the growth either way.
         *
         * `name` IS NEVER NULL. A `.rxt` source's `target` names a
         * definition and the block it names may carry a `name`; this is
         * that name, and it is the artifact's answer to "what am I" as
         * distinct from `<prefix>`'s "what are my symbols called". A build
         * that names nothing stamps its own prefix (Frank, format_design
         * §6.3), so a consumer needs no NULL case and the emitter has none
         * to get wrong.
         *
         * `nentries` IS NOT `nnames` RESTATED, and the difference is a
         * SHIPPED CONTRACT rather than a nicety. §6's caller algorithm
         * bsearches `groups[0 .. nnames)` and walks a run of equal names;
         * once composition injects a definition's own named groups
         * ([DD-13b.W1.3]) the array grows rows the primary did not declare,
         * sorted BELOW the primary's by the (ref-is-NULL, name, number)
         * key, so the primary's rows stay a genuine PREFIX and `nnames`
         * keeps its meaning exactly. `nentries` is how a caller reaches the
         * rest. Today no composer exists, so every artifact stamps
         * `nentries == nnames`; it lands NOW because it rides this `abi`
         * bump, and the alternative is a second bump for one integer. */
        /* THE COMMENTS SIT ABOVE THEIR MEMBERS, NOT AFTER THEM, for the
         * MEASURED reason [ENG-ABS] states at `match_form` twenty lines up —
         * and this row learned it the way the note predicts rather than by
         * reading it. `tests/lib/size_count.sh`'s classifier is LINE-BASED:
         * a line that STARTS a comment block is tracked to its end, so a
         * comment above a member costs ZERO counted bytes, while the
         * CONTINUATION lines of a trailing multi-line comment start no block
         * and are counted as CODE.
         *
         * The first version of these two members used the trailing shape and
         * put EIGHT prose lines into every artifact in the tree. That is a
         * K-INVARIANT constant added to both sides of [ART-SIZE]'s
         * materiality ratio, which pulls it toward 1 — exactly the mechanism
         * `tests/codegen/run_size_term.sh` §9's own header warns about for
         * the DFA prefilter's K-invariant tables — and it was enough to push
         * that cell's 0.7475 witness over the 75 % bar. The check caught it;
         * the two cells bracket the constant to 0.73 %, so there was very
         * little room to be wrong in. */
        "    /* [DD-13b.W1.2] this artifact's own name: the `.rxt` block's\n"
        "       `name` when a source named one, the <prefix> otherwise.\n"
        "       NEVER NULL. */\n"
        "    const char           *name;\n"
        "    /* [DD-13b.W1.2] rows in groups[], ALL of them. `nnames` counts\n"
        "       the PRIMARY pattern's own, which are a PREFIX of the array;\n"
        "       the two are equal on every artifact pcrec emits today. */\n"
        "    int                   nentries;\n"
        /* [OPT-5 STEP 2] AXIS J's runtime mirror, APPENDED AT THE END — after
         * `nentries`, NOT after `match_form`.
         *
         * THE [DD-13c] DISCIPLINE IS "APPEND AT THE END SO NO EXISTING
         * MEMBER'S OFFSET MOVES", and its own statement twenty lines up says
         * "after `match_form`" because `match_form` WAS the last member when
         * that was written. `name` and `nentries` now follow it, so taking
         * that phrasing literally would INSERT before them and move their
         * offsets — the exact thing the discipline exists to prevent. The
         * discipline wins over its own dated wording.
         *
         * ITS GUARD IS `pcrec_artifact_has_dfa_scan` AND DELIBERATELY NOT
         * `match_form`'s. `match_form` is guarded on `fit.chosen == ENGM_DFA`
         * because a hybrid's `<prefix>_match` is the VM's own anchored body,
         * which axis G does not describe. Axis J describes
         * `<prefix>_search`'s post-loop block, which a hybrid DOES contain —
         * it inlines this emitter's whole scan — so this field follows
         * `scan`/`prefilter`'s guard instead, exactly as the `_DFA_START`
         * macro follows `_DFA_SCAN_EDGE`'s placement. Copying `match_form`'s
         * guard here would stamp NULL on every hybrid.
         *
         * THE COMMENT SITS ABOVE THE MEMBER for the MEASURED reason
         * [ENG-ABS] and [DD-13b.W1.2] both state above: `tests/lib/
         * size_count.sh`'s classifier is LINE-BASED, so a comment above a
         * member costs zero counted bytes while the CONTINUATION lines of a
         * trailing multi-line comment are counted as CODE in every artifact
         * in the corpus. */
        "    /* [OPT-5 STEP 2] HOW <prefix>_search recovers the match START:\n"
        "       \"pinned\" (the start is search_from by compile-time proof, and\n"
        "       this artifact carries no reverse machine at all) or\n"
        "       \"reverse-pass\" (the second, backwards scan), mirroring\n"
        "       <PREFIX>_DFA_START. The two forms are ANSWER-IDENTICAL and\n"
        "       differ only in cost. NON-NULL on every artifact that CONTAINS\n"
        "       a DFA scan, a VM HYBRID INCLUDED -- a hybrid inlines this same\n"
        "       search body as its prefilter, so unlike match_form the guard\n"
        "       is \"has a DFA scan\" and not \"the DFA emitter wrote _match\".\n"
        "       NULL only on a plain VM artifact. */\n"
        "    const char           *search_form;\n"
        "};\n"
        "\n"
        /* [ABI-NS] (D60 addendum): rx_info.engine's number-only contract
         * (docs/spec/match_api.md S6: "no such constant is #defined
         * anywhere") gains names. The internal ENGM_* enum
         * (src/opt/select_engine.c) stays internal -- these two are the
         * emitted spelling, pinned to today's stamped numbers (this NAMES
         * the existing contract, it does not renumber it). */
        "#define PCREC_ENGINE_DFA 1\n"
        "#define PCREC_ENGINE_VM  2\n"
        "\n"
        /* [ABI-NS] (D60): the D46 stamp BIT constants -- which bit means
         * which rung/strategy/prune choice is a pcrec-contract fact, so the
         * NAMED bits move here, unprefixed. The per-artifact OR'd MASKS
         * (<PREFIX>_VM_RUNGS/_STRATS/_PRUNES) are a property of THIS
         * artifact (which bits it actually uses) and stay per-prefix,
         * emitted at their existing site in emit_vm.c. Emitted
         * unconditionally, including on a DFA-only artifact that never
         * uses them, for the same reason PCREC_ERR_STEPS is: the names are
         * part of pcrec's contract whether or not this artifact's engine
         * can produce the value. Values verbatim from emit_vm.c's
         * vm_rung_bit[]/vm_strat_bit[]/vm_prune_bit[] arrays, which build
         * the per-artifact masks from these same constants. */
        "#define PCREC_VM_RUNG_CURSOR           0x1u\n"
        "#define PCREC_VM_RUNG_FRAMES_BOUNDED   0x2u\n"
        "#define PCREC_VM_RUNG_FRAMES_UNBOUNDED 0x4u\n"
        "#define PCREC_VM_RUNG_REVDET           0x8u\n"
        "#define PCREC_VM_RUNG_COUNTER          0x10u\n"
        "#define PCREC_VM_STRAT_POSSESSIVE      0x1u\n"
        "#define PCREC_VM_STRAT_BACKTRACKING    0x2u\n"
        "#define PCREC_VM_PRUNE_CLAMPED         0x1u\n"
        "#define PCREC_VM_PRUNE_UNCLAMPED       0x2u\n"
        "\n"
        /* [M5-SEAM] The RESIDUAL entries get a pointer from here and their
         * full contract at their own declaration (src/gen/enc/). This block
         * is emitted ONCE PER FILE under a prefix-independent guard, so it
         * must stay independent of BOTH axes it sits across: `<prefix>` is a
         * placeholder here exactly as `<PREFIX>` is above, and the text must
         * name no particular ENCODING either — two artifacts compiled for
         * different encodings into one TU share this block, and only the
         * first copy survives the guard. What is per-encoding is the
         * residual's BODY, which is not here. */
        "/* Every generated artifact also exports one RESIDUAL entry per\n"
        " * encoding (pcrec DD-12/D58), <prefix>-scoped and therefore declared\n"
        " * outside this shared block:\n"
        " *\n"
        " *   size_t <prefix>_next_pos(const unsigned char *s, size_t n,\n"
        " *                            size_t pos);\n"
        " *\n"
        " * It returns the next CHARACTER boundary strictly after pos (every\n"
        " * position >= n counts as a boundary), and it is the one place an\n"
        " * artifact's byte-vs-character distinction lives: a find-all loop\n"
        " * advances past a zero-length match with it and needs no change when\n"
        " * the same pattern is compiled for another encoding. Full contract:\n"
        " * that declaration's own comment, and pcrec's\n"
        " * docs/spec/match_api.md S3.1. */\n"
        "\n"
        "#endif /* PCREC_RX_ABI_H */\n");
}

/* [M4.4] (match_api_m4.md §2.1/§9 item 9): the caps-array surface's named
 * constant — PER-PREFIX, since two artifacts compiled with different
 * --prefix legitimately have different RX_NCAPS values once [M4.5] lands.
 * `RX_NCAPS` is 1 on every artifact this DFA-only emitter produces (D42.2):
 * a DFA-compiled pattern never promises more than the whole-match slot,
 * capture-bearing or not.
 *
 * [ABI-NS] (D60, 2026-08-18): this function used to also emit RX_UNSET and
 * the search entry's reserved give-up codes (RX_ERR_STEPS/_FRAMES/_WORK/
 * _FLOOR) here, per-prefix. D60 ruled those four PLUS the unset sentinel
 * are pcrec-CONTRACT facts, not per-artifact ones — every artifact means
 * the same thing by -2/-3/-4 and by ((ptrdiff_t)-1) — so they moved to the
 * shared PCREC_RX_ABI_H block (`emit_rx_abi_types`, above) as
 * PCREC_ERR_STEPS/_FRAMES/_WORK/_FLOOR and PCREC_UNSET, and were DELETED
 * here: no alias, the house rule D44.2/PCREC_ENC_BYTE already set. What
 * stays per-prefix is exactly RX_NCAPS — the one member of this family
 * whose VALUE genuinely varies per artifact. */
static void emit_ncaps_macros(StrBuf *sb, const char *upper, int ncaps)
{
    sb_printf(sb, "#define %s_NCAPS %d\n", upper, ncaps);
}

/* [DD-14.FB] (D71 item 2, spec §10.4) THE CALLER-BUFFER SIZING SURFACE: five
 * per-prefix macros and the `<prefix>_buffers` descriptor, emitted wherever a
 * consumer's declarations live (the .h when split, the .c when
 * self-contained) and on EVERY artifact, both engines.
 *
 * TWO OF THE FIVE MACROS ALREADY EXISTED AND MOVE HERE FROM emit_vm.c's .c
 * body. `<PREFIX>_RESUME_FRAMES`/`_TRAIL_FRAMES` were `.c`-private, which was
 * right while they only DOCUMENTED what the artifact does; they are now
 * arithmetic a caller has to do before it can call `<prefix>_search_in`, so
 * they have to be where a caller can read them. That move is the emitted-text
 * change §10.8 announces, and it is the reason this function is called from
 * the prologue rather than from the VM body: the header is written before the
 * VM's own text begins.
 *
 * THE THREE SIZE/ALIGN MACROS ARE STAMPED LITERALS, NOT `sizeof` EXPRESSIONS,
 * and that is forced rather than chosen. The two structs they measure are
 * `.c`-private (design §5.4: exporting the frame layout would pin, as ABI, a
 * layout three axes already move), so a `sizeof` in the header would name a
 * type the header does not declare. What keeps a stamped literal honest is
 * that the artifact CHECKS it: emit_vm.c emits a `_Static_assert` beside the
 * struct definitions comparing each macro against the real `sizeof`, so a
 * number computed for the wrong target model -- or stamped from the wrong
 * struct, sabotage row S-FB6 -- is a loud compile error in the artifact,
 * never a silent under-allocation in the caller.
 *
 * THE DESCRIPTOR IS PER-PREFIX, NOT ONE OF THE FIXED-LITERAL `rx_*` ABI TYPES
 * (spec §10.2). Those six are literal so that differently-prefixed matchers
 * COMPOSE; a buffer is the opposite case, because a resume frame's size
 * differs between artifacts (24 bytes call-free, 40 call-bearing, MEASURED),
 * and a fixed-literal spelling would advertise an interchangeability that
 * does not exist. So it lives here, beside `<PREFIX>_NCAPS`, rather than in
 * the shared PCREC_RX_ABI_H block. */
static void emit_buffers_surface(StrBuf *sb, const char *upper, const char *prefix,
                                 const BufSurface *bs)
{
    sb_printf(sb,
        "\n/* [DD-14.FB] The caller-provided working storage (spec \302\24710).\n"
        " *\n"
        " *   %s_RESUME_FRAMES / _TRAIL_FRAMES   the capacities this artifact\n"
        " *       uses when it supplies the storage itself -- a DEFAULT, not a\n"
        " *       limit. 0 on a DFA artifact, which has neither array.\n"
        " *   %s_RESUME_FRAME_SIZE / _TRAIL_FRAME_SIZE   bytes per frame and\n"
        " *       per trail entry FOR THIS ARTIFACT. The layouts themselves are\n"
        " *       private; this is the arithmetic that replaces them.\n"
        " *   %s_BUFFER_ALIGN   the alignment both regions require. Storage\n"
        " *       from any ordinary allocator, mapping or object declaration\n"
        " *       already satisfies it; the macro is for a caller carving a\n"
        " *       region out of an arena.\n"
        " */\n",
        upper, upper, upper);
    sb_printf(sb, "#define %s_RESUME_FRAMES %lld\n", upper, bs->resume_frames);
    sb_printf(sb, "#define %s_TRAIL_FRAMES %lld\n", upper, bs->trail_frames);
    sb_printf(sb, "#define %s_RESUME_FRAME_SIZE %d\n", upper, bs->resume_frame_size);
    sb_printf(sb, "#define %s_TRAIL_FRAME_SIZE %d\n", upper, bs->trail_frame_size);
    sb_printf(sb, "#define %s_BUFFER_ALIGN %d\n\n", upper, bs->align);
    sb_printf(sb,
        "/* Where one match attempt's working storage lives. Pass NULL to any\n"
        " * <prefix>_*_in entry and it is EXACTLY a call to the un-suffixed\n"
        " * sibling, with this artifact's own stamped default storage on that\n"
        " * entry's stack frame.\n"
        " *\n"
        " * THE COUNTS ARE CAPACITIES, NOT BYTE SIZES: `nframes` is how many\n"
        " * FRAMES the region holds, `ntrail` how many trail ENTRIES. A caller\n"
        " * that reserved `bytes` gets `bytes / %s_RESUME_FRAME_SIZE` and\n"
        " * `bytes / %s_TRAIL_FRAME_SIZE` -- BUT CHECK THE SIZE FIRST: a stamped\n"
        " * size of 0 means this artifact's engine takes no buffers at all (every\n"
        " * DFA artifact stamps 0), so dividing by it is a division by zero. Pass\n"
        " * NULL on such an artifact; the _in entries accept a descriptor and\n"
        " * ignore it either way. Both regions are required when the\n"
        " * descriptor is non-NULL, and both are pure scratch: their contents\n"
        " * after any call are unspecified and no call reads what a previous\n"
        " * one left. Two concurrent calls must not share one region -- that is\n"
        " * a race in the caller's code exactly as a shared caps array is. */\n"
        "typedef struct {\n"
        "    void   *frames;    /* storage for resume frames */\n"
        "    size_t  nframes;   /* capacity in FRAMES, not bytes */\n"
        "    void   *trail;     /* storage for trail entries */\n"
        "    size_t  ntrail;    /* capacity in ENTRIES, not bytes */\n"
        "} %s_buffers;\n",
        upper, upper, prefix);
}

/* The three `_in` DECLARATIONS. Kept beside the three un-suffixed ones above
 * (emit_search_decl and friends), which they mirror argument for argument
 * plus the descriptor -- spec §10.2's "its un-suffixed sibling in every
 * respect, plus one argument naming where the working storage lives". */
static void emit_search_in_decl(StrBuf *sb, const char *fn, const char *prefix)
{
    sb_printf(sb, "int %s_in(const unsigned char *subject, size_t subject_length, "
                  "size_t search_from, ptrdiff_t (*capture_spans)[2], "
                  "const %s_buffers *buffers);\n", fn, prefix);
}

static void emit_match_in_decl(StrBuf *sb, const char *fn, const char *prefix)
{
    sb_printf(sb, "ptrdiff_t %s_in(const rx_ctx *ctx, const %s_buffers *buffers);\n",
              fn, prefix);
}

static void emit_match_caps_in_decl(StrBuf *sb, const char *fn, const char *prefix)
{
    sb_printf(sb, "ptrdiff_t %s_in(const rx_ctx *ctx, ptrdiff_t (*capture_spans_out)[2], "
                  "const %s_buffers *buffers);\n", fn, prefix);
}

/* The inert shape (spec §10.4): four sizing facts at 0, alignment at 1.
 *
 * ALIGNMENT 1 RATHER THAN 0 is the one value §10.4 does not spell, and 0 is
 * the wrong answer for a reason worth writing down: a caller carving a region
 * out of an arena rounds its cursor UP to the macro, and rounding up to 0 is
 * a division by zero. 1 is the alignment every pointer already satisfies,
 * which is the truthful statement for an artifact with no regions to align. */
BufSurface pcrec_bufsurface_inert(void)
{
    BufSurface bs;
    bs.resume_frames = 0; bs.trail_frames = 0;
    bs.resume_frame_size = 0; bs.trail_frame_size = 0;
    bs.align = 1;
    return bs;
}

/* [M4.4] (match_api_m4.md §3): the match-here entry, exported UNCONDITIONALLY
 * on every generated matcher (F1/F2) and RETROFITTED onto the existing DFA
 * search — nothing at [M4.4] requires a second, genuinely-anchored
 * automaton. `<prefix>_search`'s own leftmost-first priority already makes
 * this exact: a match beginning at ctx->pos exists iff the search's
 * highest-priority thread (which always tries "match starting here" before
 * "skip a byte and try later", by construction of the unanchored wrap) finds
 * one, so checking the reported start against ctx->pos is not an
 * approximation of anchored matching, it IS anchored matching, reusing the
 * existing forward+reverse walk rather than a new one.
 *
 * [K28 fix, 2026-08-19, repair slice] `caps` IS INITIALIZED, and the
 * initializer is not defensive padding — it is the only shape that compiles.
 * When the pattern's DFA is a single dead state, `<prefix>_search` always
 * returns 0, gcc -O1 inlines it here, and then reports this array as
 * maybe-uninitialized even though `found != 1` short-circuits the read. The
 * warning is bogus (the read is unreachable) but the artifact is source
 * SOMEONE ELSE compiles, and the harness's own GENCFLAGS are
 * `-O1 -Wall -Wextra -Werror`, so it is a build failure rather than a
 * blemish. Two things measured before choosing this:
 *   - it fires at -O1 ONLY: -O0, -O2, -O3 and -Os are all clean, measured,
 *     all five. Why only -O1 was not established and is not asserted here;
 *     what matters is that -O1 is exactly tests/harness/run.sh's default
 *     GENCFLAGS, so "compile it at a different level" is not a fix.
 *   - SPLITTING the `||` into two `if`s does NOT silence it. The dominance
 *     gcc cannot see is not the short-circuit; restructuring the test is not
 *     available and the initializer is the smallest thing that works.
 * The same three lines are owed by `emit_match_caps_def` and
 * `pcrec_emit_main` below, which have the identical shape and warn for the
 * identical reason -- the `-Werror` build merely stopped at the first one.
 * Full history, the six corpus spellings it cost, and the repro:
 * docs/dev/known_issues.md K28. */
static void emit_match_def(StrBuf *c, const char *matchfn, const char *searchfn,
                            const char *upper)
{
    sb_printf(c,
        "/* D49: the give-up codes PROPAGATE rather than collapsing to -1.\n"
        " * Unreachable on this engine — a DFA artifact has no counter to\n"
        " * exhaust — but written uniformly on purpose: the contract of\n"
        " * rx_matchfn is one contract, and a wrapper that discards codes it\n"
        " * merely happens never to see is the shape that goes wrong when a\n"
        " * later engine shares this emitter. */\n"
        "ptrdiff_t %s(const rx_ctx *ctx)\n"
        "{\n"
        "    /* Initialized: gcc -O1 false maybe-uninitialized (pcrec K28). */\n"
        "    ptrdiff_t capture_spans[%s_NCAPS][2] = {{0}};\n"
        "    int found = %s(ctx->subject, ctx->len, ctx->pos, capture_spans);\n"
        "    if (found < 0) return (ptrdiff_t)found;\n"
        "    if (found != 1 || (size_t)capture_spans[0][0] != ctx->pos) return -1;\n"
        "    return capture_spans[0][1] - capture_spans[0][0];\n"
        "}\n",
        matchfn, upper, searchfn);
}

/* [M4.4] (match_api_m4.md §3.1, D41.4): the anchored capture-DELIVERING
 * sibling of <prefix>_match — same anchoring test, plus a capture_spans_out
 * parameter that gets every RX_NCAPS pair on success and is left UNTOUCHED
 * on failure (A-8's "untouched wins" rule, shared with <prefix>_search). At
 * [M4.4] RX_NCAPS is always 1, so capture_spans_out[0] is the only slot ever
 * written; the loop is written against the macro rather than hardcoded so
 * nothing here needs revisiting when [M4.5] grows it. */
static void emit_match_caps_def(StrBuf *c, const char *fn, const char *searchfn,
                                 const char *upper)
{
    sb_printf(c,
        "ptrdiff_t %s(const rx_ctx *ctx, ptrdiff_t (*capture_spans_out)[2])\n"
        "{\n"
        "    /* Initialized: gcc -O1 false maybe-uninitialized (pcrec K28). */\n"
        "    ptrdiff_t capture_spans[%s_NCAPS][2] = {{0}};\n"
        "    int found = %s(ctx->subject, ctx->len, ctx->pos, capture_spans);\n"
        "    if (found < 0) return (ptrdiff_t)found;\n"
        "    if (found != 1 || (size_t)capture_spans[0][0] != ctx->pos) return -1;\n"
        "    if (capture_spans_out) {\n"
        "        for (int k = 0; k < %s_NCAPS; k++) {\n"
        "            capture_spans_out[k][0] = capture_spans[k][0];\n"
        "            capture_spans_out[k][1] = capture_spans[k][1];\n"
        "        }\n"
        "    }\n"
        "    return capture_spans[0][1] - capture_spans[0][0];\n"
        "}\n",
        fn, upper, searchfn, upper);
}

/* [DD-14.FB] (D71 item 2, spec §10.4) THE THREE `_in` ENTRIES ON A DFA
 * ARTIFACT: present, and INERT.
 *
 * WHY A DFA ARTIFACT HAS THEM AT ALL. §6.3's rule is that per-artifact
 * CAPACITY/ACTIVITY macros are VM-only, because they report what an artifact
 * DID and a DFA artifact has no such activity to report. These entries are
 * the other kind of fact: they are what a CALLER needs in order to call the
 * artifact, and which engine a pattern selects is not the caller's choice —
 * `select_engine.c` makes it, and it can change when the pattern changes or
 * when an optimisation lands. §6.3 used to close with the warning this
 * avoids: "a consumer that `#if`s on `RX_ENGINE` is writing code that does
 * not compile against half the artifacts pcrec produces". So the surface is
 * unconditional and the DEPARTURE is deliberate (spec §10.4 rules it).
 *
 * [DD-13], 2026-08-25: THAT WARNING NO LONGER APPLIES TO `RX_ENGINE` ITSELF,
 * and this comment is left standing rather than deleted because the warning
 * is still the ARGUMENT. §6.3 now splits the D46 family into (a) SELECTION
 * FACTS, unconditional on every artifact — which is what this surface already
 * was, two years of `_in` entries early — and (b) the capacity/activity
 * macros, still VM-only. `RX_ENGINE` moved to (a) for exactly the reason
 * stated above; the warning holds verbatim for every (b) macro.
 *
 * WHY THEY IGNORE THE DESCRIPTOR RATHER THAN REJECTING IT. This engine never
 * backtracks: it has no resume stack, no trail, and no capacity to exhaust —
 * which is why it can never return `PCREC_ERR_FRAMES` either. A descriptor
 * therefore names storage there is nothing to put in, and the honest answer
 * is the un-suffixed sibling's, unchanged. Refusing a non-NULL descriptor
 * would make the same call site engine-dependent again, which is the whole
 * thing this shape exists to prevent.
 *
 * THE DELEGATION RUNS `_in` -> UN-SUFFIXED here exactly as it does on a VM
 * artifact (design §5.2), so the direction is one rule across both engines
 * rather than a coincidence that holds twice. */
static void emit_in_entry_defs(StrBuf *c, const char *searchfn, const char *matchfn,
                               const char *matchcapsfn, const char *prefix)
{
    sb_printf(c,
        "/* [DD-14.FB] The caller-buffer entries. This engine keeps no working\n"
        " * storage between bytes -- it cannot backtrack, so it has no resume\n"
        " * stack and no trail to point anywhere -- so each of these is exactly\n"
        " * its un-suffixed sibling and the descriptor is unused. Emitted\n"
        " * anyway, on every artifact both engines produce, so one caller call\n"
        " * site compiles and behaves the same whichever engine the pattern\n"
        " * happened to select (spec S10.4). */\n"
        "int %s_in(const unsigned char *subject, size_t subject_length, size_t search_from,\n"
        "          ptrdiff_t (*capture_spans)[2], const %s_buffers *buffers)\n"
        "{\n"
        "    (void)buffers;\n"
        "    return %s(subject, subject_length, search_from, capture_spans);\n"
        "}\n"
        "\n"
        "ptrdiff_t %s_in(const rx_ctx *ctx, const %s_buffers *buffers)\n"
        "{\n"
        "    (void)buffers;\n"
        "    return %s(ctx);\n"
        "}\n"
        "\n"
        "ptrdiff_t %s_in(const rx_ctx *ctx, ptrdiff_t (*capture_spans_out)[2],\n"
        "                const %s_buffers *buffers)\n"
        "{\n"
        "    (void)buffers;\n"
        "    return %s(ctx, capture_spans_out);\n"
        "}\n",
        searchfn, prefix, searchfn,
        matchfn, prefix, matchfn,
        matchcapsfn, prefix, matchcapsfn);
}

/* [M4.4] (match_api_m4.md §5, D43.1/D44.5): the static reflection structure,
 * one per artifact, `.rodata` only. Every FIELD lands at [M4.4]; several are
 * trivially empty/default until later substeps populate them (groups/nnames
 * until module `named-groups`; step_budget/frame_capacity/subject_ceiling
 * until [M4.5]'s counter mechanism; engine_why until a construct forces a
 * non-default engine, which cannot happen before the VM exists) — the same
 * shape the freestanding group index had before D43.1 folded it in here.
 *
 * [M4.5b] The five fields whose "trivially default until later" window has
 * now closed for the VM — engine, engine_why, step_budget, frame_capacity,
 * subject_ceiling — come in through `st` instead of being hardcoded, and the
 * DFA path passes exactly the constants that were here before, so its output
 * is unchanged byte for byte. The VM's values are what the artifact ACTUALLY
 * ENFORCES, not what was requested (engine_m4.md §4.6's stamping rule and
 * D44.1's honest stamped ceiling): a caller must be able to learn the limit
 * from the artifact rather than by triggering PCREC_ERR_FRAMES. */
typedef struct {
    int         engine;          /* ENGM_DFA=1 / ENGM_VM=2 */
    const char *engine_why;      /* free text, or NULL */
    long long   step_budget;     /* -1 = none */
    long long   work_budget;     /* -1 = none (the D47 SECOND ADDENDUM bound) */
    long long   frame_capacity;  /* -1 = unbounded */
    long long   subject_ceiling; /* 0 = unset/not applicable */
    /* [DD-14.FB] the same four facts the header's macros carry, for a
     * consumer with no header. Never NULL: both emitters pass one, the DFA
     * path passing `pcrec_bufsurface_inert()`. */
    const BufSurface *bufs;
} InfoStamp;

/* [M6.3] the sort key for rx_info.groups: strcmp on the NAME. Chosen to
 * match PCRE2's own PCRE2_INFO_NAMETABLE ordering — measured directly
 * (tests/probes/probe_named_groups.c: a 3-name pattern declared
 * zeta/alpha/mu by paren order comes back alpha/mu/zeta) rather than
 * invented, which is what makes the array bsearch-able by name exactly as
 * docs/spec/match_api.md §6 always said it would be, and settles the
 * paragraph that section left open (docs/dev/decisions.md's [M6.3] entry). */
/* [M6.5.2] THE NUMBER TIEBREAK, AND IT IS A CORRECTNESS REQUIREMENT rather
 * than the reproducibility nicety it would have been before `(?J)` existed.
 *
 * MEASURED (backrefs_design.md §8.2, `PCRE2_INFO_NAMETABLE` read for ten
 * patterns): libpcre2's own table is sorted (name ASCENDING, then number
 * ASCENDING) — `(?<z>1)(?<a>2)(?<z>3)(?<a>4)` comes back a/2, a/4, z/1, z/3 —
 * so this is a reproduction of an external precedent, not a pcrec convention.
 *
 * WHY WITHOUT IT THE TABLE ENCODES THE WRONG RULE, which is what R32's
 * re-check found by reading two sites together. `mod_named_groups.c` PREPENDS
 * each declaration onto `Ctx.named_groups` and the loop below walks that list
 * FROM THE HEAD, so the array reaching `qsort` is in DESCENDING group number.
 * Under a name-only comparator and a STABLE sort — glibc's is a merge sort —
 * the emitted rows for one name would come out (name asc, number DESC), and
 * `docs/spec/match_api.md` §6's caller algorithm (bsearch, walk BACK to the
 * run's first row, then FORWARD to the first participating one) would then
 * select the HIGHEST-numbered participating group. That is precisely the
 * "last set" rule §8.3's `"xyy"` cell rules out: `(?J)^(?<a>x)(?<a>y)\k<a>$`
 * matches "xyx" and NOT "xyy". The table would have encoded a resolution rule
 * the emitted matcher does not use, silently, on the platform pcrec is
 * developed on.
 *
 * The reproducibility argument — an unstable `qsort` leaves equal rows in
 * unspecified order — is also true, and is now the SECOND reason rather than
 * the first. D59 left the tiebreak unpinned; this module pins it.
 *
 * ITS DETECTOR IS STRUCTURAL, not behavioural: `tests/codegen`'s
 * [M6.5-DUPNAMES] check reads the emitted rows' order off the ARTIFACT and
 * asserts it is non-decreasing in (name, number), plus a comparator-TOTALITY
 * assertion (it returns 0 only for rows equal in BOTH fields). Neither depends
 * on `qsort`'s stability or on the list's direction, which is what a
 * behavioural row here would have depended on. Sabotage row S120. */
static int ng_cmp_name(const void *a, const void *b)
{
    const NamedGroup *const *pa = a;
    const NamedGroup *const *pb = b;
    int c = strcmp((*pa)->name, (*pb)->name);
    if (c != 0) return c;
    return (*pa)->number < (*pb)->number ? -1
         : (*pa)->number > (*pb)->number ?  1 : 0;
}

static void emit_info_def(Ctx *cx, StrBuf *c, const char *infoname,
                          const char *upper, const InfoStamp *st)
{
    /* [M6.3] the named-groups reflection table, emitted (as a file-scope
     * `static` array, so two differently-prefixed artifacts sharing a TU
     * cannot collide on its name) ONLY when the pattern text declared at
     * least one name — every pattern with none stays byte-identical to
     * before this module existed, the same "trivially empty" convention
     * every other late-populated rx_info field already follows. */
    const char *groups_name = NULL;
    if (cx->n_named_groups > 0) {
        NamedGroup **sorted =
            arena_alloc(&cx->arena, cx->n_named_groups * sizeof *sorted);
        unsigned idx = 0;
        for (NamedGroup *g = cx->named_groups; g; g = g->next)
            sorted[idx++] = g;
        qsort(sorted, cx->n_named_groups, sizeof *sorted, ng_cmp_name);

        groups_name = derived_name(cx, "_group_names");
        sb_printf(c, "static const rx_group_entry %s[] = {\n", groups_name);
        for (unsigned i = 0; i < cx->n_named_groups; i++) {
            /* `slot`: the caps[] index this entry delivers, or -1 if this
             * build delivers none. `sorted[i]->number` (the group's
             * capture NUMBER) is always set, regardless of want_caps —
             * mod_named_groups.c numbers a named group unconditionally,
             * the same lexical-fact tier `ngroups` is. Whether that
             * number ALSO addresses a live caps[] slot is the separate,
             * build-output question `cx->want_caps` answers.
             *
             * [DD-14 wave G] THE VALUE IS UNCHANGED AND THE REASON WAS
             * WRONG. This comment used to argue that a captures-wanted
             * build with any named group is UNCONDITIONALLY VM-selected,
             * so `want_caps == true` implied a VM artifact. The
             * dead-capture elision retired that implication:
             * `(?:(?<g>a)){0}(?&g)b` compiles to the DFA (`.engine = 1`)
             * with `RX_NCAPS 2` and a name table whose entry addresses
             * slot 1. **THE SLOT NUMBER IS STILL RIGHT**, and now for a
             * reason that does not mention the engine: `want_caps` says
             * the caller asked for capture slots, `ncaps` is
             * `ngroups + 1` on BOTH engines since this wave, and the
             * group's number IS its slot index in the array the caller
             * gets — whether any match can set it is a different question
             * and not this field's. See mod_named_groups.c's header. */
            int slot = cx->want_caps ? sorted[i]->number : -1;
            sb_printf(c, "    { \"%s\", %d, %d, NULL },\n",
                      sorted[i]->name, sorted[i]->number, slot);
        }
        sb_puts(c, "};\n");
    }

    sb_printf(c, "const struct rx_info %s = {\n", infoname);
    /* abi 2: `work_budget` joined the layout (D47 SECOND ADDENDUM's third
     * bound). The member is INSERTED beside `step_budget` rather than appended,
     * so every following offset moves — which is precisely what the version
     * member exists to announce, and what the pre-release ABI posture (D47
     * SECOND ADDENDUM's rider, D49) licenses on a struct D44.5 called final.
     *
     * [DD-14.FB] abi 2 -> 3: the caller-buffer sizing surface's four fields
     * (spec §10.4) are INSERTED after `subject_ceiling`, ahead of the three
     * pointer members, so every following offset moves again — the same
     * announced pre-v1 boundary D40 regime 1 governs, and the same reason
     * this member exists. P-4 of the design predicts nothing in-tree reads
     * the struct positionally; a vendored consumer is D40's problem, not a
     * silent one. */
    /* [DD-13] abi 3 -> 4 (D76/[TT-11]): the DFA artifact's D46 SELECTION
     * STAMPS (`<PREFIX>_ENGINE`, `_DFA_SCAN`, `_DFA_PREFILTER`, above) are
     * three new lines in its scaffolding — and, because `emit_info_def` is
     * SHARED, this member's own byte moves in every VM artifact too, which is
     * why the whole-file pin had to move for both kinds (r37 A12). They are
     * three new lines in every DFA artifact's `#define` block. They are pure
     * SCAFFOLDING — no table, no search-loop byte and no answer moves, which
     * `run_recursion_identity.sh`'s comparison (A) proves by comparing the
     * PROGRAM REGION against the unchanged pre-module pin — but D76's rule is
     * about the emitted scaffolding and not about behaviour: any change to it
     * is an `abi` bump AND a re-pin of that gate's comparison (B) to this
     * change's last src-touching commit, in the same change. */
    /* [OPT-K] abi 8 -> 9 (D76): the OFFSET-k CANDIDATE-START SKIP
     * (docs/design/offset_k_skip.md). Every DFA artifact gains a
     * `<PREFIX>_DFA_PREFILTER_OFFSETS` stamp line (`"none"` on most of them),
     * and an artifact whose forward scan SELECTS the form additionally gains a
     * file-scope `<prefix>_ofsskip` block, up to three candidate tables and a
     * changed prefilter body inside the scan. Like [OPT-3] and [ENG-FORM] this
     * moves emitted PROGRAM bytes and not scaffolding only, and like both it
     * moves no struct offset. The four sites are the note's §9. */
    /* [OPT-1] abi 4 -> 5 (D76/[TT-11]): the TWO-TIER DEFAULT ENTRY
     * (docs/design/two_tier_entry.md). Every VM artifact gains two
     * `<PREFIX>_FAST_*` capacity stamps, and a TIERED one additionally gains a
     * `<prefix>_fast_buffers` type, the `<PREFIX>_TIER_NOTE` hook block and
     * three `noinline` `_deep` statics, while its three un-suffixed entries
     * change body. Like [DD-13] this moves NO struct offset (the two stamps
     * are `#define`s; `rx_info`'s layout is untouched) and NO emitted PROGRAM
     * byte, which `run_recursion_identity.sh`'s comparison (A) proves against
     * the unchanged pre-module pin. It is still scaffolding, so D76's rule
     * applies exactly as it did there: bump, and re-pin comparison (B).
     *
     * NO DFA ARTIFACT'S BYTES MOVE at this bump, which is a first for the
     * `abi` member and worth stating rather than leaving to be rediscovered:
     * the tier is emitted entirely by src/gen/emit_vm.c and a DFA artifact has
     * no resume stack to tier. The `abi` number is the ARTIFACT FORMAT's
     * version, not the VM's, so it moves on both kinds anyway — which is why
     * comparison (B) is re-pinned for DFA artifacts too. */
    /* [DD-13c] abi 5 -> 6, THE NEXT EVENT AFTER [OPT-1]'s immediately above,
     * AND THIS ONE IS A LAYOUT EVENT — not the scaffolding-only kind [DD-13]
     * and [OPT-1] both were. Two things move together:
     *
     *   SCAFFOLDING (D76/[TT-11]), r37's two SCOPE findings. (#5) the
     *   proven-empty DFA artifacts stamp `_DFA_SCAN "empty"` where they used to
     *   claim `"unanchored"`, a loop they do not contain; (#6) every VM HYBRID
     *   artifact gains the two `_DFA_*` lines describing the scan it inlines.
     *
     *   LAYOUT (D40 addendum, Frank 2026-08-25: pre-v1 abi changes are
     *   deliberate and methodical, not avoided). `struct rx_info` gains
     *   `scan` and `prefilter`, the RUNTIME mirrors of those same two facts,
     *   for the consumer that has no header to read the macros from. They are
     *   APPENDED AT THE END of the struct, after the three pointers, so NO
     *   EXISTING MEMBER'S OFFSET MOVES — unlike abi 2's inserted `work_budget`
     *   and abi 3's inserted sizing block, which moved everything after them.
     *
     * BOTH ARTIFACT KINDS ARE AFFECTED, and saying so is r37 A12's lesson: that
     * finding was that abi 3 -> 4's comment justified the bump from the DFA
     * side alone while `emit_info_def` is SHARED, so every VM artifact's bytes
     * moved too and the reader could not tell. Here, explicitly: a DFA artifact
     * gains two struct fields and may change its `_DFA_SCAN` value; a VM
     * artifact gains the same two struct fields, and a HYBRID additionally
     * gains two `#define` lines. Note this is the MIRROR IMAGE of [OPT-1]'s
     * note directly above ("no DFA artifact's bytes move at this bump"): its
     * event was VM-only, this one reaches both. Comparison (A) is still
     * byte-identical against the unchanged `ac4917d` pin — every byte this
     * change writes lands in the `#define` block or the `rx_info` initializer,
     * both ABOVE `goto <prefix>_L0;` — and comparison (B) is re-pinned. */
    /* [OPT-3] abi 6 -> 7 (D76/[TT-11]): the PRE-MULTIPLIED DFA TRANSITION
     * TABLE (docs/design/premultiplied_dfa_table.md), and THIS ONE MOVES
     * EMITTED PROGRAM BYTES — the first `abi` event that does. [DD-13],
     * [OPT-1] and [DD-13c] were scaffolding (and a struct append), and each
     * says so directly above; this one is not, and saying which kind it is, is
     * r37 A12's lesson.
     *
     * WHAT MOVES. On every artifact that CONTAINS a DFA scan and whose
     * machines are inside the bound — DFA artifacts and VM HYBRIDS alike,
     * since the hybrid inlines `emit_unanchored`'s own output — the two
     * transition tables become `unsigned short` holding `next * classes` with
     * 65535 for dead, the two accepting tables are indexed by that
     * pre-multiplied value (and grow from `n` to `n * classes` bytes), the
     * state variables become `unsigned`, the dead test becomes a compare
     * against 65535, and the transition line loses its `* classes +`. Above
     * the bound, under `-fno-premul-table`, and on every ENG_ATTEMPT or empty
     * artifact, the emitted text is UNCHANGED character for character.
     *
     * SCAFFOLDING ALSO MOVES, on every artifact that contains a DFA scan: one
     * new `#define <PREFIX>_DFA_TABLE` line beside the other two `_DFA_*`
     * stamps, and the orientation block's "READING THE TABLES" paragraph now
     * describes the form the artifact actually carries.
     *
     * NO STRUCT OFFSET MOVES: `rx_info`'s layout is untouched (the design note
     * §8 decides the runtime mirror question NO, with a named trigger — D77 —
     * on the measured ground that nothing yet reads abi 6's own `scan` and
     * `prefilter` fields).
     *
     * COMPARISON (A) IS STILL EXPECTED BYTE-IDENTICAL and that is a real check
     * here rather than a formality: `run_recursion_identity.sh`'s
     * `prog_region` is `goto <p>_L0;` through `<p>_accept:`, i.e. the VM
     * program, and a hybrid's inlined `static <prefix>_prefilter` is emitted
     * ABOVE that `goto`. So (A) sees no DFA scan byte at all. Comparison (B)
     * compares WHOLE FILES and is re-pinned, in this same change, per D76. */
    /* [ENG-ABS] abi 9 -> 10 (D76): the ANCHORED MATCH-HERE FORM
     * (docs/design/anchored_match_unwrapped.md §6), and like [OPT-3],
     * [ENG-FORM] and [OPT-K] it MOVES EMITTED PROGRAM BYTES rather than
     * scaffolding alone. Saying which kind it is, is r37 A12's lesson; saying
     * it PER ARTIFACT KIND is the rest of it, because `emit_info_def` is
     * shared and the three kinds move by different amounts:
     *
     *  - An ENG_UNANCH DFA artifact that SELECTS the form gains a file-scope
     *    `<prefix>_anchored_state` accessor block, a third machine's tables
     *    inside `<prefix>_match`, and rewritten `_match`/`_match_caps` bodies
     *    (the second now delegates to the first instead of to
     *    `<prefix>_search`). `<prefix>_search` itself is untouched, byte for
     *    byte, which is what makes the answer-identity gate a check of this
     *    row alone.
     *  - Every OTHER DFA artifact — ENG_ATTEMPT, the empty engine, an
     *    anchored machine that overflowed a cap, and any build under
     *    `-fno-anchored-dfa` — keeps both bodies character for character and
     *    gains one `#define <PREFIX>_DFA_MATCH "search-filter"` line.
     *  - Every artifact of EITHER engine gains one `rx_info` field
     *    (`.match_form`, NULL on the VM side, hybrid included).
     *
     * COMPARISON (A) of run_recursion_identity.sh (`goto <p>_L0;` through
     * `<p>_accept:`, the VM PROGRAM) is expected byte-identical: the only byte
     * this row writes on a VM artifact is that struct field, which is above
     * the region. Comparison (B) compares whole files and is re-pinned in this
     * same change, per D76. */
    /* [OPT-4] abi 11 -> 12 (D76): the PREFILTER'S LANGUAGE STAMP (K39;
     * docs/design/prefilter_count_independence.md). SCAFFOLDING ONLY on every
     * artifact that keeps the exact language, and a large PROGRAM-BYTE event
     * on the few that do not — stating which kind it is, per artifact kind, is
     * r37 A12's lesson:
     *
     *  - A DFA artifact gains NOTHING. Not one byte: the stamp is gated on
     *    `fit.prefilter`, and a DFA artifact has no VM prefilter decision. It
     *    moves here only because `.abi` is emitted by this shared function.
     *  - A VM artifact with NO prefilter (`--engine=vm`, a backreference, a
     *    linked call, [SEL-1]'s drop) likewise gains nothing but the version.
     *  - A VM HYBRID gains TWO lines and nothing else — `#define
     *    <PREFIX>_VM_PREFILTER_LANG "exact"` and its companion `#define
     *    <PREFIX>_VM_PREFILTER_LANG_WHY "..."` (D81's `_WHY`, five values;
     *    docs/spec/tuning.md §2.17) — on 2,855 of the corpus's 2,878
     *    artifacts.
     *  - A VM HYBRID THAT TOOK A COLLAPSE RUNG gains those two lines reading
     *    `"count-collapsed"` / a rung reason, a SMALLER inlined prefilter
     *    (different tables, different state counts), and
     *    `<PREFIX>_VM_PRUNE_CEILING` moving `"prefilter-window"` ->
     *    `"subject-end"` with the MRL clamp it names. Under Frank's ruling B
     *    (2026-08-29) that population is TINY and driven by the caps rather
     *    than by a knee: one corpus pattern reaches the [SEL-1] rung and none
     *    reaches the size rung, so essentially every artifact gains only the
     *    two stamp lines.
     *
     * COMPARISON (A) IS STILL EXPECTED BYTE-IDENTICAL, INCLUDING ON THE
     * COLLAPSED ARTIFACTS, and the reason is worth stating because the first
     * draft of this comment predicted the opposite. Dropping the
     * `prefilter-window` ceiling looks like a program change and is not one:
     * `v.mrl_win` is read at three sites and all three — the stamp, the
     * `--emit-ir` line, and the two `window_end = ...` BUILDERS — sit in
     * `<prefix>_search` and its retry recompute, ABOVE `run_recursion_
     * identity.sh`'s `prog_region` (`goto <p>_L0;` through `<p>_accept:`).
     * The per-quantifier clamp reads `window_end` as a PARAMETER, so the
     * number changes and the emitted program does not. MEASURED on
     * `((a)|b){0,4000}c`: 116 region lines, byte-identical between the
     * collapsed build and its `-fno-prefilter-collapse` twin. Comparison (B)
     * compares whole files and is re-pinned in this same change, per D76. */
    /* [OPT-5] abi 12 -> 13 (D76): THE DFA SCAN EDGE. Unlike every bump before
     * it this one moves emitted PROGRAM bytes on the DFA side and moves the
     * MACHINE with them, so stating the effect per artifact kind (r37 A12's
     * lesson) matters more here than usual:
     *
     *  - EVERY artifact gains one scaffolding line, `#define
     *    <PREFIX>_DFA_SCAN_EDGE "none"`, which is why the version moves at
     *    all on artifacts the transform never touches. A VM artifact with no
     *    hybrid prefilter gains nothing else, ever.
     *  - A DFA ARTIFACT (or a VM HYBRID's inlined prefilter) WHOSE MACHINE
     *    CARRIES A COUNTED CLASS RUN gains the stamp's real value, one
     *    `if (state == K) { ... }` block per edge inside the scan loop, and a
     *    per-edge membership table where the class is not a contiguous range
     *    — and LOSES the run's interior states from every per-state table it
     *    has: transitions, accepts, the state legend. `[a-z]{0,16384}`'s
     *    forward machine goes from 16,385 states to 2.
     *  - ENG_ATTEMPT gains nothing but the stamp line and the version: the
     *    pass is not run on that engine at all (src/core/compile.c says why —
     *    [OPT-3]'s own reason for exempting it).
     *
     * COMPARISON (A) MOVES ON THIS ONE, and that is expected rather than a
     * surprise: its `prog_region` is the VM program, and a VM HYBRID's
     * inlined DFA prefilter sits ABOVE that region — so (A) is byte-identical
     * on every VM artifact and this change reaches no VM program byte.
     * Comparison (B) compares whole files and is re-pinned in this same
     * change, per D76. */
    /* [CC-CLANG] abi 13 -> 14 (D76): TWO EMITTED-SCAFFOLDING CHANGES, bundled
     * because both exist only to let clang compile the same artifact gcc
     * already accepts and neither moves an answer:
     *
     *  - `emit_search_head`'s `noclone` line is now wrapped in an
     *    `__has_attribute` guard (this file, above) — EVERY artifact gains
     *    the three guard lines and loses nothing on gcc, which still emits
     *    `__attribute__((noclone))` because it has the attribute.
     *  - `src/gen/emit_vm.c`'s fail label omits the pop-and-resume `goto *`
     *    dispatch entirely on a FRAMELESS artifact (no `RX_PUSH` and no
     *    `RX_CALL` site anywhere in the program — the counter-rung-only
     *    shape, e.g. `[a-z]{0,4096}` --engine=vm): that dispatch was
     *    unreachable there already (resume_depth can never leave 0), and its
     *    `goto *` with no address-of-label expression in the function is
     *    exactly what clang refuses and gcc accepts. Every OTHER VM
     *    artifact's program bytes are unchanged — comparison (A) still
     *    applies to them.
     *
     * Comparison (B) compares whole files and is re-pinned in this same
     * change, per D76. */
    /* [DD-13b.W1.2] abi 14 -> 15 (D76): `rx_info.name` AND `rx_info.nentries`.
     * SCAFFOLDING ONLY, on every artifact of both engines, and this is the
     * first bump since [OPT-3] that moves no emitted PROGRAM byte at all —
     * stating that per artifact kind is r37 A12's lesson:
     *
     *  - EVERY artifact of EITHER engine gains exactly two `rx_info`
     *    initializer lines (`.name`, `.nentries`) and the two member
     *    declarations in the shared `PCREC_RX_ABI_H` block. Nothing else.
     *  - NO STRUCT OFFSET MOVES: both members are APPENDED after
     *    `match_form`, the [DD-13c] append shape rather than abi 2's and
     *    abi 3's insertions.
     *  - No table, no state, no label, no macro VALUE changes on any
     *    artifact, and no analysis is consulted that was not consulted
     *    before: `.name` reads an option field and `.nentries` reads the
     *    same `cx->n_named_groups` `.nnames` already read.
     *
     * COMPARISON (A) of run_recursion_identity.sh (`goto <p>_L0;` through
     * `<p>_accept:`, the VM PROGRAM) is expected byte-identical, and here
     * that is structural rather than argued: the two bytes this row writes
     * are `rx_info` initializer lines, which are emitted below that region
     * on every artifact. Comparison (B) compares whole files and is
     * re-pinned in this same change, per D76. */
    /* [OPT-5 STEP 2] abi 15 -> 16 (D76): the START-PINNED SEARCH. This bump
     * is the OPPOSITE of the one above — it moves emitted PROGRAM bytes, and
     * on the accepted population it DELETES a whole machine — so what it
     * moves is stated per artifact kind, r37 A12's lesson:
     *
     *  - EVERY artifact of EITHER engine gains ONE `rx_info` member
     *    declaration (`search_form`) in the shared `PCREC_RX_ABI_H` block and
     *    ONE initializer line. NO STRUCT OFFSET MOVES: the member is APPENDED
     *    AT THE END, after `nentries` — the [DD-13c] discipline's SUBSTANCE
     *    ("append at the end so no existing member's offset moves") rather
     *    than its dated wording ("after `match_form`"), which was written
     *    when `match_form` was the last member and no longer is.
     *  - EVERY artifact that CONTAINS a DFA scan (a VM HYBRID included) gains
     *    one `<PREFIX>_DFA_START` stamp line, and its `.search_form` reads a
     *    string rather than NULL.
     *  - On an artifact the axis-J predicate ACCEPTS, `<prefix>_search` loses
     *    its whole reverse machine: the reverse transition/accept/class
     *    tables, any stay tables, any scan-edge membership tables, the
     *    `<prefix>_reverse_*` accessor block and the reverse scan loop. Its
     *    post-loop block becomes two assignments and a `return 1`, and the
     *    `<PREFIX>_DFA_TABLE` / `<PREFIX>_DFA_SCAN_EDGE` folds stop reading
     *    the machine that is no longer there — so either stamp's VALUE can
     *    move, always toward the FORWARD machine's own value.
     *  - EVERY VM ARTIFACT, A HYBRID INCLUDED, gains one
     *    `<PREFIX>_VM_FRAMELESS` stamp line. That is [OPT-VMFL]'s macro, not
     *    this row's, and it RIDES THIS BUMP by the manager's ruling rather
     *    than taking one of its own: a second abi event immediately behind
     *    this one would cost a second union battery for one macro. It is
     *    written in `src/gen/emit_vm.c` beside `_VM_RUNGS`; see that file.
     *  - No answer moves on any artifact, either way. That is the deny
     *    flag's whole job (`-fno-start-pinned`, `make test-axes`).
     *
     * COMPARISON (A) of run_recursion_identity.sh (`goto <p>_L0;` through
     * `<p>_accept:`, the VM PROGRAM) is expected byte-identical: every byte
     * this row writes is either an `rx_info` initializer line, a `#define`
     * above the program, or DFA-side text, none of which is inside that
     * region. Comparison (B) compares whole files and is re-pinned in this
     * same change, per D76. */
    sb_puts(c,   "    .abi = 17,\n");
    /* [ENG-BREP] The STRATEGY-DENIAL bits are masked out of the stamp, and
     * the reason is the same one that makes them safe to ship.
     *
     * `rx_info.flags` is D43's record of the options the artifact was compiled
     * WITH, and its consumers read it to learn what the matcher DOES.
     * `-fno-possessify` changes what the matcher does by exactly nothing —
     * that is the claim the flag exists to test — so stamping it here would
     * make two artifacts that behave identically differ in their reflection
     * surface over a knob with no observable effect. It would also destroy the
     * byte-identity gate that is this pass's own safety argument: "a pattern
     * the analysis declines emits the bytes it emits today" is checkable only
     * while the flag itself leaves no trace, and a gate that has to FILTER a
     * known-differing line is the check-design failure this project has
     * recorded twice.
     *
     * What the ladder's choices ARE recorded in is `<PREFIX>_VM_STRATS`
     * (src/gen/emit_vm.c), which reports what the emitter actually DID rather
     * than what it was asked — the D46 half that a denial can be checked
     * against. Each further denial in D47.3's family joins this mask as it
     * lands.
     *
     * [M4.6f] `PCREC_NO_PREFILTER`/`PCREC_FORCE_PREFILTER` join the mask for
     * the identical reason, even though the PREFILTER axis is a FORCE pair
     * rather than a deny-only flag (lib/pcrec.h's comment on the two bits):
     * the rule this mask states is about the axis's OBSERVABLE EFFECT, not
     * about deny-vs-force spelling, and forcing the hybrid prefilter on or
     * off changes no answer, only how one is found (engine_m4.md §6.1). The
     * axis's own D46 record is `<PREFIX>_VM_PREFILTER` (src/gen/emit_vm.c),
     * VM-artifacts-only — but NOT for the reason this comment used to give
     * ("a DFA artifact has no separate prefilter decision to report", the
     * same premise §6.3's old VM-only rule rested on). [DD-13] falsified it:
     * a DFA artifact makes a real candidate-start prefilter decision and
     * stamps it as `<PREFIX>_DFA_PREFILTER` (`emit_dfa_stamps`, below). The
     * two stay SEPARATELY NAMED because their VALUE SETS are different
     * vocabularies — "hybrid"/"none" against five DFA loop shapes — which is
     * §6.3's (a)/(b) rule: the SELECTION FACT `RX_ENGINE` is unconditional
     * and shared, an engine's own vocabulary is neither.
     *
     * [OPT-ALTCLS] `PCREC_NO_ALTCLS_MERGE`/`PCREC_NO_ALTCLS_FACTOR` join the
     * mask too, and for the ORIGINAL deny-family reason rather than the
     * prefilter's force-pair exception: each is a per-alternation-run
     * selection point that changes no answer, only the emitted shape. Their
     * own D46 record is `<PREFIX>_ALTCLS_MERGES`/`<PREFIX>_ALTCLS_FACTORED`
     * (src/gen/emit_dfa.c's `pcrec_emit_prologue`, above — shared by both
     * engines since this pass runs before either is built). */
    {
        const uint64_t strategy_denials = PCREC_NO_POSSESSIFY | PCREC_NO_REVDET |
                                          PCREC_NO_COUNTER |
                                          PCREC_NO_LENGTH_PRUNE |
                                          PCREC_NO_PREFILTER | PCREC_FORCE_PREFILTER |
                                          /* [OPT-4] the prefilter's LANGUAGE
                                           * axis, on `PCREC_*_PREFILTER`'s own
                                           * precedent one line up and for the
                                           * mask's own reason: it selects a
                                           * superset the VM verifies from, so
                                           * it changes no answer, and
                                           * `<PREFIX>_VM_PREFILTER_LANG` is
                                           * where what the emitter DID is
                                           * recorded.
                                           *
                                           * MEASURED as a defect before it was
                                           * a comment: unmasked, passing
                                           * `-fno-prefilter-collapse` moved 5
                                           * bytes of `rx_info.flags` on EVERY
                                           * artifact — including patterns with
                                           * no counted repeat, where the flag
                                           * cannot act at all — which is
                                           * exactly the byte-identity property
                                           * that makes the denied build usable
                                           * as a ground truth. Caught by
                                           * run_prefilter_collapse.sh §2 on
                                           * its first run. */
                                          PCREC_NO_PREFILTER_COLLAPSE |
                                          PCREC_FORCE_PREFILTER_COLLAPSE |
                                          PCREC_NO_ALTCLS_MERGE | PCREC_NO_ALTCLS_FACTOR |
                                          /* [OPT-1] the two-tier entry axis. It
                                           * changes no answer (the deep tier is
                                           * a replay of the single-tier run --
                                           * two_tier_entry.md §4), so it belongs
                                           * to the mask for the mask's own
                                           * reason; `<PREFIX>_FAST_FRAMES` is
                                           * where what the emitter DID is
                                           * recorded. */
                                          PCREC_NO_TIERED_ENTRY |
                                          /* [OPT-3] the DFA table-form axis.
                                           * It changes the ENCODING of a
                                           * state, not the machine, so it
                                           * changes no answer and belongs to
                                           * the mask for the mask's own
                                           * reason; `<PREFIX>_DFA_TABLE` is
                                           * where what the emitter DID is
                                           * recorded. */
                                          PCREC_NO_PREMUL_TABLE |
                                          /* [OPT-K] the offset-k skip axis. It
                                           * refuses only starts the stepped
                                           * scan would refuse, so it changes
                                           * no answer and belongs to the mask
                                           * for the mask's own reason;
                                           * `<PREFIX>_DFA_PREFILTER` and its
                                           * `_OFFSETS` sibling are where what
                                           * the emitter DID is recorded. */
                                          PCREC_NO_OFFSET_SKIP |
                                          /* [ENG-ABS] the anchored match-here
                                           * axis. It changes no answer (the
                                           * identity argument is
                                           * anchored_match_unwrapped.md §3),
                                           * so it belongs to the mask for the
                                           * mask's own reason;
                                           * `<PREFIX>_DFA_MATCH` is where what
                                           * the emitter DID is recorded. */
                                          PCREC_NO_ANCHORED_DFA |
                                          /* [OPT-5 STEP 2] axis J, the search
                                           * entry's start-recovery form. It
                                           * changes no answer (the elision's
                                           * proof is opt5_step2_twopass.md
                                           * §3.2), so it belongs to the mask
                                           * for the mask's own reason; and
                                           * concretely, without it every
                                           * artifact the predicate DECLINES
                                           * would move `rx_info.flags` under
                                           * the deny flag — destroying the
                                           * byte-identity of the declined
                                           * population, which is the
                                           * reference the axis's own checks
                                           * are written against. That is the
                                           * defect [OPT-4]'s comment above
                                           * measured on bit 19 before it was
                                           * a comment. `<PREFIX>_DFA_START`
                                           * is where what the emitter DID is
                                           * recorded. */
                                          PCREC_NO_START_PINNED;
        sb_printf(c, "    .flags = %lluULL,\n",
                  (unsigned long long)(cx->opt->flags & ~strategy_denials));
    }
    sb_printf(c, "    .encoding = %d,\n", cx->opt->encoding);
    sb_printf(c, "    .ncaps = %s_NCAPS,\n", upper);
    sb_printf(c, "    .ngroups = %d,\n", (int)cx->ncap);
    sb_printf(c, "    .nnames = %u,\n", cx->n_named_groups);
    /* [ABI-NS] (D60 addendum): the comment names the emitted PCREC_ENGINE_*
     * constants (emit_rx_abi_types), not the internal ENGM_* enum. */
    sb_printf(c, "    .engine = %d, /* %s */\n", st->engine,
              st->engine == 2 ? "PCREC_ENGINE_VM" : "PCREC_ENGINE_DFA");
    sb_printf(c, "    .step_budget = %lld,\n", st->step_budget);
    sb_printf(c, "    .work_budget = %lld,\n", st->work_budget);
    sb_printf(c, "    .frame_capacity = %lld,\n", st->frame_capacity);
    sb_printf(c, "    .subject_ceiling = %lld,\n", st->subject_ceiling);
    sb_printf(c, "    .resume_frames = %lld,\n", st->bufs->resume_frames);
    sb_printf(c, "    .trail_frames = %lld,\n", st->bufs->trail_frames);
    sb_printf(c, "    .resume_frame_size = %d,\n", st->bufs->resume_frame_size);
    sb_printf(c, "    .trail_frame_size = %d,\n", st->bufs->trail_frame_size);
    sb_puts(c,   "    .pattern = ");
    emit_c_string_literal(c, cx->pat, cx->patlen);
    sb_puts(c,   ",\n");
    sb_printf(c, "    .pattern_len = %zu,\n", cx->patlen);
    if (groups_name)
        sb_printf(c, "    .groups = %s,\n", groups_name);
    else
        sb_puts(c, "    .groups = NULL,\n");
    if (st->engine_why) {
        sb_puts(c, "    .engine_why = ");
        emit_c_string_literal(c, st->engine_why, strlen(st->engine_why));
        sb_puts(c, ",\n");
    } else {
        sb_puts(c, "    .engine_why = NULL,\n");
    }
    /* [DD-13c] THE RUNTIME MIRRORS, FROM THE SAME TWO FUNCTIONS THE MACROS ARE
     * WRITTEN FROM. `dfa_scan_name`/`dfa_prefilter_name` are called here and in
     * `pcrec_emit_dfa_scan_stamps` and nowhere else, so `<PREFIX>_DFA_SCAN` and
     * `rx_info.scan` are one value written twice rather than two computations
     * of one fact -- which is what makes the codegen assertion that they AGREE
     * a check of the emitter rather than of arithmetic
     * (tests/codegen/run_codegen_tests.sh).
     *
     * THE GUARD IS THE SHARED PREDICATE, not a local test: on a non-hybrid VM
     * artifact `job->engine` and `job->dfa` were never written, so calling
     * either function there would read uninitialised analysis. */
    if (pcrec_artifact_has_dfa_scan(cx)) {
        sb_printf(c, "    .scan = \"%s\",\n", dfa_scan_name(cx));
        sb_printf(c, "    .prefilter = \"%s\",\n", dfa_prefilter_name(cx));
    } else {
        /* NULL scan is the runtime spelling of "no DFA in this artifact"; the
         * prefilter field still answers, in the VM's own vocabulary, which is
         * `<PREFIX>_VM_PREFILTER`'s value on exactly this artifact -- "none",
         * because a VM artifact whose `fit.prefilter` were on would have taken
         * the branch above. That is this field's half of closing
         * `RX_VM_PREFILTER`'s missing runtime mirror: "hybrid" never appears
         * HERE because a hybrid reports its inlined scan's actual mechanism
         * instead, and `scan != NULL` is how a consumer reads "hybrid". */
        sb_puts(c, "    .scan = NULL,\n");
        sb_puts(c, "    .prefilter = \"none\",\n");
    }
    /* [ENG-ABS] AXIS G's mirror, from the SAME `dfa_match_name` the macro is
     * written from — one value written twice, never two computations of one
     * fact.
     *
     * ITS GUARD IS NOT `pcrec_artifact_has_dfa_scan`, and the difference is
     * the field's meaning. That predicate is "does this artifact CONTAIN a DFA
     * scan", which is true of a VM HYBRID — but a hybrid's `<prefix>_match` is
     * the VM's own anchored body, which this axis does not describe. The
     * question here is "did the DFA emitter write this artifact's `_match`",
     * i.e. `fit.chosen == ENGM_DFA`, and `emit_info_def` is shared with the VM
     * emitter, which is why the test is spelled rather than assumed. */
    if (cx->job->fit.chosen == ENGM_DFA)
        sb_printf(c, "    .match_form = \"%s\",\n", dfa_match_name(cx));
    else
        sb_puts(c, "    .match_form = NULL,\n");
    /* [DD-13b.W1.2] THE NAME, AND THE FALLBACK IS THE RULE. Frank's
     * format_design §6.3 ruling is "no artifact ever carries a NULL name",
     * and this line is the whole of it: `opt->name` when a build supplied
     * one (`pcrec --source`, from the `target`'s block), the prefix
     * otherwise. Written through the same string-literal escaper the
     * pattern goes through, because a name is arbitrary text — `.rxt`'s own
     * `name` grammar is stricter, but that is that format's rule and not
     * this field's, and a library caller may set anything.
     *
     * IT IS THE `<prefix>` AND NOT THE LITERAL "rx": two differently-
     * prefixed artifacts in one TU must not both claim to be "rx". */
    {
        const char *nm = cx->opt->name ? cx->opt->name : cx->opt->prefix;
        sb_puts(c, "    .name = ");
        emit_c_string_literal(c, nm, strlen(nm));
        sb_puts(c, ",\n");
    }
    /* `nentries` reads the SAME count `nnames` does, from the same field,
     * because today the array holds the primary's rows and nothing else.
     * Two spellings of one number is the honest state of an uncomposed
     * artifact, not an oversight: what makes them different questions is
     * the composer, and the day it lands this line is where the injected
     * rows are counted. */
    sb_printf(c, "    .nentries = %u,\n", cx->n_named_groups);
    /* [OPT-5 STEP 2] AXIS J's mirror, from the SAME `dfa_search_start_name`
     * the `<PREFIX>_DFA_START` macro is written from — one value written
     * twice, never two computations of one fact, which is what makes the
     * codegen assertion that they AGREE a check of the emitter rather than of
     * arithmetic.
     *
     * THE GUARD IS THE SHARED PREDICATE, `scan`/`prefilter`'s and not
     * `match_form`'s, and the struct member's own comment carries the
     * argument. On a non-hybrid VM artifact `job->engine` and `job->dfa` were
     * never written, so calling the selection there would read uninitialised
     * analysis — the same reason the two fields above ask HERE. */
    if (pcrec_artifact_has_dfa_scan(cx))
        sb_printf(c, "    .search_form = \"%s\",\n", dfa_search_start_name(cx));
    else
        sb_puts(c, "    .search_form = NULL,\n");
    sb_puts(c,   "};\n");
}

/* [M5-SEAM] (D58, DD-12 (7)) THE RESIDUAL EMBED. The artifact's ONE encoding
 * is a per-compile scalar (`cx->opt->encoding`), and these two calls are the
 * whole of what the emitter knows about encodings: it asks the registry for
 * the backend and copies that backend's own text, prefix-substituted. There
 * is no encoding test here and there must never be one — the "switch" DD-12
 * allows is WHICH backend text got embedded, never a branch in shared code.
 *
 * Placement mirrors the four entry points exactly: declarations wherever a
 * consumer's declarations live (the .h when split, the .c when
 * self-contained), definitions in the .c. `pcrec_enc_ready` cannot be false
 * here — src/core/compile.c refuses an unimplemented encoding before any
 * emission — but the lookup is still checked rather than assumed, because a
 * NULL text pointer reaching this far would otherwise emit a truncated
 * artifact instead of failing. */
/* [M6.5.2] BOTH TAKE THE ARTIFACT'S MASK, which is D58's revisit clause being
 * honoured — see enc.h for why a per-entry mask and not two more string
 * fields. `Job.enc_mask` is set by whichever emitter is running BEFORE the
 * prologue, so an entry reaches the artifact iff something in it is emitted
 * that calls the entry. */
static void emit_residual_decls(Ctx *cx, StrBuf *sb)
{
    const PcrecEnc *enc = pcrec_enc_by_id(cx->opt->encoding);
    if (!pcrec_enc_ready(enc)) return;
    pcrec_enc_emit_decls(sb, enc, cx->job->enc_mask, cx->opt->prefix);
}

static void emit_residual_defs(Ctx *cx, StrBuf *sb)
{
    const PcrecEnc *enc = pcrec_enc_by_id(cx->opt->encoding);
    if (!pcrec_enc_ready(enc)) return;
    pcrec_enc_emit_defs(sb, enc, cx->job->enc_mask, cx->opt->prefix);
}

static void emit_header(Ctx *cx, const char *fn, const char *matchfn,
                         const char *matchcapsfn, const char *infoname,
                         const char *upper, int ncaps, const BufSurface *bs)
{
    StrBuf *h = &cx->job->hsb;
    const char *p = cx->opt->prefix;
    char guard[80];
    size_t gi = 0;
    for (const char *q = p; *q && gi < sizeof(guard) - 1; q++)
        guard[gi++] = (char)(isalnum((unsigned char)*q) ? toupper((unsigned char)*q) : '_');
    guard[gi] = 0;

    emit_pattern_comment(h, cx->pat);
    emit_feature_comment(h);
    sb_printf(h, "#ifndef PCREC_GEN_%s_H\n#define PCREC_GEN_%s_H\n\n", guard, guard);
    sb_puts(h, "#include <stddef.h>\n#include <stdint.h>\n\n");
    emit_rx_abi_types(h);
    sb_putc(h, '\n');
    emit_ncaps_macros(h, upper, ncaps);
    emit_buffers_surface(h, upper, cx->opt->prefix, bs);
    sb_putc(h, '\n');
    emit_search_decl(h, fn);
    emit_match_decl(h, matchfn);
    emit_match_caps_decl(h, matchcapsfn);
    emit_info_decl(h, infoname);
    /* [DD-14.FB] The three `_in` entries join the header UNCONDITIONALLY,
     * beside the siblings they mirror -- spec §10.4's "the three `_in`
     * entries, the `<prefix>_buffers` type and all five macros are emitted on
     * EVERY artifact", so a consumer's code does not stop compiling when the
     * same pattern selects the other engine. */
    emit_search_in_decl(h, fn, cx->opt->prefix);
    emit_match_in_decl(h, matchfn, cx->opt->prefix);
    emit_match_caps_in_decl(h, matchcapsfn, cx->opt->prefix);
    sb_putc(h, '\n');
    emit_residual_decls(cx, h);
    sb_printf(h, "\n#endif /* PCREC_GEN_%s_H */\n", guard);
}

/* ---- shared table emitters ---- */

static void emit_u8_table(StrBuf *c, const char *p, const char *tag,
                          const uint8_t *v, int n)
{
    sb_printf(c, "    static const unsigned char %s_%s[%d] = {", p, tag, n);
    for (int i = 0; i < n; i++) {
        if (i % 16 == 0) sb_puts(c, "\n       ");
        sb_printf(c, " %3d,", v[i]);
    }
    sb_puts(c, "\n    };\n");
}

/* ---- [OPT-3] THE PRE-MULTIPLIED TABLE FORM ------------------------------
 *
 * docs/design/premultiplied_dfa_table.md is the note; what lives here is the
 * rule and the two constants it turns on. In the PRE-MULTIPLIED form a
 * transition cell holds `next_state * ncls` rather than `next_state`, so the
 * emitted step is `state = table[state + class]` and the loop's carried
 * dependency chain is `add, load` instead of `lea, lea, movslq, load` —
 * [OPT-3] STEP 1 (docs/dev/opt3_dfa_scan_measurement.md §5) measured that
 * chain as the WHOLE of the scan's per-byte cost, and the transform as 1.276x
 * on the comparative bench's three throughput subjects.
 *
 * THE DEAD SENTINEL IS A RESERVED VALUE, not a sign bit and not a self-mapping
 * DEAD row. The design note §3 argues the choice on the emitted instruction
 * sequence; the short version is that `movzwl` + `cmp` is the same two
 * instructions as `movswl` + `js` with no `movslq` behind them, and that a
 * reserved value moves ONE number where an extra row moves two (its own
 * premultiplied value, and every per-state table's row count). It cannot
 * collide with a real cell BY THE BOUND below, not by convention. */
#define PREMUL_DEAD 65535

/* THE BOUND, decided PER MACHINE (a forward and a reverse DFA have different
 * `n` and different `ncls`, and each table's own dimensions are what the rule
 * is about). ONE conjunct, and it is a CORRECTNESS condition rather than a
 * budget: every cell must fit `unsigned short` and be distinguishable from
 * PREMUL_DEAD. `n * ncls <= 65535` gives a largest cell of
 * `(n - 1) * ncls = n * ncls - ncls < 65535`, so the sentinel cannot collide.
 *
 * IT USED TO HAVE A SECOND, TIGHTER CONJUNCT — a 16,384-entry SIZE BUDGET, on
 * the reasoning that above 32 KB of transition table the loop is bound by
 * memory rather than by its dependency chain, so the chain shortening would be
 * moot while the accept table's growth stayed real. **MEASURED 2026-08-26 and
 * DELETED**: the pre-multiplied form still wins across the whole L2-resident
 * band, on four witnesses (design note §13) —
 *
 *     [01]*1[01]{10}   9,216 entries   3.6029 -> 3.6094 ns/byte  (same form: the control)
 *     [01]*1[01]{11}  18,432 entries   4.8486 -> 4.3814          1.107x
 *     [01]*1[01]{12}  36,864 entries   6.8292 -> 6.2255          1.097x
 *     ((a)|bc){0,4000}d REVERSE, 40,010 entries
 *                                      3.5408 -> 2.7522          1.287x
 *
 * — because the two chain cycles the transform removes are removed whatever
 * the load costs, and the accept table's growth is a `.rodata` cost rather
 * than a per-byte one. The last row is the corpus's own largest machine, and
 * its 1.287x is the largest gain of the four, which is the opposite of what a
 * cache-eviction story predicts. */
/* DERIVED FROM THE SENTINEL, NOT SPELLED BESIDE IT. The two numbers are the
 * same and that is not a coincidence: the bound exists ONLY to keep every
 * emitted cell distinguishable from PREMUL_DEAD, so it IS the sentinel. Two
 * literals that must be kept in step is this project's most-recorded failure
 * shape; one `#define` reading the other makes stepping them impossible. (The
 * check in tests/codegen/run_premul_table.sh spells 65535 as a LITERAL on
 * purpose — a second source that cannot move with this one is the whole point
 * of it.)
 *
 * It is deliberately one row STRICTER than the arithmetic needs: the largest
 * emitted cell is `(n - 1) * ncls = ents - ncls`, so cells stay below the
 * sentinel for any `ents <= PREMUL_DEAD + ncls - 1`. Rounding down to
 * PREMUL_DEAD costs at most one row of one machine and removes an `ncls` from
 * the condition a reader has to check. */
#define PREMUL_MAX_ENTRIES PREMUL_DEAD

/* ---- [ENG-FORM] THE FORM AS A VALUE ------------------------------------
 *
 * docs/design/emitter_form.md is the note, and D82 the ruling. The rule in
 * one line: for every axis with TWO OR MORE real emitted forms, the emitter
 * holds an explicit PREFERENCE LIST of representation objects and the
 * machine's form is the FIRST APPLICABLE one; the chosen object's `name` IS
 * the stamp value; a `-fno-*` deny flag REMOVES a candidate rather than
 * being tested inside one. A one-site boolean stays a boolean (D75 addendum).
 *
 * THE OBJECTS ARE DEFINED BESIDE `emit_unanchored`, at the bottom of this
 * file, because that is where their emitters live; only the STRUCTS are here,
 * where the table emitters below need them. `DfaCand` is the common initial
 * member of every one of them, which is what lets `dfa_select` walk any of
 * the six lists with one loop instead of six.
 *
 * The facts a candidate's `applies` reads. It is a VALUE and not the Ctx
 * because selection happens twice per artifact from the body path and twice
 * more from the stamp path, and the two must not be able to answer
 * differently: everything an `applies` may look at is in here. */
typedef struct DfaSel {
    Ctx        *cx;
    const Dfa  *d;            /* THIS machine — forward and reverse differ */
    const void *us;           /* the UnanchStart; opaque until it is declared */
    bool        forward;
    /* [OPT-5] THE STATE A PER-STATE AXIS IS ABOUT, or -1. Six of this file's
     * axes describe a whole MACHINE and never read it; the scan edge's two
     * describe ONE STATE (does it emit an edge at all, and which
     * run-extension body does that edge use), and a selection walk that
     * cannot name the state would have to be a second, parallel walk. It is
     * -1 wherever it is meaningless, so a candidate that reads it on a
     * machine-level selection indexes nothing rather than reading a
     * fabricated state — `dfa_match_of`'s own reason for passing a NULL `d`
     * rather than a made-up one. */
    int         st;
} DfaSel;

typedef struct DfaCand {
    const char *name;         /* the stamp value, where this axis has a stamp */
    unsigned    deny;         /* a set bit in cx->opt->flags REMOVES this entry */
    bool      (*applies)(const DfaSel *s);
} DfaCand;

typedef struct DfaForm DfaForm;

/* AXIS A — THE TABLE REPRESENTATION, per machine. The one axis whose object
 * reaches the EMITTED C: `emit_token` writes the artifact's accessor block,
 * and after that nothing else in this file knows how a state is spelled. */
typedef struct DfaRepr {
    DfaCand     c;
    const char *cell_type;    /* the transition/view/seed table's cell type */
    bool        acc_wide;     /* the accept table is replicated `ncls`-fold */
    int         dead_cell;    /* the cell value that means "dead" */
    int       (*cell_of)(int st, const Dfa *d);  /* a live state, as a cell */
    void      (*emit_token)(StrBuf *c, const DfaForm *f);
    void      (*emit_tr_comment)(StrBuf *c, const DfaForm *f);
    void      (*emit_acc_comment)(StrBuf *c, const DfaForm *f);
} DfaRepr;

/* Selection is needed by `dfa_table_name` (the stamp path, ~700 lines above
 * the objects) and by the table emitters immediately below, so the two
 * entry points are declared here and defined with the objects. */
static const DfaRepr *dfa_repr_of(Ctx *cx, const Dfa *d);

/* [OPT-5] The scan edge's two per-state axes, same shape and same reason:
 * `dfa_scan_edge_name` (the stamp path, ~1,500 lines above the objects) asks
 * both, and the emitted loop asks both, so they are declared here and
 * DEFINED with the objects. Their types are opaque until then. */
typedef struct DfaEdge DfaEdge;
typedef struct DfaScan DfaScan;
static const DfaEdge *dfa_edge_of(Ctx *cx, const Dfa *d, int st);
static const DfaScan *dfa_scan_of(Ctx *cx, const Dfa *d, int st);
/* The chosen BODY object's own `c.name`, i.e. the stamp value (D82 rule 2).
 * An accessor rather than a dereference at the stamp path, because `DfaScan`
 * is incomplete up here -- and the accessor is what keeps "the stamp is the
 * chosen object's name" a single expression instead of a second reading. */
static const char *dfa_scan_body_name(Ctx *cx, const Dfa *d, int st);
/* Is `e` the region axis's FIRST candidate, i.e. did this state take an
 * edge? Spelled once here rather than compared against `&dfa_edges[0]` at
 * three call sites, two of which are above that array's definition. */
static bool dfa_edge_taken(const DfaEdge *e);

/* ---- [CC-DIFF] STEP 1 (b): THE UNIFORM-TABLE FOLD ------------------------
 *
 * THE FACT. pcrec BUILDS the transition and accept tables, so at emission
 * time it already knows whether every cell of one holds the same value. When
 * one does, the indexed load is a CONSTANT, and the emitter can spell it as
 * one instead of emitting an array for the compiler to re-derive it from.
 * LLVM does this fold on its own (`ConstantFoldLoadFromUniformValue`); gcc 15
 * does not fold a variable-index load even from an all-equal `static const`
 * array, which is the whole of the bench ledger's `cls-upto-4` gap
 * ([CC-DIFF] STEP 0 §1: gcc `rx_search` 142 instructions and 6 table-base
 * `lea`s against clang's 76 and 0). Measured hand-twin ratio 0.589.
 *
 * WHERE THE UNIFORMITY COMES FROM, and why this is not a pattern special
 * case: [OPT-5]'s scan edge absorbs a bounded class's real transitions into
 * the edge's own run loop, which leaves the machine's own table with nothing
 * left to say — `[a-z]{0,4}` ends with all six of its tables uniform. But the
 * rule here is a property of a TABLE, not of a pattern or of a pass: any
 * all-equal table folds, whatever made it all-equal.
 *
 * ONE DERIVATION OF THE CELL. The constant this fold emits and the cells the
 * table emitter writes come from the SAME three functions below, which is the
 * point of factoring them out of the emitters at all. A fold computed from a
 * second reading of `d->st[].tr[]` would be exactly the control-sharing-a-
 * source failure docs/dev/learnings.md §3 keeps a list of — except inverted
 * and worse: here the two readings must AGREE, and the only way to guarantee
 * that is for there to be one reading.
 *
 * WHAT IS IN SCOPE, AND THE BOUNDARY IS DRAWN ON A PROPERTY RATHER THAN ON
 * TASTE: the two tables EVERY machine emits UNCONDITIONALLY and reads once
 * per byte through the §LAYER-2 state-token accessors — `<m>_next_state` (the
 * step) and `<m>_is_accepting` (the accept probe). Because their existence is
 * not itself a selection, `<PREFIX>_DFA_UNIFORM_FOLDS` can count the folds
 * EXACTLY from `(cx, d)` at the stamp path, through these same two functions,
 * with no second reading of any axis's choice.
 *
 * DELIBERATELY OUT OF SCOPE, each for a stated reason, none of them an
 * oversight:
 *   - `<m>_is_accepting_by_class`, the WIDE accept table. It is uniform on
 *     the same shapes and folding it would work, but it EXISTS only where
 *     axis E chose `by-class`, so counting its fold at the stamp path would
 *     mean re-reading that selection there — and a count that skipped it
 *     instead would under-report. Left for a follow-up that either moves the
 *     fold derivation onto the Job (one derivation both readers share) or
 *     gives axis E a stamp-path accessor of `dfa_repr_of`'s shape.
 *   - the seed, view and stay tables: read at most twice per search, so
 *     there is no measurement behind folding them and D77 says wait for one.
 *   - `<m>_byte_class`: not a transition or accept table, read as a bare
 *     subscript rather than through an accessor, and uniform only on a
 *     single-class machine.
 *   - the direct-threaded ENG_ATTEMPT emitter's own `<p>_is_accepting_by_class`
 *     (further down, a bare subscript beside a `goto *targets`): a different
 *     mechanism with no accessor and no transition table at all. */
static int tr_cell(const Dfa *d, const DfaRepr *r, int i, int cl)
{
    int t = d->st[i].tr[cl];
    return t < 0 ? r->dead_cell : r->cell_of(t, d);
}

static int acc_cell(const Dfa *d, int i)
{
    return d->st[i].up[UPC_PLAIN].accept ? 1 : 0;
}

static int upc_emit_of_class(const Dfa *d, int cl);

static int accw_cell(const Dfa *d, int i, int cl)
{
    return d->st[i].up[upc_emit_of_class(d, cl)].accept ? 1 : 0;
}

/* "Every cell of this table is `value`", or `folded == false`. A table with a
 * single cell is uniform, which is correct and not a corner: the fold is
 * right for it and the array was never worth emitting. A table with NO cells
 * is not folded — there is nothing to fold to, and the emitter's own `[0]`
 * array is the pre-existing behaviour on a shape that does not occur. */
typedef struct { bool folded; int value; } DfaFold;

static DfaFold fold_tr(const Dfa *d, const DfaRepr *r)
{
    DfaFold f = { false, 0 };
    if (d->n <= 0 || d->ncls <= 0) return f;
    int v = tr_cell(d, r, 0, 0);
    for (int i = 0; i < d->n; i++)
        for (int cl = 0; cl < d->ncls; cl++)
            if (tr_cell(d, r, i, cl) != v) return f;
    f.folded = true; f.value = v;
    return f;
}

static DfaFold fold_acc(const Dfa *d)
{
    DfaFold f = { false, 0 };
    if (d->n <= 0) return f;
    int v = acc_cell(d, 0);
    for (int i = 0; i < d->n; i++)
        if (acc_cell(d, i) != v) return f;
    f.folded = true; f.value = v;
    return f;
}

static void emit_tr_table(StrBuf *c, const char *p, const char *tag,
                          const Dfa *d, const DfaRepr *r)
{
    sb_printf(c, "    static const %s %s_%s[%d] = {",
              r->cell_type, p, tag, d->n * d->ncls);
    int k = 0;
    for (int i = 0; i < d->n; i++) {
        for (int cl = 0; cl < d->ncls; cl++, k++) {
            if (k % 16 == 0) sb_puts(c, "\n       ");
            sb_printf(c, " %d,", tr_cell(d, r, i, cl));
        }
    }
    sb_puts(c, "\n    };\n");
}

static bool dfa_has_eolvar(const Dfa *d)
{
    for (int i = 0; i < d->n; i++)
        if (d->st[i].eolvar >= 0) return true;
    return false;
}

/* ===================================================================
 * [M6.2 repair slice, 2026-08-19] THE REFERENCE-BUILD KNOBS FOR WAVES
 * A, B AND C, RE-PLACED AT THIS EMITTER.
 *
 * Wave D's own knob (`PCREC_NO_GSTART`, further down) is at the
 * emitter's decision points, and its comment records why: waves A/B/C
 * put theirs in `src/ir/dfa.c` PINNING A FLAG, i.e. inside the code
 * their sabotages edit, and the reference compiler is built from THE
 * SAME (sabotaged) sources — so a sabotage that deletes the flag's
 * CONSUMER applies to both builds and CANCELS. This slice moves them.
 *
 * TWO PARTS PER KNOB, and the split is not tidiness — it is where each
 * construct's emitted text is actually decided:
 *
 *   - HERE, the emitter's decision points: with the knob defined the
 *     emitter takes the pre-wave branch at every site that reads the
 *     construct, so the reference build is structurally the pre-wave
 *     EMITTER. That is wave D's model applied verbatim.
 *   - AND, for these three only, at the ANALYSIS'S ACTIONS in
 *     `src/ir/dfa.c` — the alphabet refinement, `clsctx`, `upc_live[]`
 *     and the END view's interning. `\G` needed no such half because it
 *     refines no alphabet and interns no state the emitter cannot
 *     neutralize; `\b`, `(?m)` and `\z` all change the DFA ITSELF, and
 *     no emitter branch can un-refine a partition or un-intern a state.
 *     MEASURED before it was written: with the emitter half alone,
 *     sabotage S71 leaves a `\b`-free artifact byte-identical between
 *     the two builds, because both builds refine the alphabet. The
 *     dfa.c half is a PREPROCESSOR exclusion of the ACTION rather than
 *     a pinned flag, which is the property that makes it survive a
 *     sabotage of the action's own gate.
 *
 * In a shipped build every predicate below is a compile-time constant
 * true and gcc folds it away; the emitted bytes are unchanged, which
 * the identity gates' own subject builds are the standing check on.
 * =================================================================== */

/* Is the emitter willing to see class-axis context `u` as distinct from
 * UPC_PLAIN? Wave B's knob answers for UPC_WORD, wave C's for UPC_NL. */
static bool upc_emit_live(int u)
{
#ifdef PCREC_NO_WORDCTX
    if (u == UPC_WORD) return false;
#endif
#ifdef PCREC_NO_MLINECTX
    if (u == UPC_NL) return false;
#endif
    (void)u;
    return true;
}

/* `upc_of_class` as the EMITTER reads it: a masked class collapses onto
 * UPC_PLAIN, so every derived table (§3.6's accept, §3.8's seed) emits
 * the pre-wave column. */
static int upc_emit_of_class(const Dfa *d, int cl)
{
    int u = upc_of_class(d, cl);
    return upc_emit_live(u) ? u : UPC_PLAIN;
}

/* A state's END view as the EMITTER reads it — wave A's knob. -1 is
 * "same as the EOL view", so pinning it there puts every site on the
 * pre-wave arm. */
static int st_emit_endvar(const DState *st)
{
#ifdef PCREC_NO_ENDVAR
    (void)st;
    return -1;
#else
    return st->endvar;
#endif
}

/* [M6.2 wave A] Does any state have an END view (`\z`) distinct from its EOL
 * view? FALSE for every `\z`-free pattern BY CONSTRUCTION (src/ir/dfa.c's
 * make_state canonicalizes `endvar` against the EOL view, so a pattern with
 * no N_END state interns none), which is what makes every `if (endv)` below
 * a no-op on the existing corpus and the emitted text byte-identical to the
 * pre-wave one. tests/codegen/run_endvar_identity.sh is the check. */
static bool dfa_has_endvar(const Dfa *d)
{
    for (int i = 0; i < d->n; i++)
        if (st_emit_endvar(&d->st[i]) >= 0) return true;
    return false;
}

/* [OPT-3] The view tables are the ONE place a pre-multiplied value is
 * converted back, and it is deliberate (design note §6): their CELLS are
 * pre-multiplied, their INDEX stays the state index, and the emitted read
 * divides. The division is the second operand of a `&&` whose first operand is
 * `__builtin_expect(pos + 1 >= n, 0)`, so C's short-circuit runs it at most
 * twice per search and never per byte; indexing these two tables by the
 * pre-multiplied value instead would multiply them by the stride (498 B ->
 * 8,964 B each on an `orig`-sized machine, ~1,100 more emitted lines) for a
 * table a search touches twice. The `(?:P)\z` idiom is the comparative
 * bench's own 85 compliance subjects' spelling, so that is the common case. */
static void emit_eol_table(StrBuf *c, const char *p, const char *tag,
                           const Dfa *d, const DfaRepr *r)
{
    sb_printf(c, "    static const %s %s_%s[%d] = {", r->cell_type, p, tag, d->n);
    for (int i = 0; i < d->n; i++) {
        if (i % 16 == 0) sb_puts(c, "\n       ");
        int v = d->st[i].eolvar;
        sb_printf(c, " %d,", v < 0 ? r->dead_cell : r->cell_of(v, d));
    }
    sb_puts(c, "\n    };\n");
}

/* The END-view table. Same shape as the EOL one, DIFFERENT MEANING for -1:
 * here it is "same as the EOL view", so the emitted selector below walks
 * endv -> ev -> self rather than testing one entry. */
static void emit_end_table(StrBuf *c, const char *p, const char *tag,
                           const Dfa *d, const DfaRepr *r)
{
    sb_printf(c, "    static const %s %s_%s[%d] = {", r->cell_type, p, tag, d->n);
    for (int i = 0; i < d->n; i++) {
        if (i % 16 == 0) sb_puts(c, "\n       ");
        int v = st_emit_endvar(&d->st[i]);
        sb_printf(c, " %d,", v < 0 ? r->dead_cell : r->cell_of(v, d));
    }
    sb_puts(c, "\n    };\n");
}


/* The SCALAR accept table — the bit for a position with NO next byte, which
 * §3.6.2 makes the UPC_PLAIN view's own accept (out of subject is neither a
 * word character nor a newline). Every state of a machine with no class axis
 * carries that same bit in all three views, so this is also the pre-wave
 * table, byte for byte. */
/* [OPT-3] Under the pre-multiplied form this table is INDEXED BY THE
 * PRE-MULTIPLIED VALUE, so that nothing on the loop's carried chain has to
 * un-multiply. That is `n * ncls` bytes where `n` would do — the transform's
 * one real cost, and the cost STEP 1's measured 1.276x already includes. The
 * cells that are not at a multiple of `ncls` are never read; they carry the
 * ROW'S OWN accept bit rather than zero, so the table is correct under any
 * index in the row and the loop does not silently depend on the
 * pre-multiplied value's low bits being zero.
 *
 * FUSING THE BIT INTO THE TRANSITION CELL was measured and is WORSE (STEP 1
 * §5: 8.095 vs 7.751 cycles/byte — unpacking puts an `and` back on the chain).
 * The probe stays a separate table read, off the chain, where the core absorbs
 * it: §5 measured the whole accept bookkeeping at 0.05 cycles/byte. */
static void emit_acc_table(StrBuf *c, const char *p, const char *tag,
                           const Dfa *d, const DfaRepr *r)
{
    int rep_n = r->acc_wide ? d->ncls : 1;
    sb_printf(c, "    static const unsigned char %s_%s[%d] = {", p, tag,
              d->n * rep_n);
    int k = 0;
    for (int i = 0; i < d->n; i++) {
        int bit = acc_cell(d, i);
        for (int rr = 0; rr < rep_n; rr++, k++) {
            if (k % 16 == 0) sb_puts(c, "\n       ");
            sb_printf(c, " %d,", bit);
        }
    }
    sb_puts(c, "\n    };\n");
}

/* [M6.2 wave B] Does THIS state's accept bit DEPEND ON THE NEXT BYTE? */
static bool state_acc_varies(const DState *st)
{
    for (int u = UPC_PLAIN + 1; u < UPC_N; u++) {
        if (!upc_emit_live(u)) continue;
        if ((bool)st->up[u].accept != (bool)st->up[UPC_PLAIN].accept)
            return true;
    }
    return false;
}

/* Does this state accept at a position whose next byte is in ANY class? The
 * OR over the class views, and §3.6.1 is emphatic about why the prefilter's
 * gate needs the OR rather than one bit. */
static bool state_acc_any(const DState *st)
{
    for (int u = 0; u < UPC_N; u++)
        if (upc_emit_live(u) && st->up[u].accept) return true;
    return false;
}

/* Does mechanism 4's runtime start dispatch change any answer? With every
 * interior start state interned to the same state the seed table would be a
 * constant column, so the pre-wave compile-time constant start is emitted
 * instead — which is what keeps every existing artifact's first lines
 * unmoved. */
static bool dfa_needs_seed(const Dfa *d)
{
    for (int u = UPC_PLAIN + 1; u < UPC_N; u++)
        if (upc_emit_live(u) && d->s1u[u] != d->s1u[UPC_PLAIN]) return true;
    return false;
}

/* [M6.2 wave D] Does this machine distinguish "the attempt begins AT
 * `startpos`" from "it begins after it" (assertions_design.md §4.2)? False
 * for every machine with no N_GSTART by construction — `pcrec_build_dfa`
 * assigns `s1g[u] = s1u[u]` there without closing anything — so a `\G`-free
 * artifact keeps its two-way start dispatch and its `start_max` string
 * character for character. This is the ONE predicate the emitter's `\G` code
 * is gated on; there is no `has_gstart` flag on the Dfa for a second site to
 * disagree with. */
static bool dfa_needs_gseed(const Dfa *d)
{
    for (int u = 0; u < UPC_N; u++)
        if (d->s1g[u] != d->s1u[u]) return true;
    return false;
}

/* Does THIS machine's table take the pre-multiplied form?
 *
 * ONE DERIVATION, THREE READERS — this file's standing rule (`unanch_start`,
 * `attempt_cand` and `dfa_engine_is_empty` each state it at length). The
 * emitted loop, `<PREFIX>_DFA_TABLE`'s value (through `dfa_table_name`) and
 * the orientation block's "READING THE TABLES" paragraph all come from here,
 * so none of the three can disagree with the loop it describes.
 *
 * THE SEED PRECONDITION is the third clause and it is not defensive padding.
 * `emit_seed_table`'s cells come from `d->s1u[]`, which can in principle be
 * -1 (a dead interior start state); that value flows straight into the state
 * variable, where today it would index `is_accepting[-1]` and premultiplied it
 * would index `[PREMUL_DEAD]` — a far wilder read for the same latent defect.
 * Measured 2026-08-26 over the 1,256 corpus patterns that compile under
 * `--features all`: no emitted seed table has a negative cell. Rather than
 * rest on that sweep, the transform REFUSES a machine that has one, so the
 * wilder read is unreachable by construction and the pre-existing `[-1]`
 * question is left exactly as it was — it is not [OPT-3]'s to answer. The loop
 * mirrors `emit_seed_table`'s own, so the two cannot disagree about which
 * cells are emitted. */
/* [ENG-FORM] `PCREC_NO_PREMUL_TABLE` IS NOT TESTED HERE ANY MORE. The deny
 * flag is the `deny` field of the pre-multiplied candidate (D82: "the deny
 * flag = a filter on the candidate list"), so `-fno-premul-table` REMOVES the
 * form from selection rather than making this predicate lie about the
 * machine's dimensions. What is left below is only the machine's own
 * arithmetic, which is what the comment above is about. */
static bool dfa_premul(Ctx *cx, const Dfa *d)
{
    (void)cx;
    long ents = (long)d->n * (long)d->ncls;
    if (ents > PREMUL_MAX_ENTRIES) return false;   /* the RANGE condition */
    if (dfa_needs_seed(d))
        for (int cl = 0; cl < d->ncls; cl++)
            if (d->s1u[upc_emit_of_class(d, cl)] < 0) return false;
    return true;
}


/* Are ALL of a family's interior start states dead? `s1u` answers "can an
 * attempt at `start > startpos` match at all"; `s1g` answers it for
 * `start == startpos`. §4.1's three-valued `start_max` is exactly the two
 * answers read together. */
static bool dfa_interior_dead(const int fam[UPC_N])
{
    for (int u = 0; u < UPC_N; u++) if (fam[u] >= 0) return false;
    return true;
}

/* Does ANY state's accept bit depend on the next byte?
 *
 * This is the exact condition for emitting §3.6's class-indexed accept table,
 * and it is deliberately NOT "the pattern contains `\b` or `(?m)$`": an
 * assertion that is not reachable at an accepting position leaves every
 * state's accept bits equal across the views, and such a pattern keeps the
 * pre-wave scalar accept and the pre-wave loop text. False for every state of
 * every machine with no class axis by construction (with no N_WORDB and no
 * N_EOL_M the closures coincide, src/ir/dfa.c), which is what makes the
 * corpus's artifacts unmoved. */
static bool dfa_has_clsacc(const Dfa *d)
{
    for (int i = 0; i < d->n; i++)
        if (state_acc_varies(&d->st[i])) return true;
    return false;
}

/* §3.6's accept table: `[states x ncls]`, the bit for "this state accepts at a
 * position whose NEXT byte is in class cl". Two source bits and a class map
 * decide every entry, so this table is derived, never a second opinion. */
static void emit_acc_cls_table(StrBuf *c, const char *p, const char *tag,
                               const Dfa *d)
{
    sb_printf(c, "    static const unsigned char %s_%s[%d] = {", p, tag,
              d->n * d->ncls);
    int k = 0;
    for (int i = 0; i < d->n; i++) {
        for (int cl = 0; cl < d->ncls; cl++, k++) {
            if (k % 16 == 0) sb_puts(c, "\n       ");
            sb_printf(c, " %d,", accw_cell(d, i, cl));
        }
    }
    sb_puts(c, "\n    };\n");
}

/* The class-axis context of a position whose next byte is a NEWLINE — the one
 * position ENG_ATTEMPT's EOL arm knows the byte at without reading it, since
 * `s[pos] == '\n'` is the arm's own entry condition.
 *
 * D64: derived from `pcrec_cls_newline`, the ONE definition, rather than from
 * a `'\n'` written here. A machine with no newline refinement answers
 * UPC_PLAIN, which is correct for it: nothing distinguishes the two views
 * there, so the bit is the same either way. */
static int upc_of_newline(const Dfa *d)
{
    for (int b = 0; b < 256; b++)
        if (cls_has(pcrec_cls_newline, (unsigned)b))
            return upc_emit_of_class(d, d->clsmap[b]);
    return UPC_PLAIN;
}

/* MECHANISM 4's seed table (§3.8.2): byte class of the context byte -> start
 * state. `ncls` entries, not 256 — the seed only has to distinguish classes,
 * and the alphabet refinement already guarantees the word set is a union of
 * them. It is read ONCE PER SEARCH, off the hot loop entirely.
 *
 * `s1u[]` are the interior start states, one per class-axis context of the
 * context byte; `s0` covers "no context byte exists", which every caller
 * handles with its own branch because the condition differs per machine
 * (`startpos == 0` forward, `end == n` reverse). */
static void emit_seed_table(StrBuf *c, const char *p, const char *tag,
                            const Dfa *d, const int fam[UPC_N], const DfaRepr *r)
{
    sb_printf(c, "    static const %s %s_%s[%d] = {", r->cell_type, p, tag, d->ncls);
    for (int cl = 0; cl < d->ncls; cl++) {
        if (cl % 16 == 0) sb_puts(c, "\n       ");
        int v = fam[upc_emit_of_class(d, cl)];
        /* [OPT-3] the pre-multiplied candidate's `applies` guarantees `v >= 0`
         * under that form; the branch is not a fallback, it is the assertion
         * written where a reader of the emitted table will look for it. */
        sb_printf(c, " %d,", v < 0 ? r->dead_cell : r->cell_of(v, d));
    }
    sb_puts(c, "\n    };\n");
}

/* ---- [D63] the CANDIDATE-START derivation: one site, two callers ---------
 *
 * A scan-avoidance mechanism has two halves, and D63 rules that exactly one of
 * them is shared. The DERIVATION — which byte VALUES can begin a match, how
 * many there are, whether that is one `memchr` or a 256-entry bitmap walk, and
 * the table for the bitmap case — is the SAME question for every engine, and
 * it lives here. The LOOP INTEGRATION differs structurally (ENG_UNANCH skips
 * WITHIN one scan while parked in its start state; ENG_ATTEMPT advances
 * BETWEEN attempts and composes with the three-way start dispatch) and stays
 * with each engine.
 *
 * The constraint is M2.12's lesson stated as a rule rather than as a warning:
 * "M2.7 forked a second copy, and the fork is exactly how the prefilter and
 * skip loops went missing from the `$` path for a whole milestone". D63
 * charters this as a TOOL — ENG_ATTEMPT's `(?m)^` instance is the first
 * customer and the only one built here, with D8's `^`-on-some-branches shape
 * and partial `\G` named as the next two, both of which are new CALLERS of
 * these three functions rather than new copies of them.
 *
 * THE ONE NEW CASE `(?m)^` ADDS is `offset`. ENG_UNANCH's candidates are
 * positions whose OWN byte is in the set; `(?m)^`'s are positions whose
 * PREDECESSOR is (a line start is the byte after a newline), so the candidate
 * is the found offset plus one. That is a field, not a fork. */
typedef struct {
    uint8_t set[256];   /* the candidate byte values */
    int     count;      /* how many */
    int     byte;       /* the single value when count == 1 */
    bool    usable;     /* a PROPER subset: worth filtering on at all */
    bool    use_memchr; /* usable and a single value */
    int     offset;     /* candidate position = found offset + offset */
} CandSet;

static void cand_derive(CandSet *cs, const uint8_t set[256], int offset)
{
    memcpy(cs->set, set, 256);
    cs->count = 0;
    cs->byte = 0;
    cs->offset = offset;
    for (int b = 0; b < 256; b++)
        if (cs->set[b]) { cs->count++; cs->byte = b; }
    /* NEITHER EXTREME IS FILTERABLE, and the two are different failures: an
     * empty set means the caller has already proved something stronger than a
     * prefilter (its own early-out), and a full one means every position is a
     * candidate, so the filter is pure cost. */
    cs->usable = cs->count > 0 && cs->count < 256;
    cs->use_memchr = cs->usable && cs->count == 1;
}

/* ENG_UNANCH's caller: the bytes on which the start state does not stay put —
 * i.e. the bytes that ADVANCE the pattern. A run of bytes outside this set
 * leaves the machine parked in `st`, so the scan may jump over it. */
static void cand_from_escapes(CandSet *cs, const Dfa *d, int st)
{
    uint8_t set[256];
    for (int b = 0; b < 256; b++)
        set[b] = (uint8_t)(d->st[st].tr[d->clsmap[b]] != st);
    cand_derive(cs, set, 0);
}

/* ENG_ATTEMPT's caller ([M6.2] wave C): the PREDECESSOR bytes after which an
 * attempt can still be alive. An attempt at `start > 0` enters
 * `s1u[upc_of_class(s[start-1])]`, so a predecessor byte whose seeded start
 * state is DEAD cannot begin a match and the attempt loop may skip it.
 *
 * This is `(?m)^`'s candidate set without naming `(?m)^` anywhere: for
 * `(?m)^ERROR` only the UPC_NL seed is live, so the set is the newline
 * definition and the derivation picks `memchr`; for a pattern with no
 * BOT-family node every seed is live, the set is all 256 and `usable` is
 * false, so nothing is emitted. `\b`-only patterns land there too — both
 * their seeds are live — which is why this costs wave B's artifacts nothing.
 *
 * `start == 0` is a candidate unconditionally (it enters `s0`, a different
 * state entirely) and every caller handles it with its own branch. */
static void cand_from_live_seeds(CandSet *cs, const Dfa *d)
{
    uint8_t set[256];
    for (int b = 0; b < 256; b++)
        set[b] = (uint8_t)(d->s1u[upc_emit_of_class(d, d->clsmap[b])] >= 0);
    cand_derive(cs, set, 1);
}

static void cand_emit_table(StrBuf *c, const char *p, const char *tag,
                            const CandSet *cs)
{
    emit_u8_table(c, p, tag, cs->set, 256);
}

/* Does ENG_ATTEMPT get a candidate-start prefilter, and what is it? ONE
 * derivation with TWO readers — emit_attempt, which emits the loop, and
 * pcrec_emit_prologue, which has to decide about `#include <string.h>` before
 * any body exists. A second copy of this test in the prologue is how the
 * artifact would end up calling `memchr` without declaring it. */
static bool attempt_cand(const Dfa *d, CandSet *cs)
{
    /* A fully-anchored pattern already runs ONE attempt (`start_max` is the
     * literal 0), so there is nothing between attempts to skip. */
    bool anchored = true;
    for (int u = 0; u < UPC_N; u++) if (d->s1u[u] >= 0) anchored = false;
    if (d->n == 0 || anchored) return false;
    cand_from_live_seeds(cs, d);
    /* THE MEMCHR FORM ONLY, and that is a deliberate scope line rather than an
     * oversight. D63 charters the derivation as a tool and says to build ONLY
     * the `(?m)^` instance now; MEASURED against today's construct set, that
     * instance's candidate set is always a SINGLE byte — a seeded start state
     * is dead only when all three of its class views are empty, which `(?m)^`
     * achieves (nothing passes without a newline to the left) and `\b`/`\B`
     * structurally cannot (their truth needs BOTH sides, so some view always
     * survives). So the bitmap loop integration would be EMITTED CODE NO
     * PATTERN REACHES, and shipping an untested emitted loop is worse than
     * shipping none.
     *
     * The DERIVATION still handles the bitmap case (`cand_derive` computes it
     * and `cand_emit_table` emits it — ENG_UNANCH's caller uses exactly that
     * path today), so D63's next instance adds a LOOP, not a second
     * derivation. D8's `^`-on-some-branches shape is that instance: its
     * candidate set is a first-byte set at offset 0, which is both multi-byte
     * and a different bound, and D63 gates it on its own measurement. */
    return cs->usable && cs->use_memchr;
}

/* ---- [DD-13] THE UNANCHORED ENGINE'S START ANALYSIS: one derivation -------
 *
 * WHY IT IS A FUNCTION NOW. Everything below used to be the first forty lines
 * of `emit_unanchored`, which was fine while the emitted loop was its only
 * reader. D46 adds a SECOND reader — the artifact's `<PREFIX>_DFA_PREFILTER`
 * stamp, written before the engine body exists — and this file's own rule for
 * that situation is `attempt_cand`'s (immediately above): ONE derivation with
 * TWO readers, never a restatement of the condition at the second site. M2.12
 * states the cost of the alternative in this file's header: "M2.7 forked a
 * second copy, and the fork is exactly how the prefilter and skip loops went
 * missing from the `$` path for a whole milestone." A stamp that re-derived
 * `prefilter` would be that fork with a `#define` on the end of it — and a
 * stamp that disagrees with the loop it describes is worse than no stamp.
 *
 * THE FLAGS ARE HERE FOR THE SAME REASON AND NOT FOR TIDINESS: `views` is what
 * separates `<PREFIX>_DFA_PREFILTER`'s two bound forms (plan.md [DD-13] (b):
 * the `\z` spelling's skip runs `pos + 1 < n` and cannot early-exit), so the
 * stamp reads the same flag the emitted `fbound` string is built from.
 *
 * NOTHING HERE EMITS. The struct is facts; every `sb_*` call stays in
 * `emit_unanchored`, so this function is safe to call from the stamp path
 * (where no engine body is being written) as often as it likes. */
typedef enum {
    DFA_PF_NONE = 0,     /* no candidate-start filter at all */
    DFA_PF_MEMCHR,       /* ONE candidate byte value: a memchr() replaces the steps */
    DFA_PF_BYTE_CLASS    /* several: the 256-entry can_begin_match bitmap walk */
} DfaPfKind;

typedef struct {
    /* the three EOL/END/word-context flags, kept apart on purpose because they
     * gate different things (each one's own note is at its use site below). */
    bool eol, endv, viewsel;
    bool views;          /* the D11 flag: a skip may pass a position whose
                          * accept was not the one evaluated -> every skip is
                          * bounded at n-1 and the prefilter loses its early-out */
    bool empty;          /* nothing can match: the whole body is one `return 0` */
    DfaPfKind kind;      /* the prefilter the forward scan carries */
    CandSet   cand;      /* D63's candidate set; meaningful when kind != NONE */
    /* [OPT-K] THE OFFSET-k SKIP'S SELECTION, derived from the same call and
     * read by the same two readers. `ofsk.nsel == 0` — the answer for every
     * pattern before this row and for most patterns after it — means the
     * forward scan carries exactly the offset-0 filter `kind` names above.
     * docs/design/offset_k_skip.md. */
    PrefixKSets ofsk;
} UnanchStart;

static void unanch_start(Ctx *cx, UnanchStart *o)
{
    const Dfa *fd = &cx->job->dfa, *rd = &cx->job->rdfa;
    memset(o, 0, sizeof *o);
    o->kind = DFA_PF_NONE;

    o->eol  = dfa_has_eolvar(fd) || dfa_has_eolvar(rd);
    /* [M6.2 wave A] `\z`'s third view. `views` is the flag every site that
     * used to read `eol` now reads: what the D11 bound and the evaluation
     * ORDER protect is "a state can accept at a position a skip would pass",
     * and an END view creates exactly that situation at `pos == n`. Both are
     * false for every pattern the pre-wave corpus contains, so `views == eol`
     * there and nothing moves. */
    o->endv = dfa_has_endvar(fd) || dfa_has_endvar(rd);
    /* Does the emitted text carry the `est`/`erst` POSITION-view indirection
     * at all? Only `$`/`\Z`/`\z` create it. `\b` does not: its axis is the
     * byte class, which the transition lookup already indexes by. */
    o->viewsel = o->eol || o->endv;
    /* `wctx` — this machine carries a word context at all, so mechanism 4's
     * start seeding applies (§3.8) and the D11 evaluation ORDER must be the
     * views one. (Its sibling `facc2`/`racc2` — some state's accept actually
     * VARIES with the next byte — gates §3.6's class-indexed accept table
     * instead, and stays with the emitter: a pattern can have the first
     * without the second.) */
    bool wctx = fd->clsctx || rd->clsctx;
    /* `views` is the D11 flag: "a state can accept at a position a skip would
     * pass, or the position a skip lands on is not the position whose accept
     * was evaluated". The EOL and END views create that at the last two
     * positions; a word context creates it everywhere, so it joins. */
    o->views = o->viewsel || wctx;

    int fs = fd->s0;   /* no asserts -> s0 == s1 */
    int rs = rd->s0;
    if (fs < 0 || rs < 0) { o->empty = true; return; }

    /* start-state prefilter analysis: bytes that advance the pattern.
     *
     * [M6.2 wave B] `start_acc` is "accepts on ANY class", the OR over the
     * class views, and §3.6.1 is emphatic about why. The prefilter skips runs
     * of bytes at which the machine provably stays parked in `fs`; if `fs`
     * accepts on SOME classes and this read one bit, a pattern like `\bx*`
     * would keep its `memchr('x')` and jump straight past the empty matches
     * it owes at every word boundary. MEASURED cell, through the find-all
     * loop: `\bx*` on `'a x'` is [(0,0), (1,1), (2,3), (3,3)] and a
     * one-bit `start_acc` reports only (2,3).
     *
     * It is also the analysis for the start state's OTHER seeded forms —
     * `s1u[]` under mechanism 4 — so those are OR'd in too: with
     * `startpos > 0` the machine begins in one of those, and a prefilter
     * decision taken from `s0` alone would be a decision about a state the
     * search may never occupy.
     *
     * [M6.2 wave C] THE WIDENING IS BELT-AND-BRACES, NOT LOAD-BEARING, and
     * that is a correction to the paragraph above — §3.6.1's `\bx*` cell does
     * NOT lose three of four matches under a one-bit read. The reason is the
     * argument this file already makes for the `last == (size_t)-1` gate
     * further down: D3's accept-pruning cuts the unanchored start self-loop
     * out of every accepting closure, so a class the start state ACCEPTS on
     * cannot transition back to the start state — it ESCAPES — so the
     * prefilter's stay set never contains it and the skip never passes an
     * accepting position.
     *
     * MEASURED, [M6.2] wave C: narrowing to `fd->st[fs].up[UPC_PLAIN].accept`
     * changes 21 corpus artifacts and 0 answers, over 2,247 find-all cells
     * (21 patterns x 107 subjects). Keep the widening — it is free and it is
     * the honest reading of "accepts on any class" — but do not cite it as a
     * premise, and note that it therefore ships NO sabotage row: a check with
     * no failing direction is exactly what this file's own neighbouring
     * comment warns about. */
    bool start_acc = state_acc_any(&fd->st[fs]);
    bool fseed = dfa_needs_seed(fd);
    if (fseed) {
        for (int u = 0; u < UPC_N; u++)
            start_acc = start_acc || state_acc_any(&fd->st[fd->s1u[u]]);
    }
    /* [D63] THE SHARED DERIVATION, this engine's caller. */
    cand_from_escapes(&o->cand, fd, fs);
    /* "can neither accept nor ever leave the start state" is only a proof
     * that nothing matches when the start state has no EOL view. `$` alone is
     * exactly the counter-example: it never leaves fs and forward_is_accepting[fs] is 0, but
     * its EOL variant accepts.
     *
     * [M6.2 wave B] `!fseed` joins the conjunction: the proof is about the ONE
     * start state `fs`, and under mechanism 4 a search at `startpos > 0`
     * begins in a different state whose escapes and accepts this analysis
     * never looked at. With `fseed` false there is only one start state and
     * the pre-wave argument is unchanged. */
    if (o->cand.count == 0 && !start_acc && !fseed && fd->st[fs].eolvar < 0 &&
        st_emit_endvar(&fd->st[fs]) < 0) { o->empty = true; return; }

    /* The prefilter stays valid under EOL because it is BOUNDED AT n-1: it
     * only ever skips non-EOL positions at which the machine provably stays
     * parked in fs.
     *
     * The `last == (size_t)-1` gate on the emitted `if` is NOT part of that
     * argument, and this comment used to present the two as jointly
     * load-bearing (R3.2 critic). The gate is redundant given D3's priority
     * pruning: the unanchored start self-loop is the LOWEST-priority thread,
     * so it is pruned out of every accepting state, an accepting state's
     * successors can therefore never be `fs`, and `last` is only ever set from
     * an accepting view — so `st == fs` already implies `last == -1`. Two
     * independent critics attacked the gate and neither could build a witness:
     * deleting it produced 0 divergences over 8.0M oracle-checked comparisons
     * and 0 failures across the whole .rxt corpus.
     *
     * Keep the gate — it is free belt-and-braces — but do not cite it as a
     * premise. Presenting a redundant condition and a load-bearing one as the
     * same claim is how someone eventually "simplifies away" the wrong half. */
    if (!start_acc && o->cand.usable)
        o->kind = o->cand.use_memchr ? DFA_PF_MEMCHR : DFA_PF_BYTE_CLASS;

    /* [OPT-K] THE OFFSET-k SELECTION RIDES THE OFFSET-0 VERDICT and is never
     * asked independently of it. Everything the skip inherits is proved
     * above: `!start_acc` is what says the machine cannot accept while parked
     * (so no position the skip passes can be an empty match), and
     * `cand.usable` is what says there is a proper subset to filter on at
     * all. A k-set selected without them would be a second, weaker version of
     * an argument this function already makes — the fork D63's header
     * forbids. */
    if (o->kind != DFA_PF_NONE)
        pcrec_prefix_ksets(cx, &cx->job->nfa, o->cand.set, &o->ofsk);
#ifdef OPTK_DEBUG
    { extern void optk_debug_dump(const PrefixKSets *); optk_debug_dump(&o->ofsk); }
#endif
}

/* ---- [DD-13c] IS THIS ARTIFACT'S SEARCH BODY THE EMPTY ENGINE? -----------
 *
 * BOTH ENGINES HAVE ONE, and that is why this is a function rather than a
 * clause inside the stamp. A pattern the analysis proves can match nothing
 * emits a search body that is one `return 0` — no table, no loop, no skip —
 * and BOTH emitters below take that exit: `emit_unanchored` on
 * `unanch_start`'s `empty` (its two causes are that function's), `emit_attempt`
 * on `d->n == 0` (no live start state at all). Corpus witnesses exist for both
 * (`\B\b` unanchored; `^\B\b` under ENG_ATTEMPT).
 *
 * WHY IT EXISTS AT ALL. r37 finding #5: those artifacts used to stamp
 * `<PREFIX>_DFA_SCAN "unanchored"` — a loop they do not contain — because the
 * stamp read `job->engine` alone, which names WHICH EMITTER RAN and not
 * WHICH BODY IT WROTE. The two are the same question for every other artifact
 * and a different one here, so the stamp now has a third value (`"empty"`,
 * docs/spec/match_api.md §6.3) and this is its derivation.
 *
 * ONE DERIVATION, TWO READERS, this file's standing rule (`unanch_start` and
 * `attempt_cand` state it at length): `emit_attempt`'s early exit calls THIS
 * function rather than re-spelling `d->n == 0`, so the stamp cannot say
 * "empty" about a body that has a loop in it, nor stay silent about one that
 * does not. `emit_unanchored` reads the SAME `UnanchStart` it emits from —
 * one call, both facts — which is the same guarantee spelled the other way.
 *
 * NOTHING HERE EMITS, so the stamp path may call it before any body exists.
 * `unanch_start` is side-effect-free and cheap (no allocation), which is what
 * makes the twice-per-artifact call unremarkable. */
static bool dfa_engine_is_empty(Ctx *cx)
{
    if (cx->job->engine == PCREC_ENG_ATTEMPT) return cx->job->dfa.n == 0;
    UnanchStart us;
    unanch_start(cx, &us);
    return us.empty;
}

/* [OPT-3] WHICH TABLE FORM this artifact's DFA scan carries
 * (docs/design/premultiplied_dfa_table.md §8, docs/spec/match_api.md §6.3).
 *
 * ONE DERIVATION, THREE READERS — `dfa_premul`, called here, by
 * `emit_unanchored`'s loop and by the orientation block's "READING THE TABLES"
 * paragraph. The stamp cannot disagree with the loop it describes unless the
 * predicate itself is wrong, in which case the loop is wrong too. This is the
 * same construction `dfa_scan_name` and `dfa_prefilter_name` are built on and
 * for the same reason (this file's header, M2.12).
 *
 * `"mixed"` IS A REAL VALUE, not defensive padding: the bound is decided PER
 * MACHINE on that machine's own `n * ncls`, so a pattern whose forward DFA is
 * above it and whose reverse DFA is below it takes one form of each. Naming
 * that is cheaper than a rule claiming it cannot happen.
 *
 * `"none"` IS NOT A FAILURE either. ENG_ATTEMPT's states are LABELS and a step
 * is `goto *targets_K[class]` — there is no numeric transition table to
 * pre-multiply, no state variable and no address arithmetic to shorten, so the
 * transform would be a no-op there (design note §4). The empty engine has no
 * loop at all. Both answer "none", and `dfa_engine_is_empty` is asked FIRST for
 * `dfa_scan_name`'s own reason (r37 #5). */
static const char *dfa_table_name(Ctx *cx)
{
    if (dfa_engine_is_empty(cx)) return "none";
    if (cx->job->engine == PCREC_ENG_ATTEMPT) return "none";
    /* [ENG-FORM] THE STAMP IS THE CHOSEN OBJECT'S NAME. It is not a second
     * reading of the predicate that chose it — it is the same pointer the
     * loop was emitted through, so "one derivation, three readers" is
     * structural here rather than a convention this function keeps. */
    const char *f = dfa_repr_of(cx, &cx->job->dfa)->c.name;
    /* [OPT-5 STEP 2] A COMPOSITION MUST NOT NAME A MACHINE THE ARTIFACT DOES
     * NOT CONTAIN, which is the mirror image of the defect [ENG-ABS] avoided
     * when it ADDED the anchored machine to this fold. Axis J's `pinned` form
     * emits no reverse machine — no tables, no accessor block, no loop — so
     * reading `job->rdfa` here would let a pinned artifact stamp `"mixed"`
     * about text that is not in it. Asked through the SAME selection the body
     * was emitted through, never a second reading. */
    if (!dfa_search_is_pinned(cx)) {
        const char *r = dfa_repr_of(cx, &cx->job->rdfa)->c.name;
        if (strcmp(f, r)) return "mixed";
    }
    /* [ENG-ABS] THE COMPOSITION SPANS EVERY MACHINE THE ARTIFACT CARRIES, and
     * after this row that is three rather than two whenever axis G selected
     * `unwrapped`. `RX_DFA_TABLE` is an artifact-level composition (spec
     * S6.3), so leaving the anchored machine out would let the stamp say
     * "premultiplied" about an artifact holding an indexed table — the exact
     * disagreement between a stamp and a body this file's rule exists to make
     * impossible. It can move an artifact's value from a form name to
     * `"mixed"`; the form census counts the populations. */
    if (dfa_match_is_unwrapped(cx) &&
        strcmp(f, dfa_repr_of(cx, &cx->job->adfa)->c.name)) return "mixed";
    return f;
}

/* [OPT-5] `<PREFIX>_DFA_SCAN_EDGE` — WHICH CLASS TEST THE ARTIFACT'S SCAN
 * EDGES USE, or `"none"` where it has none. Composed over every machine the
 * artifact carries, `dfa_table_name`'s own shape and for its own reason: it
 * is an artifact-level fact (spec §6.3), so leaving the anchored machine out
 * would let it say `"range"` about an artifact carrying a membership table.
 *
 * The four values are `none` / `range` / `bitmap` / `mixed`, and they are a
 * COST statement rather than a decoration: `range` is a subtract-and-compare
 * against immediates, `bitmap` is a 256-byte table read per byte, and a
 * consumer picking between two spellings of a class can see which it got. The
 * value comes off `pcrec_scan_range` — the same predicate the emitted test is
 * written from, never a second reading of "is this class contiguous". */
static const char *scan_edge_of(Ctx *cx, const Dfa *d, const char *so_far)
{
    for (int i = 0; i < d->n; i++) {
        /* AXIS H first: a state the region axis did not give an edge to has
         * no body to name. Then AXIS I's chosen object's own `c.name` IS the
         * value (D82 rule 2) -- never a second reading of the predicate that
         * chose it. */
        if (!dfa_edge_taken(dfa_edge_of(cx, d, i))) continue;
        const char *v = dfa_scan_body_name(cx, d, i);
        if (!strcmp(so_far, "none")) so_far = v;
        else if (strcmp(so_far, v)) return "mixed";
    }
    return so_far;
}

static const char *dfa_scan_edge_name(Ctx *cx)
{
    if (dfa_engine_is_empty(cx)) return "none";
    if (cx->job->engine == PCREC_ENG_ATTEMPT) return "none";
    const char *v = scan_edge_of(cx, &cx->job->dfa, "none");
    /* [OPT-5 STEP 2] The reverse machine drops out of this fold on a pinned
     * artifact, for `dfa_table_name`'s reason exactly — and it MATTERS more
     * here than there, because on the shapes at issue the reverse machine
     * grows edges more readily than the forward one (r48sem measured `mc2`
     * at forward 0 edges against reverse 4), so a pinned artifact would
     * otherwise stamp `"range"` or `"bitmap"` while carrying no edge at all. */
    if (strcmp(v, "mixed") && !dfa_search_is_pinned(cx))
        v = scan_edge_of(cx, &cx->job->rdfa, v);
    if (strcmp(v, "mixed") && dfa_match_is_unwrapped(cx))
        v = scan_edge_of(cx, &cx->job->adfa, v);
    return v;
}

/* [CC-DIFF] `<PREFIX>_DFA_UNIFORM_FOLDS` — HOW MANY OF THIS ARTIFACT'S DFA
 * TABLES THE UNIFORM FOLD REMOVED. A COUNT, and deliberately not a mask: the
 * three masks in §6.3 are masks because a rung or a strategy is chosen PER
 * QUANTIFIER and a scalar would LIE on a mixed artifact, where this is a
 * whole-artifact total with no axis to mix. Two tables per machine are
 * foldable (`<m>_next_state`, `<m>_is_accepting`), so the value runs 0..6.
 *
 * WHY IT IS OWED RATHER THAN SYMMETRY. The fold makes a table ABSENT, and
 * this project has gone back and REMOVED a check that read a fact off a
 * macro's absence twice ([DD-13], and [OPT-1]'s `_FAST_FRAMES` before it).
 * Without this line the only way to see the fold is to grep the emitted C for
 * an array that is not there. `tests/codegen/run_dfa_uniform_fold.sh` reads
 * this number and nothing else.
 *
 * IT IS FAMILY (b), for `<PREFIX>_VM_FRAMELESS`'s reason exactly and not a
 * new one: there is no fold mode anywhere upstream and no pass decides it —
 * it is what the emitted machine turned out to CONTAIN, discovered while the
 * emitter held the table. Its scope is the `_DFA_*` family's IFF, every
 * artifact CONTAINING a DFA scan, hybrids included.
 *
 * THE MACHINE COMPOSITION IS `dfa_table_name`'s, ASKED THE SAME WAY: the
 * reverse machine drops out of a start-pinned artifact (it is not there to
 * fold) and the anchored machine joins only under `unwrapped`. A count that
 * included a machine the artifact does not contain would be the same defect
 * that paragraph exists to name, arriving through a third door. */
static int uniform_folds_of(Ctx *cx, const Dfa *d)
{
    const DfaRepr *r = dfa_repr_of(cx, d);
    return (fold_tr(d, r).folded ? 1 : 0) + (fold_acc(d).folded ? 1 : 0);
}

static int dfa_uniform_folds(Ctx *cx)
{
    /* An empty scan has no machine, and ENG_ATTEMPT's states are LABELS with
     * no numeric transition table and no scalar accept table to fold — the
     * same two exclusions `dfa_table_name` opens with, for the same reason. */
    if (dfa_engine_is_empty(cx)) return 0;
    if (cx->job->engine == PCREC_ENG_ATTEMPT) return 0;
    int n = uniform_folds_of(cx, &cx->job->dfa);
    if (!dfa_search_is_pinned(cx)) n += uniform_folds_of(cx, &cx->job->rdfa);
    if (dfa_match_is_unwrapped(cx)) n += uniform_folds_of(cx, &cx->job->adfa);
    return n;
}


/* ---- ENG_UNANCH: table-driven forward + reverse (D7) ---- */

/* M2.1 self-loop skip: pick up to 4 states (excluding `exclude`) that stay
 * put on >= 192 of 256 bytes — their scan degenerates to a SIMD-friendly
 * skip loop. Motivated by compare case h (`.*=.*`): the post-'=' state
 * self-loops on everything but '\n' in both machines.
 *
 * M2.10 tried replacing this absolute byte count with a fraction of the
 * state's LIVE bytes, so that narrow-alphabet patterns like `[01]*1[01]{8}`
 * (2 live bytes, 100% stay) would qualify — R2-A5 had described that case as
 * having "no skip-eligible states". The reasoning was sound and the result
 * was a REGRESSION: it gives case (f) one reverse skip table and measures
 * 158.6/159.1 -> 118.7 MB/s on the compare harness and 159.1/157.5 ->
 * 115.9/115.8 MB/s on bdriver, spreads 1.01-1.02x, i.e. ~27% slower on the
 * exact case it was meant to fix. Reverted; see D13 and the 2026-08-09
 * journal entry. Do not re-attempt without measuring the REVERSE machine
 * specifically — the suspicion is that a backward byte-at-a-time skip loop
 * loses to the reverse table walk, but that is untested. */
static int pick_skip_states(const Dfa *d, int exclude, int out[4])
{
    int cls_size[256] = {0};
    for (int b = 0; b < 256; b++) cls_size[d->clsmap[b]]++;
    int nout = 0;
    for (int pass = 0; pass < 4; pass++) {
        int best = -1, bestcnt = 191;
        for (int i = 0; i < d->n; i++) {
            if (i == exclude) continue;
            /* [M6.2 wave B] A STATE WHOSE ACCEPT DEPENDS ON THE NEXT BYTE IS
             * NOT SKIP-ELIGIBLE, and this is the D11-rule-1 hazard §3.6.1
             * describes, resolved by declining rather than by intersecting.
             *
             * A skip advances without consulting accept flags and records
             * only its LANDING position. That is sound while the accept bit
             * is constant across the run — which the pre-wave scalar accept
             * made true unconditionally, and a class-indexed one does not.
             * The concrete loss: a forward skip whose run's bytes all accept
             * landing on a byte whose class does not, with `last` wanting the
             * LARGEST accepting position, throws away every position it just
             * passed.
             *
             * §3.6.1 argues from §3.5 that `\b` cannot reach this, on the
             * ground that a skip set is a union of classes and therefore
             * pins next-is-word across the run. THE SECOND HALF DOES NOT
             * FOLLOW: a union of classes may perfectly well contain both word
             * and non-word classes (a state that stays put on both `a` and
             * ` ` has exactly such a stay set). So the argument is not
             * available and this declines instead. Declining is always safe
             * and costs nothing on any pattern without a next-byte-sensitive
             * accept — i.e. nothing in the pre-wave corpus, where this test
             * is false at every state. */
            if (state_acc_varies(&d->st[i])) continue;
            /* [OPT-5] A STATE CARRYING A SCAN EDGE IS NOT SKIP-ELIGIBLE, and
             * this is a structural exclusion rather than a preference: the
             * scan edge's own soundness argument (src/opt/scanedge.c's
             * header) is that nothing between it and the step advances the
             * position, and a stay skip at the same state fires BEFORE it and
             * does exactly that. Its interior states are gone by then, so the
             * step that followed such a skip would read a table cell the pass
             * killed. Costs nothing on any machine without a scan edge, which
             * is every machine in the pre-[OPT-5] corpus.
             *
             * IT READS THE ANNOTATION AND NOT AXIS H, which is the honest
             * question rather than a shortcut past the selection: what this
             * exclusion needs to know is whether the PASS left a run's
             * interior deleted here, and this function has no `Ctx` to ask
             * an axis through. The two agree in both directions anyway —
             * under `-fno-scan-edge` the pass writes no annotation, so
             * neither the axis nor this test can be true. */
            if (d->st[i].scan_span != 0) continue;
            bool taken = false;
            for (int k = 0; k < nout; k++)
                if (out[k] == i) taken = true;
            if (taken) continue;
            int stay = 0;
            for (int cl = 0; cl < d->ncls; cl++)
                if (d->st[i].tr[cl] == i) stay += cls_size[cl];
            if (stay > bestcnt) { bestcnt = stay; best = i; }
        }
        if (best < 0) break;
        out[nout++] = best;
    }
    return nout;
}

static void emit_stay_table(StrBuf *c, const char *p, const char *tag,
                            int idx, const Dfa *d)
{
    uint8_t stay[256];
    for (int b = 0; b < 256; b++)
        stay[b] = (uint8_t)(d->st[idx].tr[d->clsmap[b]] == idx);
    /* [K38's rule, [ENG-FORM]] The one fixed buffer this function owns is
     * sized by the SHARED emitted-name constant, not by a hand guess: `tag`
     * reaches here from a caller's own `PCREC_MAX_EMIT_NAME_LEN` buffer now,
     * and 32 was a number that happened to fit the two literals it used to
     * be handed. */
    char name[PCREC_MAX_EMIT_NAME_LEN + 16];   /* + the state number */
    snprintf(name, sizeof(name), "%s%d", tag, idx);
    emit_u8_table(c, p, name, stay, 256);
}

/* ---------------------------------------------------------------------
 * [M6-READ] LEGENDS: the block comments that make a table readable.
 *
 * Both are computed from the very data this file is about to write -- the
 * class map and the transition table themselves -- so neither can drift from
 * the table it describes. That is the plan row's engineering note (iv), "the
 * emitter tags what it emits, no after-the-fact inference", satisfied without
 * a tagging pass: a walk over emitter-owned data IS the tag.
 * --------------------------------------------------------------------- */

/* One byte rendered for a human: printable ASCII quoted, everything else as a
 * number. Legend text only; never emitted as code. */
static void legend_byte(StrBuf *c, int b)
{
    if (b == '\'')      sb_puts(c, "'\\''");
    else if (b == '\\') sb_puts(c, "'\\\\'");
    else if (b >= 0x20 && b < 0x7f) sb_printf(c, "'%c'", b);
    else                sb_printf(c, "%d", b);
}

/* WHICH BYTES EACH CLASS HOLDS, as ranges. Class 0 is named rather than
 * enumerated: it is the catch-all, and listing its ranges is pages of noise
 * that tells the reader nothing. */
static void emit_class_legend(StrBuf *c, const Dfa *d)
{
    sb_printf(c, "     * Class legend (%d classes; every byte not listed is class 0):\n",
              d->ncls);
    sb_puts(c, "     *   0  every other byte\n");
    for (int cl = 1; cl < d->ncls; cl++) {
        sb_printf(c, "     *   %d  ", cl);
        int shown = 0, b = 0;
        while (b < 256 && shown < 8) {
            if (d->clsmap[b] != cl) { b++; continue; }
            int a = b;
            while (b + 1 < 256 && d->clsmap[b + 1] == cl) b++;
            if (shown) sb_puts(c, ", ");
            legend_byte(c, a);
            if (b != a) { sb_puts(c, "-"); legend_byte(c, b); }
            shown++; b++;
        }
        if (b < 256) sb_puts(c, ", ...");
        sb_puts(c, "\n");
    }
}

/* WHAT EACH STATE MEANS, as the SHORTEST INPUT THAT REACHES IT -- a
 * breadth-first search over the transition table below, using each class's
 * representative byte.
 *
 * The example string IS the state's meaning, and it needs no knowledge of the
 * pattern's syntax: a reader comparing two adjacent states sees exactly what
 * the machine just consumed. On the reverse machine the walk consumes the
 * match right-to-left, so the examples read backwards and the banner says so.
 *
 * Capped: past LEGEND_MAX_STATES a full listing is noise rather than
 * orientation, so only the start and the accepting states are named and the
 * comment says what it left out. */
#define LEGEND_MAX_STATES 48
/* A state deep in the machine has an example as long as its distance from
 * the start; past this many bytes the string stops orienting anyone. */
#define LEGEND_MAX_EXAMPLE 40

static void emit_state_legend(StrBuf *c, const Dfa *d, bool reverse)
{
    int *dist  = malloc((size_t)d->n * sizeof(int));
    int *from  = malloc((size_t)d->n * sizeof(int));
    int *via   = malloc((size_t)d->n * sizeof(int));
    int *queue = malloc((size_t)d->n * sizeof(int));
    /* [OPT-5] `path` IS NOT SIZED BY THE STATE COUNT ANY MORE, and the change
     * is a bounds fix rather than a tidy-up. It holds the example input for
     * the deepest state, which used to be at most one byte per state because
     * every edge cost one byte — and a SCAN EDGE costs its whole span, so
     * `[a-z]{0,16384}`'s two-state machine has a state 16,384 bytes deep. It
     * is allocated after the walk, from the deepest distance the walk
     * actually found. */
    int *path  = NULL;
    if (!dist || !from || !via || !queue) {
        free(dist); free(from); free(via); free(queue);
        return;                    /* a legend is never worth failing a compile over */
    }
    for (int i = 0; i < d->n; i++) { dist[i] = -1; from[i] = -1; via[i] = -1; }
    int head = 0, tail = 0;
    if (d->s0 >= 0 && d->s0 < d->n) { dist[d->s0] = 0; queue[tail++] = d->s0; }
    while (head < tail) {
        int s = queue[head++];
        for (int cl = 0; cl < d->ncls; cl++) {
            int nx = d->st[s].tr[cl];
            if (nx < 0 || nx >= d->n || dist[nx] >= 0) continue;
            dist[nx] = dist[s] + 1; from[nx] = s; via[nx] = cl;
            queue[tail++] = nx;
        }
        /* [OPT-5] THE SCAN EDGE IS AN EDGE, and this walk has to follow it or
         * the legend goes silently wrong. The run's interior states are gone
         * from the table, so a state reachable only THROUGH one would print
         * "no path through the transitions above" — true of the transitions
         * and false of the machine. It costs `span` bytes of the edge's class
         * rather than one, which `rep[via[]]` below renders by repeating the
         * class's representative that many times. An unbounded edge is a
         * self-loop and adds no reachability. */
        int span = d->st[s].scan_span, nx = d->st[s].scan_next;
        if (span > 0 && nx >= 0 && nx < d->n && dist[nx] < 0) {
            dist[nx] = dist[s] + span; from[nx] = s;
            via[nx] = d->st[s].scan_cls;
            queue[tail++] = nx;
        }
    }

    int maxd = 0;
    for (int i = 0; i < d->n; i++) if (dist[i] > maxd) maxd = dist[i];
    path = malloc((size_t)(maxd + 1) * sizeof(int));
    if (!path) { free(dist); free(from); free(via); free(queue); return; }

    /* How many states accept? In a big machine this decides whether a listing
     * is orientation or noise -- `((a)|b){0,4000}c` has 4002 accepting states,
     * and naming them all cost 4000 lines and tripled the artifact. Caught by
     * the [ENG-BREP] emitted-size check, which is exactly what it is for. */
    int nacc = 0;
    for (int i = 0; i < d->n; i++) if (d->st[i].up[UPC_PLAIN].accept) nacc++;

    bool brief = d->n > LEGEND_MAX_STATES;
    if (brief) {
        /* A SUMMARY, not a truncated list. Which particular states accept is
         * not orientation once there are thousands of them; how many there
         * are, and what the shortest accepted input looks like, is. */
        int shortest = -1;
        for (int i = 0; i < d->n; i++)
            if (d->st[i].up[UPC_PLAIN].accept && dist[i] >= 0 &&
                (shortest < 0 || dist[i] < dist[shortest])) shortest = i;
        sb_printf(c, "     * State legend -- %d states, %d of them accepting: too many\n"
                     "     * to name individually. The start state is %d",
                  d->n, nacc, d->s0);
        if (shortest >= 0)
            sb_printf(c, ", and the\n"
                         "     * shortest input reaching an accepting state is %d byte(s) long",
                      dist[shortest]);
        sb_puts(c, ".\n");
        free(dist); free(from); free(via); free(queue); free(path);
        return;
    }
    if (reverse)
        sb_puts(c, "     * State legend -- the bytes this walk consumes, IN WALK\n"
                   "     * ORDER, i.e. the match read backwards:\n");
    else
        sb_puts(c, "     * State legend -- the shortest input that reaches each state:\n");
    for (int i = 0; i < d->n; i++) {
        bool acc = d->st[i].up[UPC_PLAIN].accept != 0;
        /* NOT "unreachable": this walk follows the plain transitions only, and
         * a state can also be selected by a POSITION VIEW (end of subject, end
         * of line) that has no edge in the table below. Saying what the walk
         * actually established is the honest claim; saying the state is dead
         * would be wrong, and is wrong on `^ab(c|d)e$` today. */
        if (dist[i] < 0) {
            sb_printf(c, "     *  %3d  (no path through the transitions above;\n"
                         "     *       a position view can still select it)\n", i);
            continue;
        }
        sb_printf(c, "     *  %3d  ", i);
        if (dist[i] == 0) sb_puts(c, "(start) nothing consumed yet");
        else {
            int len = dist[i], k = len, s = i;
            /* One HOP is no longer one BYTE: a scan edge's hop costs its
             * whole span, and the distance difference across the hop is
             * exactly how many copies of its class this example needs. */
            while (k > 0 && from[s] >= 0) {
                int p = from[s], step = dist[s] - dist[p];
                for (int j = 0; j < step && k > 0; j++) path[--k] = via[s];
                s = p;
            }
            sb_puts(c, "\"");
            int shown = len < LEGEND_MAX_EXAMPLE ? len : LEGEND_MAX_EXAMPLE;
            for (k = 0; k < shown; k++) {
                int b = d->rep[path[k]];
                if (b >= 0x20 && b < 0x7f && b != '"' && b != '\\')
                    sb_printf(c, "%c", b);
                else sb_printf(c, "\\x%02x", b);
            }
            sb_puts(c, "\"");
            if (shown < len) sb_printf(c, "... (%d bytes)", len);
        }
        if (acc) sb_puts(c, "   ACCEPTING");
        /* [OPT-5] and, where this state carries one, the SCAN EDGE -- because
         * the transition row printed above says "dead" for that class and a
         * reader who took the table at its word would conclude the machine
         * stops there. This line is the table's own footnote. */
        if (d->st[i].scan_span < 0)
            sb_printf(c, "\n     *       scan edge: any run of class %d stays here",
                      d->st[i].scan_cls);
        else if (d->st[i].scan_span > 0)
            sb_printf(c, "\n     *       scan edge: %d of class %d -> state %d",
                      d->st[i].scan_span, d->st[i].scan_cls, d->st[i].scan_next);
        sb_puts(c, "\n");
    }
    free(dist); free(from); free(via); free(queue); free(path);
}

/* M2.7 put `$`-bearing patterns on this engine; M2.12 gave them back the
 * scan-avoidance M2.7 had traded away. Both live in ONE emitter on purpose:
 * M2.7 forked a second copy, and the fork is exactly how the prefilter and
 * skip loops went missing from the `$` path for a whole milestone.
 *
 * EOL handling: both machines switch to a state's EOL variant exactly at EOL
 * positions (end of subject, or before a final newline), guarded by
 * `pos + 1 >= n` — false for every byte but the last two, so the scan stays a
 * tight table walk.
 *
 * Scan avoidance under EOL (M2.12): a prefilter or self-loop skip advances
 * `pos` WITHOUT consulting accept flags, which is unsound when a state can
 * accept at an EOL position. The fix is to bound every skip at `n - 1` rather
 * than `n` and let the stepped loop handle the last two positions. That also
 * keeps the EOL-variant lookup correct for free: a skip can only run when
 * `pos + 1 < n`, and in that case `est == st` by construction, so the state
 * used for the transition is never stale. The forward prefilter additionally
 * must NOT keep its `return 0` early-out, since the start state's EOL variant
 * may still accept at n-1 or n. */
/* =========================================================================
 * [ENG-FORM] THE REPRESENTATION OBJECTS AND THE ONE SCAN LOOP
 *
 * docs/design/emitter_form.md is the note; D82 the ruling. What used to be a
 * 459-line function carrying ~14 loose form booleans — every one of them a
 * forward/reverse PAIR — is six candidate lists, one loop skeleton and one
 * table emitter, each called twice.
 *
 * READ `DfaForm` FIRST: it is one machine's whole form, and every emitter
 * below takes nothing else. The two `DfaForm`s an artifact builds differ in
 * their DIRECTION object, their machine, and whichever candidates that
 * machine's own dimensions selected.
 * ========================================================================= */

typedef struct DfaDir DfaDir;

/* AXIS B — THE PREFILTER, forward only. Five objects and not three: the D11
 * `-bounded` half of `<PREFIX>_DFA_PREFILTER`'s value is a DIFFERENT EMITTED
 * LOOP (the skip stops at n-1 and loses its `return 0` early-out), so it is a
 * different form, and making it one is what turns the stamp into `c.name`. */
typedef struct DfaPf {
    DfaCand c;
    /* [OPT-K] `bool table` became a METHOD when the offset-k forms landed, and
     * that is the object owning what it emits rather than the assembly asking
     * a boolean. The byte-class forms emit `can_begin_match` and nothing else,
     * exactly as before; the offset-set forms emit that table only when offset
     * 0's set is genuinely a bitmap, plus one table per multi-byte VERIFY
     * offset. A boolean cannot express "which of my offsets need a table",
     * and a second boolean beside it would be the parallel mechanism the
     * house rule forbids. NULL == this form emits no table. */
    void  (*emit_tables)(StrBuf *c, const DfaForm *f);
    /* [OPT-K] LAYER 2, the accessor block, at FILE SCOPE beside the state
     * token's — the offset-k skip is a loop over the subject and belongs in a
     * function, not inlined three levels deep in the scan. NULL == no block.
     * It is emitted from the same place `repr->emit_token` is, so the VM
     * hybrid's inlined prefilter gets it by construction. */
    void  (*emit_block)(StrBuf *c, const DfaForm *f);
    void  (*emit)(StrBuf *c, const DfaForm *f); /* NULL == emits nothing */
} DfaPf;

/* AXIS C — VIEW HANDLING. `emit_view_select`'s three branches, plus the
 * "not called at all" case that used to be an `if (viewsel)` at each of the
 * two call sites. */
typedef struct DfaView {
    DfaCand c;
    void  (*emit)(StrBuf *c, const DfaForm *f); /* NULL == emits nothing */
} DfaView;

/* AXIS D — THE START SEED (mechanism 4). The object owns whether the
 * initializer reads a context byte; the DIRECTION owns which byte, which
 * guard, and where the range check goes relative to it. */
typedef struct DfaSeed {
    DfaCand c;
    bool    table;                              /* the <M>_seed_state table */
    void  (*emit_init)(StrBuf *c, const DfaForm *f);
} DfaSeed;

/* AXIS E — WHERE THE ACCEPT IS RECORDED, which is one axis with three forms
 * and not two booleans. `by_class` records inside the step arm (§3.6.2's
 * composition); `scalar_viewed` records AFTER the view selector, because the
 * position a skip landed on is not the position whose accept was evaluated
 * (D11); `scalar_plain` records at the top of the loop, which is measurably
 * the right order when nothing can move under it (D11's note: hoisting the
 * prefilter above it costs 43% on `[01]*1[01]{8}`). Exactly one of the three
 * `emit_*` slots is non-NULL per object, which is why the skeleton calls them
 * through null checks instead of branching on a form. */
typedef struct DfaAcc {
    DfaCand c;
    bool    wide_table;                         /* the by-class accept table */
    void  (*emit_top)(StrBuf *c, const DfaForm *f);
    void  (*emit_after_view)(StrBuf *c, const DfaForm *f);
    void  (*emit_tail)(StrBuf *c, const DfaForm *f);
} DfaAcc;

/* AXIS F — THE SCAN DIRECTION, the axis that collapses the duplication. It is
 * a representation axis in the same sense as the others: a direction is how a
 * scan spells its position, its bound, the answer it records and the byte it
 * reads, and every one of those has exactly two emitted forms. */
struct DfaDir {
    DfaCand     c;
    const char *title;        /* "Forward" / "Reverse", for comments */
    const char *label;        /* "FORWARD" / "REVERSE", for headings */
    const char *statev;       /* the emitted state variable */
    const char *viewv;        /* the emitted view-state variable */
    const char *posv;         /* the emitted position variable */
    const char *recv;         /* the emitted answer variable */
    const char *ind;          /* indent of the state declaration */
    const char *bind;         /* indent of the loop body */
    bool        reverse;      /* for emit_state_legend */
    /* [ENG-ABS] Does a start-candidate PREFILTER own this machine's start
     * state, so that the in-loop stay-skips must leave it alone? True on the
     * SEARCH scan alone. It used to be spelled `dir->reverse ? -1 : d->s0` at
     * the one call site, which read as "the reverse machine has no prefilter"
     * and became wrong the moment a THIRD machine had none either: the
     * anchored MATCH-HERE scan is forward and prefilter-free, and excluding
     * its `s0` would deny it a skip for a reason that does not apply to it. */
    bool        prefilter_owns_start;
    const char *tbl_hdr;      /* the table section's block comment */
    const char *acc_meaning;  /* what a 1 in the accept table means */
    const char *range_guard;  /* emitted beside the initializer, or NULL */
    const char *seed_cond;    /* "a context byte exists" */
    const char *seed_byte;    /* that byte */
    const char *at_bound;     /* "there is no byte left to consume" */
    const char *peek;         /* the byte to consume, WITHOUT consuming it */
    const char *consume;      /* the byte to consume, consuming it */
    const char *advance;      /* the statement that consumes it */
    void      (*emit_skip)(StrBuf *c, const DfaForm *f, int K, const char *kw);
    void      (*emit_bound_accept)(StrBuf *c, const DfaForm *f);
    /* [OPT-5] THE SCAN EDGE'S TWO DIRECTION STRINGS, and it needs only two
     * because everything else it spells is already here. `scan_more` is the
     * loop's "a byte is left" test — `at_bound`'s negation, written out
     * rather than derived, because a direction states its own bound in this
     * object and `!(...)` around a string is how the two would drift.
     * `scan_back` is the position one byte BEHIND the cursor IN WALK ORDER,
     * which is `- 1` going forward and `+ 1` going backward: it is where the
     * run's last CHAIN-state position sits once the bound has been reached,
     * and getting its sign wrong is a wrong span rather than a compile
     * error. There is no `emit_scan` method beside them — unlike `emit_skip`,
     * the three directions' scan loops differ in nothing else, so the
     * emitter is written once and called from all three. */
    const char *scan_more;
    const char *scan_back;
};

/* ONE MACHINE'S FORM. Everything an emitter below is allowed to read. */
struct DfaForm {
    /* [OPT-K] the Ctx, for `ctx_fail` alone. Two arms of the offset-k skip's
     * emitter are UNREACHABLE by construction (an empty verify chain; a
     * non-singleton scan offset), and this file's standing preference is a
     * loud internal error over a silent fallback that would emit a correct
     * matcher with the optimization quietly switched off. */
    Ctx           *cx;
    const Dfa     *d;
    const char    *p;              /* the artifact prefix */
    const DfaDir  *dir;
    const DfaRepr *repr;
    const DfaPf   *pf;
    const DfaView *view;
    const DfaSeed *seed;
    const DfaAcc  *acc;
    bool           views;          /* the D11 bound: a skip may pass a
                                    * position whose accept was not evaluated */
    bool           viewsel;        /* the position-view indirection exists */
    const char    *src;            /* the state the accept and the step read:
                                    * `statev`, or `viewv` under `viewsel` */
    int            nskip, skip[4];
    /* [OPT-5] The states carrying a SCAN EDGE, read straight off
     * `DState.scan_span` — src/opt/scanedge.c chose them and this is a walk
     * for them, never a second selection. The array is sized by the same
     * `PCREC_MAX_SCAN_EDGES` the pass spends, so it cannot truncate. */
    int            nscan, scan[PCREC_MAX_SCAN_EDGES];
    /* [CC-DIFF] (b) THE TWO UNIFORM-TABLE FOLDS, derived ONCE in
     * `dfa_form_derive` and read by three places that must not disagree: the
     * accessor's parameter list, the table's emission (or its omission), and
     * every call site's argument list. A second uniformity scan at any of
     * them would be a second derivation of one fact, and a fold that
     * disagreed with its accessor is a compile error at best and a wrong
     * answer at worst. `<PREFIX>_DFA_UNIFORM_FOLDS` is a fourth reader, and
     * it calls the SAME `fold_tr`/`fold_acc` on the same `(d, repr)` at the
     * stamp path, exactly as `dfa_table_name` re-asks `dfa_repr_of` there. */
    DfaFold        tr_fold, acc_fold;
    CandSet        cand;
    /* [OPT-K] BY POINTER into the caller's `UnanchStart`, which outlives every
     * use: the selection carries 24 byte-sets and copying it into a stack
     * struct twice per artifact would put 13 KB on the emitter's frame for a
     * value nothing mutates. */
    const PrefixKSets *ofsk;
};

/* THE SELECTION WALK, written ONCE for all six axes. Every object struct
 * begins with a `DfaCand`, so the address of the i'th entry of any of the
 * lists is the address of a `DfaCand` — no punning, just the first member.
 *
 * Returning NULL is UNREACHABLE and deliberately not defended against: every
 * list's last entry's `applies` returns true unconditionally, which is the
 * property §9.3 of the note names as the failure mode a total fallback
 * removes. A missing fallback would crash here rather than emit a machine
 * with a hole in it. */
static const void *dfa_select(const void *list, size_t n, size_t sz,
                              const DfaSel *s, unsigned flags)
{
    const char *base = (const char *)list;
    for (size_t i = 0; i < n; i++) {
        const DfaCand *cand = (const DfaCand *)(const void *)(base + i * sz);
        if (cand->deny & flags) continue;
        if (cand->applies(s)) return (const void *)(base + i * sz);
    }
    return NULL;
}
#define DFA_SELECT(T, list, sel, flags)                                       \
    ((const T *)dfa_select((list), sizeof(list) / sizeof((list)[0]),          \
                           sizeof((list)[0]), (sel), (flags)))

static bool cand_always(const DfaSel *s) { (void)s; return true; }

/* ---- AXIS A: the table representations ---------------------------------- */

static bool repr_premul_applies(const DfaSel *s) { return dfa_premul(s->cx, s->d); }
static int  cell_premul(int st, const Dfa *d) { return st * d->ncls; }
static int  cell_indexed(int st, const Dfa *d) { (void)d; return st; }

/* LAYER 2 — THE OPAQUE STATE TOKEN. One block per machine per form, emitted
 * at file scope immediately above the search function, so the VM hybrid's
 * inlined `static <prefix>_prefilter` gets it BY CONSTRUCTION: that body is
 * this same emitter call (`pcrec_emit_dfa_engine`), not a second copy.
 *
 * AN ACCESSOR TAKES THE TABLE IT READS AS A PARAMETER. The tables stay
 * function-local `static const` arrays, where they have always been; the
 * token abstracts the STATE REPRESENTATION and nothing else, and gcc folds a
 * block-scope array's address through an inline call. That folding is the
 * whole design (D82 bound 1) and it is MEASURED, not assumed: the objdump of
 * `<prefix>_search` after this change is instruction-for-instruction the
 * sequence the hand-written loop produced.
 *
 * ONLY THE ACCESSORS THIS MACHINE USES ARE EMITTED — `accepts_class` under
 * axis E's `by_class`, `row`/`view_live`/`view_take` under a view — so no
 * artifact carries a dead one. */
/* [CC-DIFF] (b) THE TABLE ARGUMENT A FOLDED ACCESSOR NO LONGER TAKES: the
 * empty string when the fold removed the parameter, `"<p>_<m>_<tag>, "` when
 * it did not. Every call site of a foldable accessor spells its table
 * argument THROUGH THIS, so the accessor's parameter list and its call sites
 * are two readings of ONE `DfaFold` and cannot drift apart into a program
 * that does not compile.
 *
 * ONLY THE TABLE POINTER LEAVES. The state and class arguments stay in the
 * signature and are still passed, still evaluated, and then ignored by name
 * — because a class argument is routinely `<m>_byte_class[subject[pos++]]`,
 * and dropping THAT parameter would drop the increment with it. A folded
 * accessor is a function that ignores what it is given, never a call site
 * that stops giving it. */
static const char *fold_arg(char *buf, size_t n, const DfaForm *f,
                            const DfaFold *fold, const char *tag)
{
    if (fold->folded) { buf[0] = '\0'; return buf; }
    snprintf(buf, n, "%s_%s_%s, ", f->p, f->dir->c.name, tag);
    return buf;
}

/* The `_step` accessor, in the one spelling both representations share: the
 * folded body ignores everything and returns the constant, and the table
 * parameter is gone from the list. `%s` is the representation's own cell type
 * and index expression, which is what makes this ONE function rather than a
 * copy in each `token_*`. */
static void token_step(StrBuf *c, const DfaForm *f, const char *cell_type,
                       const char *index_expr)
{
    const char *p = f->p, *m = f->dir->c.name;
    if (f->tr_fold.folded) {
        sb_printf(c,
            "/* [CC-DIFF] EVERY CELL of the %s transition table holds %d, so the\n"
            " * table is not emitted and a step IS that constant. The state and the\n"
            " * class are still passed -- the class expression can consume a byte --\n"
            " * and then ignored. */\n"
            "static inline %s_%s_state %s_%s_step(%s_%s_state s, unsigned cl)\n"
            "{ (void)s; (void)cl; return %d; }\n",
            m, f->tr_fold.value, p, m, p, m, p, m, f->tr_fold.value);
        return;
    }
    sb_printf(c, "static inline %s_%s_state %s_%s_step(const %s *transitions, %s_%s_state s, unsigned cl)\n"
                 "{ return %s; }\n", p, m, p, m, cell_type, p, m, index_expr);
}

/* [OPT-EDGE] STEP 1 — THE STOP PREDICATE, the loop's ONE per-iteration state
 * test, and the third accessor that is emitted only where it is used.
 *
 * The generic path used to pay one compare PER SCAN EDGE (`if (state == HEAD
 * && ...)`, once per edge, every iteration) on top of the one sentinel test
 * the loop already had. This predicate folds the two together: `scanedge.c`
 * renumbered the edge heads to the TOP rows of the machine, and the dead
 * value sits above them under BOTH representations — 65535 above every
 * premultiplied cell by `PREMUL_MAX_ENTRIES`, and -1 above every indexed row
 * once it is READ AS UNSIGNED. So "dead, or a head" is `(unsigned)s >= FLOOR`
 * and nothing else, and which of the two it is costs nothing on the path
 * where it is neither.
 *
 * IT IS SPELLED ONCE FOR BOTH REPRESENTATIONS, from the repr's own
 * `cell_of`, because the floor is a question about the machine's row
 * numbering and not about how a row is spelled. `is_dead` is untouched — same
 * name, same body, same exact meaning — so the split off the generic path is
 * an existing predicate and not a second one to keep in step. A machine with
 * no scan edge emits neither this accessor nor any of the loop scaffolding
 * that reads it, and is byte-identical to the pre-[OPT-EDGE] artifact. */
static void token_stop(StrBuf *c, const DfaForm *f)
{
    if (f->nscan <= 0) return;
    const char *p = f->p, *m = f->dir->c.name;
    unsigned floor = (unsigned)f->repr->cell_of(f->d->n - f->nscan, f->d);
    /* THE COMMENT IS TWO LINES ON PURPOSE. It is emitted once per machine,
     * i.e. up to three times per artifact, and this file has already had to
     * cut one per-machine comment for exactly that reason (`emit_scan_edge`'s,
     * seven lines to four, ~900 emitted bytes on `[a-z]*`). The two facts a
     * reader cannot get anywhere else are what is left. */
    /* THE WHOLE-MACHINE CASE IS THE FLOOR AT ZERO, and it is a FOLD rather
     * than a special case — [CC-DIFF]'s uniform-table fold one accessor over,
     * spelled the same way. `[a-z]*`'s forward machine is ONE state and that
     * state is the head, so every value the predicate can see is in the
     * reserved range and the answer is the constant. Emitting the compare
     * anyway is `(unsigned)s >= 0u`, which is `-Werror=type-limits` in
     * generated C the harness and every caller build with `-Wall -Wextra
     * -Werror`; the loop's own shape does not change, because gcc folds the
     * inline call and drops the unreachable arm. */
    if (floor == 0) {
        sb_printf(c,
            "/* [OPT-EDGE] EVERY state of this machine is a scan-edge head, so the\n"
            " * loop's generic path is unreachable and the test IS that constant. */\n"
            "static inline int %s_%s_is_stop(%s_%s_state s) { (void)s; return 1; }\n",
            p, m, p, m);
        return;
    }
    char heads[48];
    if (f->nscan == 1) snprintf(heads, sizeof heads, "the scan-edge head");
    else snprintf(heads, sizeof heads, "one of the %d scan-edge heads", f->nscan);
    sb_printf(c,
        "/* [OPT-EDGE] Dead, or %s -- which %s the machine's\n"
        " * TOP row%s, so ONE unsigned compare answers both. */\n"
        "static inline int %s_%s_is_stop(%s_%s_state s) { return (unsigned)s >= %uu; }\n",
        heads, f->nscan == 1 ? "is" : "are", f->nscan == 1 ? "" : "s",
        p, m, p, m, floor);
}

/* The two accept accessors, same rule. `accepts_class` is emitted only under
 * a wide table, which is the same condition `accw_fold` is derived under. */
static void token_accepts(StrBuf *c, const DfaForm *f, const char *cls_index)
{
    const char *p = f->p, *m = f->dir->c.name;
    if (f->acc_fold.folded)
        sb_printf(c,
            "/* [CC-DIFF] EVERY STATE of the %s machine has accept bit %d, so the\n"
            " * table is not emitted and the probe IS that constant. */\n"
            "static inline int %s_%s_accepts(%s_%s_state s)\n"
            "{ (void)s; return %d; }\n",
            m, f->acc_fold.value, p, m, p, m, f->acc_fold.value);
    else
        sb_printf(c, "static inline int %s_%s_accepts(const unsigned char *accepting, %s_%s_state s)\n"
                     "{ return accepting[s]; }\n", p, m, p, m);
    if (!f->acc->wide_table) return;
    sb_printf(c, "static inline int %s_%s_accepts_class(const unsigned char *accepting, %s_%s_state s, unsigned cl)\n"
                 "{ return %s; }\n", p, m, p, m, cls_index);
}

static void token_premul(StrBuf *c, const DfaForm *f)
{
    const char *p = f->p, *m = f->dir->c.name;
    int nc = f->d->ncls;
    sb_printf(c,
        "/* ---- THE %s SCAN'S STATE, AS AN OPAQUE TOKEN --------------------\n"
        " * The scan carries its state in a `%s_%s_state`. Everything that\n"
        " * depends on how a state is REPRESENTED is in this block: the loop\n"
        " * only steps the token, asks whether it is dead, probes its accept\n"
        " * bit and -- at most twice per search -- asks which table ROW it\n"
        " * names.\n"
        " *\n"
        " * THIS IS THE PRE-MULTIPLIED FORM: the token is the state's row\n"
        " * number times %d, so a step is one add and one load, and %d is the\n"
        " * reserved value meaning \"dead, stop\".\n"
        " */\n", f->dir->label, p, m, nc, PREMUL_DEAD);
    sb_printf(c, "typedef unsigned %s_%s_state;\n", p, m);
    token_step(c, f, "unsigned short", "transitions[s + cl]");
    sb_printf(c, "static inline int %s_%s_is_dead(%s_%s_state s) { return s == %d; }\n",
              p, m, p, m, PREMUL_DEAD);
    token_stop(c, f);
    token_accepts(c, f, "accepting[s + cl]");
    if (f->viewsel) {
        /* THE ONE UN-MULTIPLY, and the reason it is a function rather than a
         * hoisted local at the call site: under this form it is a DIVISION.
         * Its callers spell it inside the second operand of a `&&` whose
         * first operand is `__builtin_expect(pos + 1 >= n, 0)`, so it runs at
         * most twice per search and never per byte. A tidier
         * `unsigned row = <M>_row(s);` above the `if` changes no answer,
         * passes every identity gate, and puts a divide on the hot path. */
        sb_printf(c, "static inline unsigned %s_%s_row(%s_%s_state s) { return s / %d; }\n",
                  p, m, p, m, nc);
        sb_printf(c, "static inline int %s_%s_view_live(const unsigned short *view, unsigned row)\n"
                     "{ return view[row] != %d; }\n", p, m, PREMUL_DEAD);
        sb_printf(c, "static inline %s_%s_state %s_%s_view_take(const unsigned short *view, unsigned row)\n"
                     "{ return view[row]; }\n", p, m, p, m);
    }
    sb_puts(c, "\n");
}

static void token_indexed(StrBuf *c, const DfaForm *f)
{
    const char *p = f->p, *m = f->dir->c.name;
    int nc = f->d->ncls;
    sb_printf(c,
        "/* ---- THE %s SCAN'S STATE, AS AN OPAQUE TOKEN --------------------\n"
        " * The scan carries its state in a `%s_%s_state`. Everything that\n"
        " * depends on how a state is REPRESENTED is in this block: the loop\n"
        " * only steps the token, asks whether it is dead, probes its accept\n"
        " * bit and -- at most twice per search -- asks which table ROW it\n"
        " * names.\n"
        " *\n"
        " * THIS IS THE INDEXED FORM: the token IS the row number, a step\n"
        " * scales it by the %d columns, and a negative value means \"dead,\n"
        " * stop\".\n"
        " */\n", f->dir->label, p, m, nc);
    sb_printf(c, "typedef int %s_%s_state;\n", p, m);
    /* The indexed form scales the token by the column count, so its two index
     * expressions carry `ncls` and are built here rather than written as
     * literals in the shared emitter above. */
    char tr_ix[64], acc_ix[64];
    snprintf(tr_ix, sizeof tr_ix, "transitions[s * %d + cl]", nc);
    snprintf(acc_ix, sizeof acc_ix, "accepting[s * %d + cl]", nc);
    token_step(c, f, "short", tr_ix);
    sb_printf(c, "static inline int %s_%s_is_dead(%s_%s_state s) { return s < 0; }\n",
              p, m, p, m);
    token_stop(c, f);
    token_accepts(c, f, acc_ix);
    if (f->viewsel) {
        sb_printf(c, "static inline unsigned %s_%s_row(%s_%s_state s) { return (unsigned)s; }\n",
                  p, m, p, m);
        sb_printf(c, "static inline int %s_%s_view_live(const short *view, unsigned row)\n"
                     "{ return view[row] >= 0; }\n", p, m);
        sb_printf(c, "static inline %s_%s_state %s_%s_view_take(const short *view, unsigned row)\n"
                     "{ return view[row]; }\n", p, m, p, m);
    }
    sb_puts(c, "\n");
}

static void tr_comment_premul(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "    /* %s transitions, PRE-MULTIPLIED: indexed [state + class],\n"
                 "     * and each cell already holds next_state * %d, so a step is one\n"
                 "     * add and one load. %d means the walk cannot continue and stops.\n"
                 "     * %d rows of %d. The state numbers in the legend below are ROW\n"
                 "     * numbers; the values %s carries are those times %d.\n"
                 "     *\n",
              f->dir->title, f->d->ncls, PREMUL_DEAD, f->d->n, f->d->ncls,
              f->dir->statev, f->d->ncls);
}

static void tr_comment_indexed(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "    /* %s transitions, indexed [state * %d + class]; -1 means the\n"
                 "     * walk cannot continue and stops. %d rows of %d.\n"
                 "     *\n",
              f->dir->title, f->d->ncls, f->d->n, f->d->ncls);
}

static void acc_comment_premul(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "    /* 1 where %s, indexed by the PRE-MULTIPLIED\n"
                 "     * %s state, so the scan's chain never un-multiplies. Each row\n"
                 "     * repeats one bit; only the cells at a multiple of the class\n"
                 "     * count are ever read. */\n",
              f->dir->acc_meaning, f->dir->c.name);
}

static void acc_comment_indexed(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "    /* 1 where %s, indexed by %s state. */\n",
              f->dir->acc_meaning, f->dir->c.name);
}

/* THE CANDIDATE LIST, in PREFERENCE order. A new representation — the u32
 * form above the u16 bound, a two-byte alphabet — is a new ENTRY here plus
 * its `emit_token` body, and nothing in `emit_scan_loop` or the assembly
 * moves. Neither is built: D77, wait for the measurement that asks. */
static const DfaRepr dfa_reprs[] = {
    { { "premultiplied", PCREC_NO_PREMUL_TABLE, repr_premul_applies },
      "unsigned short", true, PREMUL_DEAD, cell_premul,
      token_premul, tr_comment_premul, acc_comment_premul },
    { { "indexed", 0, cand_always },
      "short", false, -1, cell_indexed,
      token_indexed, tr_comment_indexed, acc_comment_indexed },
};

static const DfaRepr *dfa_repr_of(Ctx *cx, const Dfa *d)
{
    DfaSel s = { cx, d, NULL, true, -1 };
    return DFA_SELECT(DfaRepr, dfa_reprs, &s, cx->opt->flags);
}

/* ---- AXIS C: the view selector ------------------------------------------ */

static void view_decl(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "%s%s_%s_state %s = %s;\n", f->dir->bind, f->p, f->dir->c.name,
              f->dir->viewv, f->dir->statev);
}

/* `%s_%s_row(%s)` spelled once, since every view site needs it and none may
 * hoist it (see `token_premul`'s note). */
#define VROW(f) (f)->p, (f)->dir->c.name, (f)->dir->statev
#define VTBL(f) (f)->p, (f)->dir->c.name

static void view_emit_eol_only(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind, *pos = f->dir->posv;
    view_decl(c, f);
    sb_printf(c, "%sif (__builtin_expect(%s + 1 >= subject_length, 0) &&\n"
                 "%s    %s_%s_view_live(%s_%s_eol_view, %s_%s_row(%s)) &&\n"
                 "%s    (%s == subject_length ||\n"
                 "%s     (%s + 1 == subject_length && subject[%s] == '\\n')))\n"
                 "%s    %s = %s_%s_view_take(%s_%s_eol_view, %s_%s_row(%s));\n",
              ind, pos,
              ind, VTBL(f), VTBL(f), VROW(f),
              ind, pos,
              ind, pos, pos,
              ind, f->dir->viewv, VTBL(f), VTBL(f), VROW(f));
}

static void view_emit_end_only(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind, *pos = f->dir->posv;
    view_decl(c, f);
    /* `\z` with no `$`/`\Z` anywhere: only `pos == n` selects anything. */
    sb_printf(c, "%sif (__builtin_expect(%s == subject_length, 0) &&\n"
                 "%s    %s_%s_view_live(%s_%s_end_view, %s_%s_row(%s)))\n"
                 "%s    %s = %s_%s_view_take(%s_%s_end_view, %s_%s_row(%s));\n",
              ind, pos,
              ind, VTBL(f), VTBL(f), VROW(f),
              ind, f->dir->viewv, VTBL(f), VTBL(f), VROW(f));
}

static void view_emit_end_and_eol(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind, *pos = f->dir->posv;
    view_decl(c, f);
    sb_printf(c, "%sif (__builtin_expect(%s + 1 >= subject_length, 0)) {\n", ind, pos);
    sb_printf(c, "%s    if (%s == subject_length) {\n", ind, pos);
    sb_printf(c, "%s        if (%s_%s_view_live(%s_%s_end_view, %s_%s_row(%s)))\n"
                 "%s            %s = %s_%s_view_take(%s_%s_end_view, %s_%s_row(%s));\n"
                 "%s        else if (%s_%s_view_live(%s_%s_eol_view, %s_%s_row(%s)))\n"
                 "%s            %s = %s_%s_view_take(%s_%s_eol_view, %s_%s_row(%s));\n",
              ind, VTBL(f), VTBL(f), VROW(f),
              ind, f->dir->viewv, VTBL(f), VTBL(f), VROW(f),
              ind, VTBL(f), VTBL(f), VROW(f),
              ind, f->dir->viewv, VTBL(f), VTBL(f), VROW(f));
    sb_printf(c, "%s    } else if (subject[%s] == '\\n' &&\n"
                 "%s               %s_%s_view_live(%s_%s_eol_view, %s_%s_row(%s))) {\n",
              ind, pos,
              ind, VTBL(f), VTBL(f), VROW(f));
    sb_printf(c, "%s        %s = %s_%s_view_take(%s_%s_eol_view, %s_%s_row(%s));\n",
              ind, f->dir->viewv, VTBL(f), VTBL(f), VROW(f));
    sb_printf(c, "%s    }\n%s}\n", ind, ind);
}

/* THE THREE-WAY POSITION RULE, once:
 *
 *   pos == n                      -> the END view   (`\z`, `$`, `\Z` all pass)
 *   pos + 1 == n && s[pos] == \n  -> the EOL view   (`$`/`\Z` only)
 *   otherwise                     -> the state itself
 *
 * Which of the four objects a machine takes is which of the two view tables
 * it actually has; `none` is the artifact with neither, where the scan reads
 * the state directly and `f->src` is the state variable. */
static bool view_end_and_eol_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return u->endv && u->eol; }
static bool view_end_only_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return u->endv && !u->eol; }
static bool view_eol_only_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return u->eol && !u->endv; }

static const DfaView dfa_views[] = {
    { { "end+eol", 0, view_end_and_eol_applies }, view_emit_end_and_eol },
    { { "end",     0, view_end_only_applies    }, view_emit_end_only    },
    { { "eol",     0, view_eol_only_applies    }, view_emit_eol_only    },
    { { "none",    0, cand_always              }, NULL                  },
};

/* ---- AXIS D: the start seed --------------------------------------------- */

static bool seed_applies(const DfaSel *s) { return dfa_needs_seed(s->d); }

static void seed_emit_seeded(StrBuf *c, const DfaForm *f)
{
    /* MECHANISM 4's start initialization (§3.8.2/§3.8.3). ONCE PER SEARCH,
     * off the loop entirely — the emitted hot path is unchanged.
     *
     * The context byte is IN THE SUBJECT AND OUTSIDE THE WINDOW the walk
     * consumes, which is the whole point: a leading `\b` at `startpos` is a
     * question about the byte before it, and a trailing one at `end` is a
     * question about `s[end]` — a byte one to the RIGHT of where the reverse
     * walk begins and never consumed by it. A constant start state encodes
     * exactly one answer, "the context here is the end of the subject",
     * which is the assumption a SLICE makes and not the one this API's
     * contract makes. MEASURED against libpcre2 10.46: 5 of §3.8.1's 10
     * cells differ, in both directions, so no conservative shortcut exists.
     *
     * THE RANGE GUARD MOVES ABOVE THE INITIALIZER on the direction that has
     * one, and it has to: the constant form could not read the subject, so
     * `startpos > n` was checked after it; here the initializer dereferences
     * `s[startpos - 1]`, and on an out-of-range `startpos` that is an
     * out-of-bounds read in EMITTED code — K27's class. With the guard
     * first, `startpos <= n`, and `startpos > 0` then implies `n > 0`, hence
     * `s != NULL` under match_api.md §3.1's legal empty subject. */
    if (f->dir->range_guard) sb_puts(c, f->dir->range_guard);
    sb_printf(c, "%s%s_%s_state %s = %s ? %s_%s_seed_state[%s_%s_byte_class[%s]]"
                 " : %d;\n",
              f->dir->ind, f->p, f->dir->c.name, f->dir->statev,
              f->dir->seed_cond, f->p, f->dir->c.name, f->p, f->dir->c.name,
              f->dir->seed_byte, f->repr->cell_of(f->d->s0, f->d));
}

static void seed_emit_constant(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "%s%s_%s_state %s = %d;\n", f->dir->ind, f->p, f->dir->c.name,
              f->dir->statev, f->repr->cell_of(f->d->s0, f->d));
    if (f->dir->range_guard) sb_puts(c, f->dir->range_guard);
}

static const DfaSeed dfa_seeds[] = {
    { { "seeded",   0, seed_applies }, true,  seed_emit_seeded   },
    { { "constant", 0, cand_always  }, false, seed_emit_constant },
};

/* ---- AXIS E: where the accept is recorded ------------------------------- */

static bool acc_by_class_applies(const DfaSel *s) { return dfa_has_clsacc(s->d); }
static bool acc_viewed_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return u->views; }

static void acc_emit_probe(StrBuf *c, const DfaForm *f)
{
    char ab[PCREC_MAX_EMIT_NAME_LEN];
    sb_printf(c, "%sif (%s_%s_accepts(%s%s)) %s = %s;\n",
              f->dir->bind, f->p, f->dir->c.name,
              fold_arg(ab, sizeof ab, f, &f->acc_fold, "is_accepting"),
              f->src, f->dir->recv, f->dir->posv);
}

static void acc_emit_tail_scalar(StrBuf *c, const DfaForm *f)
{
    char tb[PCREC_MAX_EMIT_NAME_LEN];
    sb_printf(c, "%sif (%s) break;\n", f->dir->bind, f->dir->at_bound);
    sb_printf(c, "%s%s = %s_%s_step(%s%s, %s_%s_byte_class[%s]);\n",
              f->dir->bind, f->dir->statev, f->p, f->dir->c.name,
              fold_arg(tb, sizeof tb, f, &f->tr_fold, "next_state"),
              f->src, f->p, f->dir->c.name,
              f->dir->consume);
}

static void acc_emit_tail_by_class(StrBuf *c, const DfaForm *f)
{
    /* §3.6.2's COMPOSITION RULE. The accept bit is class-indexed at every
     * position that HAS a next byte and SCALAR at the boundary, where there
     * is none in that direction: out of the window counts as non-word, which
     * is a property of the POSITION, and the base accept already is that bit.
     * Indexing the wide table at the boundary would be asking what the accept
     * is when the next byte is "whatever byte happens to sit in that
     * equivalence class", which is meaningless there.
     *
     * The guard is also what makes the byte read below unreachable at the
     * boundary. The class is computed ONCE into `<M>_class` and shared with
     * the transition — the byte is read once, and the structural check for
     * this rule has a single named thing to look at rather than an expression
     * to parse.
     *
     * THE BOUNDARY ARM IS ATTACHED TO THE BREAK, NOT PEELED BELOW THE LOOP,
     * and that placement is the whole of R30 N9. This loop has TWO exits —
     * this one and the dead-state one — and code placed after the loop would
     * run on both. On the dead-state exit the walk did not reach the
     * boundary, so an epilogue would record an answer at a position the walk
     * never reached (a WRONG ANSWER, worse than a lost match) and would index
     * the accept table with a dead token (an out-of-bounds read in emitted
     * code, K27's class). This arm is entered only when the walk IS at the
     * boundary and the token is live, so both are unreachable by
     * construction. */
    const char *ind = f->dir->bind, *m = f->dir->c.name, *p = f->p;
    char tb[PCREC_MAX_EMIT_NAME_LEN];
    sb_printf(c, "%sif (%s) {\n", ind, f->dir->at_bound);
    f->dir->emit_bound_accept(c, f);
    sb_printf(c, "%s    break;\n%s}\n", ind, ind);
    sb_printf(c, "%s{\n", ind);
    sb_printf(c, "%s    unsigned %s_class = %s_%s_byte_class[%s];\n",
              ind, m, p, m, f->dir->peek);
    sb_printf(c, "%s    if (%s_%s_accepts_class(%s_%s_is_accepting_by_class, %s, %s_class))"
                 " %s = %s;\n",
              ind, p, m, p, m, f->src, m, f->dir->recv, f->dir->posv);
    sb_printf(c, "%s    %s = %s_%s_step(%s%s, %s_class);\n",
              ind, f->dir->statev, p, m,
              fold_arg(tb, sizeof tb, f, &f->tr_fold, "next_state"), f->src, m);
    sb_printf(c, "%s    %s;\n", ind, f->dir->advance);
    sb_printf(c, "%s}\n", ind);
}

static const DfaAcc dfa_accs[] = {
    { { "by-class", 0, acc_by_class_applies }, true,
      NULL, NULL, acc_emit_tail_by_class },
    { { "scalar-viewed", 0, acc_viewed_applies }, false,
      NULL, acc_emit_probe, acc_emit_tail_scalar },
    { { "scalar-plain", 0, cand_always }, false,
      acc_emit_probe, NULL, acc_emit_tail_scalar },
};

/* ---- AXIS B: the prefilter ---------------------------------------------- */

static bool pf_memchr_bounded_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return s->forward && u->kind == DFA_PF_MEMCHR && u->views; }
static bool pf_memchr_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return s->forward && u->kind == DFA_PF_MEMCHR; }
static bool pf_bcls_bounded_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return s->forward && u->kind == DFA_PF_BYTE_CLASS && u->views; }
static bool pf_bcls_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return s->forward && u->kind == DFA_PF_BYTE_CLASS; }

/* THE ENTRY CONDITION, shared by all four emitted forms: still parked in the
 * start state with nothing found.
 *
 * The `last == (size_t)-1` half is NOT load-bearing and this comment must not
 * present it as though it were. D3's priority pruning cuts the unanchored
 * start self-loop out of every accepting closure, so an accepting state's
 * successors can never be the start state and `st == s0` already implies
 * `last == -1`. Two independent critics attacked the gate and neither could
 * build a witness: deleting it produced 0 divergences over 8.0M
 * oracle-checked comparisons. Keep it — it is free belt-and-braces — but do
 * not cite it as a premise. */
static void pf_open(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "%sif (%s == %d && %s == (size_t)-1) {\n",
              f->dir->bind, f->dir->statev, f->repr->cell_of(f->d->s0, f->d),
              f->dir->recv);
}

static void pf_comment_memchr(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "%s// Prefilter: nothing found yet and still at the start, so\n"
                 "%s// skip straight to the next byte that could begin a match.\n"
                 "%s// Only ", f->dir->bind, f->dir->bind, f->dir->bind);
    legend_byte(c, f->cand.byte);
    sb_printf(c, " (%d) can, so one memchr() replaces the steps.\n", f->cand.byte);
}

static void pf_comment_bcls(StrBuf *c, const DfaForm *f)
{
    sb_printf(c, "%s// Prefilter: nothing found yet and still at the start, so\n"
                 "%s// skip over bytes that cannot begin a match rather than\n"
                 "%s// stepping through them. can_begin_match says which can.\n",
              f->dir->bind, f->dir->bind, f->dir->bind);
}

static void pf_emit_memchr(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    pf_comment_memchr(c, f);
    pf_open(c, f);
    /* [K27] The `pos >= n` guard is the FIX, and it is not defensive padding:
     * docs/spec/match_api.md §3.1 makes (s == NULL, n == 0) a LEGAL subject,
     * and on it this line used to call memchr(NULL, c, 0) — technical UB in
     * EMITTED code, which a user compiling a generated matcher under their
     * own -fsanitize=undefined sees pcrec's name on. It changes no answer:
     * memchr over a zero-length range returns NULL, so the guarded early
     * `return 0` is exactly the branch the unguarded form reached one line
     * later. The BOUNDED form below needs no such guard — its own
     * `pos + 1 < n` bound already implies n > 0, hence s != NULL. */
    sb_printf(c, "%s    if (scan_position >= subject_length) return 0;\n", ind);
    sb_printf(c, "%s    const void *q = memchr(subject + scan_position, %d,"
                 " subject_length - scan_position);\n", ind, f->cand.byte);
    sb_printf(c, "%s    if (!q) return 0;\n"
                 "%s    scan_position = (size_t)((const unsigned char *)q - subject);\n",
              ind, ind);
    sb_printf(c, "%s}\n", ind);
}

static void pf_emit_memchr_bounded(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    pf_comment_memchr(c, f);
    pf_open(c, f);
    /* No early `return 0`: under a view the machine may still accept at n-1
     * or n, so this falls through to the stepped loop instead. That lost
     * early-out is exactly what `<PREFIX>_DFA_PREFILTER`'s `-bounded` half
     * tells a consumer, and it is why this is its own form rather than a
     * flag inside one. */
    sb_printf(c, "%s    if (scan_position + 1 < subject_length) {\n", ind);
    sb_printf(c, "%s        const void *q = memchr(subject + scan_position, %d,"
                 " subject_length - 1 - scan_position);\n", ind, f->cand.byte);
    sb_printf(c, "%s        scan_position = q ? (size_t)((const unsigned char *)q - subject)\n"
                 "%s                          : subject_length - 1;\n", ind, ind);
    sb_printf(c, "%s    }\n%s}\n", ind, ind);
}

static void pf_emit_bcls(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    pf_comment_bcls(c, f);
    pf_open(c, f);
    sb_printf(c, "%s    while (scan_position < subject_length &&"
                 " !%s_can_begin_match[subject[scan_position]]) scan_position++;\n",
              ind, f->p);
    sb_printf(c, "%s    if (scan_position >= subject_length) return 0;\n", ind);
    sb_printf(c, "%s}\n", ind);
}

static void pf_emit_bcls_bounded(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    pf_comment_bcls(c, f);
    pf_open(c, f);
    /* Every skip stops at n-1 so a state that accepts only under a view is
     * never skipped past; below n-1 the view is unreachable, which is also
     * why the view state cannot be stale after a skip (D11). */
    sb_printf(c, "%s    while (scan_position + 1 < subject_length &&"
                 " !%s_can_begin_match[subject[scan_position]]) scan_position++;\n",
              ind, f->p);
    sb_printf(c, "%s}\n", ind);
}

/* ---- [OPT-K] THE OFFSET-k FORMS ----------------------------------------
 *
 * docs/design/offset_k_skip.md is the note. In one paragraph: the four forms
 * above filter a candidate start on the byte AT it; these two filter it on a
 * SET of (offset, byte-set) tests that every match must satisfy, of which the
 * offset-0 test is one member. The selection lives in src/opt/prefix_k.c and
 * is carried in `UnanchStart.ofsk`; `nsel == 0` — the answer for every pattern
 * before [OPT-K] and for most patterns after it — is what makes the four forms
 * above still the ones selected, byte for byte.
 *
 * THESE TWO SIT AT THE HEAD OF THE LIST, so a pattern with a k-set takes them
 * and one without falls through to exactly what it had. `-fno-offset-skip`
 * REMOVES them (the `deny` field), which is why the denied build is
 * byte-identical to the pre-row compiler's output and is therefore a valid
 * control rather than a fourth variant (D82). */

/* Which member of the selected set the SCAN uses, and which are verifies. */
static const PrefixK *ofsk_at(const DfaForm *f, int i)
{
    return &f->ofsk->k[f->ofsk->sel[i]];
}
static const PrefixK *ofsk_scan(const DfaForm *f)
{
    return ofsk_at(f, f->ofsk->scan);
}

static bool pf_ofs_applies_common(const DfaSel *s)
{
    const UnanchStart *u = s->us;
    return s->forward && u->kind != DFA_PF_NONE && u->ofsk.nsel > 0;
}
static bool pf_ofs_bounded_applies(const DfaSel *s)
{ const UnanchStart *u = s->us; return pf_ofs_applies_common(s) && u->views; }
static bool pf_ofs_applies(const DfaSel *s)
{ return pf_ofs_applies_common(s); }

/* The emitted name of the table a multi-byte offset probes.
 *
 * OFFSET 0 GETS ITS OWN TABLE AND MUST NOT REUSE `can_begin_match`. That was
 * MISCOMPILE-1: `can_begin_match` is the DFA start state's ESCAPE set — "does
 * this byte move the machine off `fs`" — which is the right question for the
 * SCAN that walks it and the wrong one for a VERIFY that refuses a candidate
 * START. The skip lands past bytes it jumped over, so the parked state there
 * may be a seeded `s1u[UPC_WORD]`, and a byte that cannot begin a match from
 * `fs` can begin one from there. `\b\.[0-9]{4}Z` lost three matches to
 * exactly that. src/opt/prefix_k.c's `pcrec_prefix_ksets` header is the full
 * account; here the consequence is one table name. */
static void ofsk_tbl_name(char *buf, size_t n, const DfaForm *f, const PrefixK *k)
{
    snprintf(buf, n, "%s_ofs_k%d", f->p, k->k);
}

static void pf_tables_bcls(StrBuf *c, const DfaForm *f)
{
    sb_puts(c, "    /* 1 for each byte that could be the FIRST byte of a match. The\n"
               "     * forward loop uses this to skip over bytes that cannot begin\n"
               "     * one instead of stepping through them; speed only, it never\n"
               "     * changes the answer. */\n");
    cand_emit_table(c, f->p, "can_begin_match", &f->cand);
}

static void pf_tables_ofs(StrBuf *c, const DfaForm *f)
{
    for (int i = 0; i < f->ofsk->nsel; i++) {
        const PrefixK *k = ofsk_at(f, i);
        char tag[PCREC_MAX_EMIT_NAME_LEN];
        if (i == f->ofsk->scan || k->count <= 1) continue;
        sb_printf(c, "    /* 1 for each byte a match MAY BEGIN WITH %d byte%s before\n"
                     "     * its own start -- i.e. which bytes may sit at offset %d of a\n"
                     "     * match. NOT the same question as can_begin_match, which asks\n"
                     "     * whether a byte moves the machine off its start state; the\n"
                     "     * two differ on every pattern with a leading assertion, and\n"
                     "     * confusing them loses matches (MISCOMPILE-1). The candidate\n"
                     "     * filter probes this before entering the transition loop;\n"
                     "     * speed only, it never changes the answer. */\n",
                  k->k, k->k == 1 ? "" : "s", k->k);
        snprintf(tag, sizeof tag, "ofs_k%d", k->k);
        emit_u8_table(c, f->p, tag, k->set, 256);
    }
}

/* The `if (...)` a candidate must pass: every SELECTED offset except the one
 * the scan already proved, in ASCENDING OFFSET order so a reader of the
 * artifact sees the pattern's own order. A singleton set is a byte compare
 * rather than a table probe — cheaper, and it puts the byte in the artifact
 * where a reader can see it. */
static void ofsk_emit_verify(StrBuf *c, const DfaForm *f)
{
    bool first = true;
    for (int i = 0; i < f->ofsk->nsel; i++) {
        const PrefixK *k = ofsk_at(f, i);
        if (i == f->ofsk->scan) continue;
        sb_puts(c, first ? "" : " &&\n            ");
        first = false;
        if (k->count == 1) {
            if (k->k == 0) sb_printf(c, "subject[cand] == %d", k->byte);
            else           sb_printf(c, "subject[cand + %d] == %d", k->k, k->byte);
        } else {
            char tbl[PCREC_MAX_EMIT_NAME_LEN];
            ofsk_tbl_name(tbl, sizeof tbl, f, k);
            if (k->k == 0) sb_printf(c, "%s[subject[cand]]", tbl);
            else           sb_printf(c, "%s[subject[cand + %d]]", tbl, k->k);
        }
    }
    /* UNREACHABLE, and a `ctx_fail` rather than a `1` fallback (critic nit
     * N-2): offset 0 is always a member and never the scan, so the chain has
     * at least one term. A silent `1` would emit a skip that accepts every
     * candidate — correct, and with the whole mechanism switched off. */
    if (first)
        ctx_fail(f->cx, 0, "internal error: an offset-k skip with an empty "
                               "verify chain (offset 0 is always a verify member)");
}

/* Names the block's parameters, in the order `ofsk_emit_params` writes them. */
static void ofsk_emit_params(StrBuf *c, const DfaForm *f, bool decl)
{
    for (int i = 0; i < f->ofsk->nsel; i++) {
        const PrefixK *k = ofsk_at(f, i);
        char tbl[PCREC_MAX_EMIT_NAME_LEN];
        if (i == f->ofsk->scan || k->count <= 1) continue;
        ofsk_tbl_name(tbl, sizeof tbl, f, k);
        sb_printf(c, ", %s%s", decl ? "const unsigned char *" : "", tbl);
    }
}

/* LAYER 2 — the block. One function per artifact, at file scope. */
static void pf_block_ofs(StrBuf *c, const DfaForm *f)
{
    const char *p = f->p;
    const PrefixK *sc = ofsk_scan(f);
    int maxk = f->ofsk->maxk;

    sb_printf(c,
        "/* ---- THE OFFSET-k CANDIDATE-START SKIP ---------------------------\n"
        " * Every match of this pattern carries a byte from a known set at each\n"
        " * of these offsets FROM ITS OWN START, so a position that fails any\n"
        " * one of them cannot begin a match and the transition loop need not\n"
        " * be entered there (docs/design/offset_k_skip.md):\n"
        " *\n");
    for (int i = 0; i < f->ofsk->nsel; i++) {
        const PrefixK *k = ofsk_at(f, i);
        sb_printf(c, " *   offset %-2d  ", k->k);
        if (k->count == 1) { sb_puts(c, "exactly "); legend_byte(c, k->byte);
                             sb_printf(c, " (%d)", k->byte); }
        else               sb_printf(c, "one of %d bytes", k->count);
        if (i == f->ofsk->scan) sb_puts(c, "   <- SCANNED FOR");
        sb_puts(c, "\n");
    }
    sb_printf(c,
        " *\n"
        " * The scan is one pass for the offset marked above; the others are\n"
        " * checked on each candidate before the loop is entered, and a failed\n"
        " * candidate resumes the scan one position later, so no position is\n"
        " * examined twice and none is skipped. Returns the first position >=\n"
        " * `pos` that satisfies every test, or `n` when there is none.\n"
        " *\n"
        " * SPEED ONLY: it refuses exactly the starts the stepped scan would\n"
        " * refuse, so no answer depends on it. Compile with -fno-offset-skip\n"
        " * to emit the same matcher without it.\n"
        " */\n");

    sb_printf(c, "static inline size_t %s_ofsskip(const unsigned char *subject, size_t n, size_t pos", p);
    ofsk_emit_params(c, f, true);
    sb_puts(c, ")\n{\n");
    sb_printf(c, "    while (pos + %d < n) {\n", maxk);
    sb_puts(c,   "        size_t cand;\n");
    if (sc->count == 1) {
        /* THE memchr FORM. `pos + maxk < n` above implies `pos + k* < n`, so
         * the pointer is inside the subject and the length is non-zero --
         * [K27]'s memchr(NULL, c, 0) hazard closed by the loop guard rather
         * than by a second test. */
        if (sc->k == 0)
            sb_printf(c, "        const void *q = memchr(subject + pos, %d, n - pos);\n", sc->byte);
        else
            sb_printf(c, "        const void *q = memchr(subject + pos + %d, %d, n - pos - %d);\n",
                      sc->k, sc->byte, sc->k);
        sb_puts(c,   "        if (!q) return n;\n");
        if (sc->k == 0)
            sb_puts(c, "        cand = (size_t)((const unsigned char *)q - subject);\n");
        else
            sb_printf(c, "        cand = (size_t)((const unsigned char *)q - subject) - %d;\n", sc->k);
        sb_printf(c, "        if (cand + %d >= n) return n;\n", maxk);
    } else {
        /* UNREACHABLE. The selection requires the scan offset to MOVE off 0
         * (measured -- the note's S7.4) and a scan offset past 0 to be a
         * SINGLETON (S4.4), so a non-singleton scan cannot be selected. The
         * bitmap-scan arm that stood here was written for a k = 0 scan and
         * read `can_begin_match`, which is the set MISCOMPILE-1 is about; it
         * is deleted rather than left as dead emitted text. */
        ctx_fail(f->cx, 0, "internal error: an offset-k skip whose scan "
                               "offset is not a single byte value");
    }
    sb_puts(c,   "        if (");
    ofsk_emit_verify(c, f);
    sb_puts(c,   ") return cand;\n");
    sb_puts(c,   "        pos = cand + 1;\n"
                 "    }\n"
                 "    return n;\n}\n\n");
}

/* The RESEED, and it is not optional on a machine that has one.
 *
 * Today's skip jumps over bytes that leave the machine PARKED in the start
 * state, so the state after the jump is trivially still that state. This one
 * jumps over bytes that LEAVE it -- and on a `\b`-bearing machine those bytes
 * are how the class of the byte to the left is carried (the start state
 * escapes on every word character for that reason alone; the note's S2.1). So
 * the landing state is `s1u[upc(s[cand-1])]`, which is exactly what the
 * search's own initializer computes at `search_from`, through the same table.
 *
 * On a machine with no seed there is one start state and no context to carry,
 * and this emits nothing. */
static void pf_emit_ofs_reseed(StrBuf *c, const DfaForm *f, const char *ind)
{
    if (!dfa_needs_seed(f->d)) return;
    sb_printf(c, "%s%s = %s ? %s_%s_seed_state[%s_%s_byte_class[subject[%s - 1]]] : %d;\n",
              ind, f->dir->statev, f->dir->posv,
              f->p, f->dir->c.name, f->p, f->dir->c.name, f->dir->posv,
              f->repr->cell_of(f->d->s0, f->d));
}

static void pf_comment_ofs(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    sb_printf(c, "%s// Prefilter: nothing found yet and still at the start, so\n"
                 "%s// skip straight to the next position that could begin a\n"
                 "%s// match. %s_ofsskip tests %d offsets, not just this one.\n",
              ind, ind, ind, f->p, f->ofsk->nsel);
}

static void pf_emit_ofs(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    pf_comment_ofs(c, f);
    pf_open(c, f);
    sb_printf(c, "%s    size_t cand = %s_ofsskip(subject, subject_length, scan_position",
              ind, f->p);
    ofsk_emit_params(c, f, false);
    sb_puts(c, ");\n");
    sb_printf(c, "%s    if (cand >= subject_length) return 0;\n", ind);
    sb_printf(c, "%s    scan_position = cand;\n", ind);
    {
        char sub[64];
        snprintf(sub, sizeof sub, "%s    ", ind);
        pf_emit_ofs_reseed(c, f, sub);
    }
    sb_printf(c, "%s}\n", ind);
}

static void pf_emit_ofs_bounded(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->bind;
    pf_comment_ofs(c, f);
    pf_open(c, f);
    /* No early `return 0`, and the fall-back clamp is the other bounded
     * forms': under a view the machine may still accept at n-1 or n, so a
     * failed scan lands at n-1 and the stepped loop takes it from there. */
    sb_printf(c, "%s    size_t cand = %s_ofsskip(subject, subject_length, scan_position",
              ind, f->p);
    ofsk_emit_params(c, f, false);
    sb_puts(c, ");\n");
    sb_printf(c, "%s    if (cand < subject_length) {\n", ind);
    sb_printf(c, "%s        scan_position = cand;\n", ind);
    {
        char sub[64];
        snprintf(sub, sizeof sub, "%s        ", ind);
        pf_emit_ofs_reseed(c, f, sub);
    }
    sb_printf(c, "%s    } else if (scan_position + 1 < subject_length) {\n", ind);
    sb_printf(c, "%s        scan_position = subject_length - 1;\n", ind);
    {
        char sub[64];
        snprintf(sub, sizeof sub, "%s        ", ind);
        pf_emit_ofs_reseed(c, f, sub);
    }
    sb_printf(c, "%s    }\n%s}\n", ind, ind);
}

static const DfaPf dfa_pfs[] = {
    { { "offset-set-bounded",  PCREC_NO_OFFSET_SKIP, pf_ofs_bounded_applies },
      pf_tables_ofs,  pf_block_ofs, pf_emit_ofs_bounded    },
    { { "offset-set",          PCREC_NO_OFFSET_SKIP, pf_ofs_applies         },
      pf_tables_ofs,  pf_block_ofs, pf_emit_ofs            },
    { { "memchr-bounded",     0, pf_memchr_bounded_applies }, NULL, NULL, pf_emit_memchr_bounded },
    { { "memchr",             0, pf_memchr_applies         }, NULL, NULL, pf_emit_memchr         },
    { { "byte-class-bounded", 0, pf_bcls_bounded_applies   }, pf_tables_bcls, NULL, pf_emit_bcls_bounded   },
    { { "byte-class",         0, pf_bcls_applies           }, pf_tables_bcls, NULL, pf_emit_bcls           },
    { { "none",               0, cand_always               }, NULL, NULL, NULL                   },
};

static const DfaPf *dfa_pf_of(Ctx *cx, const UnanchStart *us)
{
    DfaSel s = { cx, &cx->job->dfa, us, true, -1 };
    return DFA_SELECT(DfaPf, dfa_pfs, &s, cx->opt->flags);
}

/* ---- AXIS F: the two directions ----------------------------------------- */

static void dir_fwd_skip(StrBuf *c, const DfaForm *f, int K, const char *kw)
{
    const char *ind = f->dir->bind;
    sb_printf(c, "%s%s (%s == %d) {\n", ind, kw, f->dir->statev,
              f->repr->cell_of(K, f->d));
    /* [ENG-ABS] THE TABLE NAME IS THE MACHINE'S, not the literal "forward".
     * It was `%s_forward_stay%d` while forward and reverse were the only two
     * directions and the forward one's name was "forward"; the anchored
     * machine's stay tables are emitted as `<p>_anchored_stay<K>` by
     * `emit_machine_tables` (which has always derived the tag from
     * `dir->c.name`), so a hardcoded "forward" here emitted a reference to a
     * table that does not exist in that function. Byte-for-byte unchanged on
     * the forward machine, whose `c.name` IS "forward". */
    sb_printf(c, "%s    while (scan_position %s subject_length &&"
                 " %s_%s_stay%d[subject[scan_position]]) scan_position++;\n",
              ind, f->views ? "+ 1 <" : "<", f->p, f->dir->c.name, K);
    /* With the accept check ahead of us (the non-view order) the skipped
     * run's final position would otherwise go unrecorded; under a view the
     * check runs after the skip and already covers it. */
    if (!f->views && f->d->st[K].up[UPC_PLAIN].accept)
        sb_printf(c, "%s    %s = %s;\n", ind, f->dir->recv, f->dir->posv);
    sb_printf(c, "%s}\n", ind);
}

static void dir_rev_skip(StrBuf *c, const DfaForm *f, int K, const char *kw)
{
    const char *ind = f->dir->bind;
    /* `pp` only ever DECREASES, so one entry guard is enough to keep the
     * whole skip below the view region. */
    sb_printf(c, "%s%s (%s == %d%s) {\n", ind, kw, f->dir->statev,
              f->repr->cell_of(K, f->d),
              f->views ? " && rewind_position + 1 < subject_length" : "");
    /* Same rule as `dir_fwd_skip`'s: the table name is the machine's. Nothing
     * but the reverse machine reaches this emitter today, so the text is
     * unchanged; spelling it from `dir->c.name` is what stops the next
     * direction re-learning [ENG-ABS]'s lesson. */
    sb_printf(c, "%s    while (rewind_position > search_from &&"
                 " %s_%s_stay%d[subject[rewind_position - 1]]) rewind_position--;\n",
              ind, f->p, f->dir->c.name, K);
    if (!f->views && f->d->st[K].up[UPC_PLAIN].accept)
        sb_printf(c, "%s    %s = %s;\n", ind, f->dir->recv, f->dir->posv);
    sb_printf(c, "%s}\n", ind);
}

static void dir_fwd_bound_accept(StrBuf *c, const DfaForm *f)
{
    /* `pos == n` is the position with NO next byte, where §3.6.2 makes the
     * accept SCALAR: out of subject is neither a word character nor a
     * newline, and the base accept already is that bit. */
    /* [ENG-ABS] THE MACHINE'S NAME, not the literal "forward" — `dir_fwd_skip`'s
     * rule, and this emitter is SHARED by the forward scan and the anchored
     * MATCH-HERE scan, so a hardcoded name here referred to the wrong
     * machine's accept table from inside `<prefix>_match`. Byte-for-byte
     * unchanged on the forward machine, whose `c.name` IS "forward". */
    char ab[PCREC_MAX_EMIT_NAME_LEN];
    sb_printf(c, "%s    if (%s_%s_accepts(%s%s)) %s = %s;\n",
              f->dir->bind, f->p, f->dir->c.name,
              fold_arg(ab, sizeof ab, f, &f->acc_fold, "is_accepting"),
              f->src, f->dir->recv, f->dir->posv);
}

static void dir_rev_bound_accept(StrBuf *c, const DfaForm *f)
{
    /* MECHANISM 4's REVERSE TERMINATION (§3.8.3.1) — the site whose absence
     * is a LOST MATCH. At `pp == startpos` the walk breaks before ever
     * reading `s[startpos-1]`, so a LEADING `\b`/`\B` at the match start is
     * otherwise evaluated with no left context. `\b` is safe BY ACCIDENT
     * there, which is why a leading-`\b` sweep reports clean against a design
     * that throws matches away; `\B` inverts it — `\Bfoo` on "xfoo" at
     * startpos 1 is (1,4) in libpcre2 and no-match blind.
     *
     * Note the pleasing asymmetry with the forward boundary above: that one
     * needs a SCALAR accept because no byte exists past `n`; this one needs a
     * CONTEXT-INDEXED accept because the byte exists and is merely outside
     * the window. `startpos == 0` is out of subject to the left — non-word —
     * hence the scalar arm. */
    /* Same rule as the forward site's: the machine's name, never the literal.
     * Nothing but the reverse machine reaches this emitter today, so the text
     * is unchanged. */
    const char *m = f->dir->c.name;
    char ab[PCREC_MAX_EMIT_NAME_LEN];
    sb_printf(c, "%s    if (search_from"
                 " ? %s_%s_accepts_class(%s_%s_is_accepting_by_class, %s,\n"
                 "%s                          %s_%s_byte_class[subject[search_from - 1]])\n"
                 "%s                 : %s_%s_accepts(%s%s))"
                 " %s = %s;\n",
              f->dir->bind, f->p, m, f->p, m,
              f->src,
              f->dir->bind, f->p, m,
              f->dir->bind, f->p, m,
              fold_arg(ab, sizeof ab, f, &f->acc_fold, "is_accepting"),
              f->src, f->dir->recv, f->dir->posv);
}

static const DfaDir dfa_dir_forward = {
    { "forward", 0, cand_always },
    "Forward", "FORWARD", "forward_state", "forward_view_state",
    "scan_position", "last_accept_position",
    "    ", "        ", false, true,
    "    /* ---- FORWARD TABLES: find where a match ENDS ------------------\n"
    "     * Byte class of every possible input byte. The pattern can only\n"
    "     * tell a few kinds of byte apart, so all 256 values fold into a\n"
    "     * few classes and the transition table needs one column per class\n"
    "     * rather than 256.\n"
    "     *\n",
    "a match may end",
    "    if (search_from > subject_length) return 0;\n",
    "search_from", "subject[search_from - 1]",
    "scan_position >= subject_length",
    "subject[scan_position]", "subject[scan_position++]", "scan_position++",
    dir_fwd_skip, dir_fwd_bound_accept,
    "scan_position < subject_length", "scan_position - 1",
};

static const DfaDir dfa_dir_reverse = {
    { "reverse", 0, cand_always },
    "Reverse", "REVERSE", "reverse_state", "reverse_view_state",
    "rewind_position", "match_start_position",
    "        ", "            ", true, false,
    "    /* ---- REVERSE TABLES: find where that match BEGINS -------------\n"
    "     * The same three-table shape, built from the pattern read right to\n"
    "     * left and walked backwards from the end the forward scan found.\n"
    "     * The two machines are independent and need not agree.\n"
    "     *\n",
    "the backwards walk has consumed a whole match",
    NULL,
    "match_end_position < subject_length", "subject[match_end_position]",
    "rewind_position <= search_from",
    "subject[rewind_position - 1]", "subject[--rewind_position]", "rewind_position--",
    dir_rev_skip, dir_rev_bound_accept,
    "rewind_position > search_from", "rewind_position + 1",
};

/* [ENG-ABS] THE THIRD DIRECTION, and it is a direction in exactly axis F's
 * sense: "how a scan spells its position, its bound, the answer it records and
 * the byte it reads". It is FORWARD — every string below is the forward
 * object's, character for character, with two exceptions — but it is not the
 * forward SEARCH, and the difference is what it is rooted at:
 * `Nfa.anch_start` rather than the start-anywhere self-loop, so it answers
 * "where does the match that begins AT `search_from` end?" rather than "where
 * does the first match at or after `search_from` end?"
 * (docs/design/anchored_match_unwrapped.md §2, §3.3).
 *
 * THE TWO EXCEPTIONS.
 *
 *   - `range_guard` returns `-1`, not `0`: this machine's loop is the body of
 *     `<prefix>_match`, whose failure value is the entry's (a length, or -1)
 *     and not `<prefix>_search`'s found-count.
 *   - `prefilter_owns_start` is FALSE. A candidate-start prefilter CHOOSES
 *     WHERE THE SCAN BEGINS, which is sound for a search and wrong for a
 *     match-here, where the start is the caller's. Nothing here has to say so:
 *     `anch_start` hands this machine's form an `UnanchStart` whose `kind` is
 *     `DFA_PF_NONE` and whose `ofsk.nsel` is 0, and every axis-B candidate
 *     requires one of those to be non-trivial, so axis B's total fallback is
 *     what the ordinary walk selects. The flag here is about the STAY skips,
 *     which are a different mechanism and DO apply (§3.7).
 *
 * WHY THE VARIABLE NAMES ARE THE FORWARD SCAN'S. `<prefix>_match`'s emitted
 * body opens by binding `subject`, `subject_length` and `search_from` from the
 * `rx_ctx`, so every direction string, every seed initializer and every bound
 * expression below is reused character for character rather than respelled —
 * which is also what makes the seeded start dispatch provably the same line
 * against the same byte (`subject[search_from - 1]`, §3.5). */
static const DfaDir dfa_dir_anchored = {
    { "anchored", 0, cand_always },
    "Anchored", "ANCHORED", "anchored_state", "anchored_view_state",
    "scan_position", "last_accept_position",
    "    ", "        ", false, false,
    "    /* ---- ANCHORED TABLES: does a match begin HERE, and where does\n"
    "     * it end? Built from the same pattern as the forward scan above but\n"
    "     * WITHOUT its start-anywhere self-loop, so a walk that dies has\n"
    "     * proved there is no match at ctx->pos -- and a walk that accepts\n"
    "     * has found one that begins there, so no backwards pass is needed.\n"
    "     *\n",
    "a match beginning at ctx->pos may end",
    "    if (search_from > subject_length) return -1;\n",
    "search_from", "subject[search_from - 1]",
    "scan_position >= subject_length",
    "subject[scan_position]", "subject[scan_position++]", "scan_position++",
    dir_fwd_skip, dir_fwd_bound_accept,
    "scan_position < subject_length", "scan_position - 1",
};

/* ---- AXIS G: WHICH FORM THE ANCHORED MATCH-HERE ENTRY TAKES -------------
 *
 * [ENG-ABS] (docs/design/anchored_match_unwrapped.md §5.1). Two objects, and
 * the choice is per ARTIFACT rather than per machine — it is a question about
 * an ENTRY POINT, which is why this axis has no `DfaForm` and its objects
 * carry no emitter pointer: the two bodies are different enough (one has
 * tables and a scan loop, the other is four lines around a call to
 * `<prefix>_search`) that a shared skeleton would be a switch wearing a
 * skeleton's clothes.
 *
 * `unwrapped` applies exactly when `Job.anchored_ok` is set — the artifact is
 * this emitter's own (not a VM hybrid's inlined prefilter), it is ENG_UNANCH,
 * and the anchored machine BUILT within the DFA caps — and when the artifact's
 * engine is not the empty one, whose `<prefix>_search` is a single `return 0`
 * and whose `_match` is correctly four lines around it.
 *
 * `-fno-anchored-dfa` is a `deny` FIELD on the first candidate, D82's shape:
 * the flag removes the object and the ordinary walk selects the fallback.
 * Nothing branches on the flag here. */
typedef struct DfaMatch {
    DfaCand c;
} DfaMatch;

static bool match_unwrapped_applies(const DfaSel *s)
{
    return s->cx->job->anchored_ok && !dfa_engine_is_empty(s->cx);
}

static const DfaMatch dfa_matches[] = {
    { { "unwrapped",     PCREC_NO_ANCHORED_DFA, match_unwrapped_applies } },
    { { "search-filter", 0,                     cand_always             } },
};

/* THE ONE SELECTION, and the reason it takes a bare `Ctx` rather than a
 * `DfaSel`: this axis's predicate asks nothing about a MACHINE. Passing a
 * fabricated `d` would invite a later candidate to read it. */
static const DfaMatch *dfa_match_of(Ctx *cx)
{
    DfaSel s = { cx, NULL, NULL, false, -1 };
    return DFA_SELECT(DfaMatch, dfa_matches, &s, cx->opt->flags);
}

static const char *dfa_match_name(Ctx *cx) { return dfa_match_of(cx)->c.name; }

static bool dfa_match_is_unwrapped(Ctx *cx)
{ return dfa_match_of(cx) == &dfa_matches[0]; }

/* ---- AXIS J: WHICH FORM THE SEARCH ENTRY'S START RECOVERY TAKES ---------
 *
 * [OPT-5 STEP 2] (docs/design/opt5_step2_twopass.md §1.2, §3.2, §4.1). Axis
 * G's sibling: G answers "which form does `<prefix>_match` take", this
 * answers "which form does `<prefix>_search`'s POST-LOOP BLOCK take". It has
 * G's properties for G's reasons — a question about an ENTRY POINT rather
 * than about one machine's dimensions, so no `DfaForm`, bare `DfaCand`s, one
 * `if` in `emit_unanchored`, and the two bodies (a whole reverse machine with
 * tables, an accessor block and a scan loop, versus two assignments) are far
 * too different for a shared skeleton.
 *
 * THE LETTER IS J AND NOT H. H and I are STEP 1's — the scan edge's REGION
 * and BODY axes at `:4317`/`:4349`, named by letter there, in
 * `scan_edge_of`'s own comment and in `src/gen/CLAUDE.md`. A collision would
 * be SILENT: `--list-axes` walks the candidate arrays generically and would
 * print two axes under one letter.
 *
 * ================== WHAT `pinned` CLAIMS, AND WHY ==================
 *
 * `<prefix>_search` scans the same bytes twice: forward to find where a match
 * ENDS, backwards to find where it BEGAN. When the forward machine's start
 * state accepts UNCONDITIONALLY, the backwards pass computes `search_from` on
 * every call, provably, at compile time:
 *
 *   1. A match exists at `search_from` for every `search_from <= n` — at
 *      minimum the empty one — so the search returns 1 on every call, and the
 *      spec's zero-length-is-success convention (match_api.md §3.1) is what
 *      makes that a correct answer rather than a suspicious one.
 *   2. D3's accept-pruning removes the start-anywhere self-loop from the
 *      closure of any accepting state — `unanch_start`'s own comments state
 *      it twice, independently. If the START state accepts, that pruning has
 *      fired BEFORE THE FIRST BYTE IS READ: no later start is ever spawned,
 *      so every accept the forward loop records belongs to a thread that
 *      began at `search_from`.
 *   3. Therefore `last_accept_position` is the end of the LONGEST match
 *      beginning at `search_from`, that match is the leftmost one, and
 *      `match_start_position == search_from` unconditionally.
 *
 * The reverse machine is then dead text and is NOT EMITTED AT ALL: no tables,
 * no accessor block, no stay-skip tables, no scan-edge membership tables, no
 * loop. That is a SIZE event as much as a speed one.
 *
 * ================== THE PREDICATE, CLAUSE BY CLAUSE ==================
 *
 * Every clause DECLINES rather than stretches, and each one has a failure
 * direction on record in the note's §3.4.
 *
 * P0 — THE ROUTING DEPENDENCY, INHERITED AND THEREFORE STATED. The predicate
 * reads `fs = fd->s0`. That is the right state at `search_from == 0` only
 * because `ENG_UNANCH` implies `!nfa_has_bot` (`src/core/compile.c`), i.e. no
 * `N_BOT`/`N_BOT_M`/`N_GSTART`: `s0` is closed with `bot_ok = true,
 * gst_ok = true` and `s1u[UPC_PLAIN]` with `false, false`, so with none of
 * those nodes present the two closures coincide and intern to the same id.
 * NOTHING IN P1-P5 CHECKS THIS — `dfa_needs_seed` compares only `s1u[u]`
 * ACROSS `u` and would not notice an `s0 != s1u[PLAIN]` split, and
 * `seed_emit_constant` then emits `s0` unconditionally at every
 * `search_from`. A future engine-selection change that routed a BOT-bearing
 * machine here would break the elision SILENTLY, so it is ASSERTED below
 * rather than left to the routing.
 *
 * P1 — `fd->st[fs].up[UPC_PLAIN].accept != 0`. The start state accepts under
 * the PLAIN view. *Not* `state_acc_any`: that bit is `unanch_start`'s
 * deliberate widening, whose own neighbouring comment says it is
 * BELT-AND-BRACES and instructs the reader not to cite it as a premise.
 * Reusing it here would invert its meaning — `$` alone is the named
 * counter-example, and on `"abc"` from `startpos = 0` the widened read
 * reports `[0,3)` where the true span is `[3,3)`.
 *
 * P2 — the accept is position- and context-INVARIANT, via
 * `pcrec_state_view_invariant`, which is `src/opt/scanedge.c`'s own
 * `member_ok` body and not a second copy of it (that pass's precondition (3)
 * exists for the same reason: a view makes a state's accept differ at
 * `pos == n-1`/`pos == n`, positions a scan can pass). It is STRICTER than
 * soundness needs — the elision needs only the variant's accept BIT to agree,
 * where this refuses a state carrying a variant at all — and that is a
 * deliberate conservative choice: one derivation for a fact two passes read.
 *
 * P3 — under `dfa_needs_seed` (mechanism 4: `\b`, `(?m)^`, where a search at
 * `startpos > 0` begins in `s1u[u]` rather than in `fs`), EVERY live seed
 * state must be LIVE and satisfy P1 and P2 as well.
 *
 *   THE LIVENESS HALF IS NOT TIDINESS. `d->s1u[u]` is `-1` when no
 *   `(view, class-context)` closure is live. A search at `search_from > 0`
 *   that seeds into a DEAD state records no accept, the kept
 *   `last_accept_position == (size_t)-1` gate returns 0, AND THAT IS THE
 *   CORRECT ANSWER — no match begins there. Without this conjunct the elision
 *   would write a FABRICATED EMPTY MATCH at `search_from`: a match reported
 *   where there is none, which is strictly worse than every other failure
 *   direction here (all of which produce a too-small `caps[0][0]`).
 *   `dfa_premul` refuses pre-multiplication on exactly this condition;
 *   STEP 2 takes the same posture. AND NOTHING HERE RELIES ON "a dead token
 *   records nothing": the accept probe on a dead token is already latent UB
 *   (`is_accepting[-1]` indexed, `[65535]` premultiplied — `dfa_premul`'s own
 *   note), a PRE-EXISTING hazard this row does not fix and must not lean on.
 *
 * P4 — the artifact's scan is `unanchored`. `attempt` scans are a different
 * emitter with no reverse pass to elide; the `empty` engine is one
 * `return 0`.
 *
 * P5 — is an ENGINE-LEVEL fact and is deliberately NOT a clause here. `\K`
 * would break the identification of "where reporting begins" with "where
 * matching began", and `fit.chosen == ENGM_DFA` implies no `\K` — so no
 * artifact whose `_match` and `_search` this emitter OWNS carries one. A VM
 * HYBRID can put a `\K` machine through this emitter as its inlined
 * prefilter, and there the elision is SAFE FOR A DIFFERENT REASON that must
 * be said rather than assumed: `rx_search_run` consumes `window[0][0]` as a
 * LOWER BOUND on the attempt start, never as the answer, and `search_from` is
 * the strongest sound lower bound there is. So a pinned hybrid is if anything
 * MORE conservative than today. `tests/codegen/run_search_pinned.sh` asserts
 * the engine-level fact and the hybrid's bound-not-answer shape separately. */
typedef struct DfaSearchStart {
    DfaCand c;
} DfaSearchStart;

/* P0's assertion, and it is the real guard for two of the clauses above
 * rather than a decoration. It fires as a loud internal error, which is this
 * file's standing preference over a silent fallback (`ctx_fail` is what the
 * offset-k skip's two unreachable arms use, for the same reason).
 *
 * The seed-liveness half has NO SABOTAGE WITNESS and cannot currently have
 * one — the note's §5.6b derives that the P3-discriminating population looks
 * EMPTY on `ENG_UNANCH`, not merely unpopulated — so an assertion is the
 * correct instrument: it needs no witness, because its firing IS the finding.
 * Sabotage row S219 ships declared `UNREACHED` beside it and exists so that
 * the `[MECH-REACH]` reverse check reads NOW REACHED the day somebody builds
 * the machine this assertion is waiting for. */
static void start_pinned_assert_routing(Ctx *cx, const Dfa *fd, int fs)
{
    if (fd->s1u[UPC_PLAIN] != fs)
        ctx_fail(cx, 0, "internal error: the start-pinned search's P0 routing "
                        "premise is broken -- ENG_UNANCH's s0 (%d) and "
                        "s1u[UPC_PLAIN] (%d) are different states, so the "
                        "elision's proof is about a state the search at "
                        "startpos == 0 may not occupy (docs/design/"
                        "opt5_step2_twopass.md P0)", fs, fd->s1u[UPC_PLAIN]);
    for (int u = 0; u < UPC_N; u++)
        if (fd->s1g[u] != fd->s1u[u])
            ctx_fail(cx, 0, "internal error: the start-pinned search reached a "
                            "machine with a \\G start family (s1g[%d] = %d, "
                            "s1u[%d] = %d); ENG_UNANCH implies no N_GSTART, so "
                            "this artifact's routing has moved under the "
                            "elision's P0 premise", u, fd->s1g[u], u,
                            fd->s1u[u]);
    if (dfa_needs_seed(fd))
        for (int u = 0; u < UPC_N; u++) {
            if (!upc_emit_live(u)) continue;
            if (fd->s1u[u] < 0)
                ctx_fail(cx, 0, "internal error: the start-pinned search "
                                "accepted a machine with a DEAD seed state "
                                "(s1u[%d] < 0); P3's liveness conjunct should "
                                "have declined it, and eliding here would "
                                "report an empty match at a startpos where "
                                "there is none", u);
        }
}

/* THE PREDICATE. `DfaSel.d` IS the forward machine and is read as such — this
 * axis is genuinely about it, so unlike axis G there is nothing fabricated to
 * invite a later candidate to misread. */
static bool start_pinned_applies(const DfaSel *s)
{
    Ctx *cx = s->cx;
    /* P4. `dfa_engine_is_empty` is asked through the shared predicate rather
     * than by re-spelling `us.empty`, `dfa_scan_name`'s own rule (r37 #5). */
    if (cx->job->engine != PCREC_ENG_UNANCH) return false;
    if (dfa_engine_is_empty(cx)) return false;

    const Dfa *fd = s->d;
    int fs = fd->s0;
    if (fs < 0 || fs >= fd->n) return false;

    /* P1 — the NARROWED read. */
    if (!fd->st[fs].up[UPC_PLAIN].accept) return false;
    /* P2 — one derivation, shared with the scan-edge pass. */
    if (!pcrec_state_view_invariant(&fd->st[fs])) return false;

    /* P3 — every LIVE seed state, and liveness first. */
    if (dfa_needs_seed(fd)) {
        for (int u = 0; u < UPC_N; u++) {
            if (!upc_emit_live(u)) continue;
            int su = fd->s1u[u];
            if (su < 0) return false;                       /* the LIVENESS half */
            if (su >= fd->n) return false;
            if (!fd->st[su].up[UPC_PLAIN].accept) return false;
            if (!pcrec_state_view_invariant(&fd->st[su])) return false;
        }
    }
    return true;
}

/* `-fno-start-pinned` is a `deny` FIELD on the first candidate, D82's shape:
 * the flag REMOVES the object and the ordinary walk selects the fallback.
 * Nothing branches on the flag, and `--list-axes` picks this array up with no
 * edit because that walk is generic over `DfaCand`'s common leading member. */
static const DfaSearchStart dfa_search_starts[] = {
    { { "pinned",       PCREC_NO_START_PINNED, start_pinned_applies } },
    { { "reverse-pass", 0,                     cand_always          } },
};

/* THE ONE SELECTION. It takes a bare `Ctx` because every caller has one and
 * none of them holds a `DfaSel`; the `d` it builds is the artifact's own
 * forward machine, which is the machine this axis is about. */
static const DfaSearchStart *dfa_search_start_of(Ctx *cx)
{
    DfaSel s = { cx, &cx->job->dfa, NULL, true, -1 };
    return DFA_SELECT(DfaSearchStart, dfa_search_starts, &s, cx->opt->flags);
}

static const char *dfa_search_start_name(Ctx *cx)
{ return dfa_search_start_of(cx)->c.name; }

static bool dfa_search_is_pinned(Ctx *cx)
{ return dfa_search_start_of(cx) == &dfa_search_starts[0]; }

/* ---- [CHK-2] `--list-axes`: READ-ONLY ACCESS TO THE SIX LAYER-1 LISTS ---
 *
 * `pcrec --list-axes` (src/parse/axes_dump.c) needs the SAME name+deny data
 * this file's own `dfa_select` walks, rather than a hand-copied restatement
 * of it (docs/dev/learnings.md §3: "a REFERENCE BUILD assembled by ... a
 * hand-enumerated list drifts silently from the subject's source set"). A
 * candidate NEWLY ADDED to one of these arrays — the offset-k skip lane's
 * own bit-16 candidate among them — therefore appears in the dump with no
 * edit here: the walk below is generic over `DfaCand`'s common leading
 * member, exactly as `dfa_select` is.
 *
 * `applies` is DELIBERATELY NOT CALLED: evaluating a real candidate's
 * predicate needs a genuine `DfaSel` (a live `Ctx`/`Dfa`/direction), which a
 * context-free listing command does not have and must not fabricate — a
 * fabricated one could silently answer a different question than a real
 * compile does. `axes_dump.c` carries its own hand-written one-line English
 * summary of each `applies` clause, cross-checked against this file's own
 * comments by a human at review time rather than derived, and named as such
 * in the dump's own header comment and in docs/spec/registry.md. */
size_t pcrec_dfa_axis_cands(const void *list, size_t n, size_t stride,
                            PcrecAxisCand *out, size_t cap)
{
    const char *base = (const char *)list;
    size_t k = 0;
    for (size_t i = 0; i < n && k < cap; i++) {
        const DfaCand *c = (const DfaCand *)(const void *)(base + i * stride);
        out[k].name = c->name;
        out[k].deny = c->deny;
        k++;
    }
    return k;
}

#define AXIS_LIST(list) \
    pcrec_dfa_axis_cands((list), sizeof(list) / sizeof((list)[0]), \
                         sizeof((list)[0]), out, cap)

size_t pcrec_dfa_axis_table_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_reprs); }
size_t pcrec_dfa_axis_prefilter_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_pfs); }
size_t pcrec_dfa_axis_view_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_views); }
size_t pcrec_dfa_axis_seed_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_seeds); }
size_t pcrec_dfa_axis_accept_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_accs); }
/* [ENG-ABS] axis G rides the SAME generic walk — its objects are `DfaCand`-
 * headed like the other five lists, so `--list-axes` and the registry check
 * see the new candidates and the new deny bit with no hand-copied
 * restatement. */
size_t pcrec_dfa_axis_match_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_matches); }
/* [OPT-5 STEP 2] axis J, on the same terms as axis G one line up: its objects
 * are `DfaCand`-headed, so the dump and the registry check see the new
 * candidates and `PCREC_NO_START_PINNED` with no hand-copied restatement. */
size_t pcrec_dfa_axis_searchstart_cands(PcrecAxisCand *out, size_t cap)
{ return AXIS_LIST(dfa_search_starts); }
#undef AXIS_LIST

/* Axis F is not a candidate LIST (emitter_form.md §3, axis F: "Not a
 * candidate LIST: the two objects are named directly ... because 'which
 * machine am I emitting' is not a question about the machine's
 * dimensions"), so there is no array to walk — both objects are ALWAYS
 * emitted, once each, per machine. Returned as a fixed pair for the dump's
 * uniform iteration; `deny` is 0 on both by construction (D82: this axis has
 * no `-fno-*` knob, and the dump's job is to report that truthfully rather
 * than invent one). */
size_t pcrec_dfa_axis_direction_cands(PcrecAxisCand *out, size_t cap)
{
    size_t k = 0;
    if (k < cap) { out[k].name = dfa_dir_forward.c.name; out[k].deny = dfa_dir_forward.c.deny; k++; }
    if (k < cap) { out[k].name = dfa_dir_reverse.c.name; out[k].deny = dfa_dir_reverse.c.deny; k++; }
    /* [ENG-ABS] the third object. It is NOT "always" the way the other two
     * are — an artifact carries it only where axis G selected `unwrapped` —
     * but it is still a named object rather than a list entry, for axis F's
     * own reason, and the dump's `applies` column says so in prose. `deny` is
     * 0 here on purpose: the flag that removes this MACHINE is axis G's, on
     * axis G's candidate, and reporting it twice would let a reader think two
     * things can be denied independently. */
    if (k < cap) { out[k].name = dfa_dir_anchored.c.name; out[k].deny = dfa_dir_anchored.c.deny; k++; }
    return k;
}

/* ---- [OPT-5] THE SCAN EDGE, emitted once for all three directions -------
 *
 * `src/opt/scanedge.c` is the pass and its header carries the criterion, the
 * five preconditions and the argument that licenses deleting the run's
 * interior states. What lives here is the LOOP, and the two things about it
 * that are the whole point:
 *
 *   - THE LOOP-CARRIED VALUE IS THE CURSOR. No table is read inside it, so
 *     iteration i+1's load address is known the instant iteration i's cursor
 *     is — which is the ONE structural difference
 *     `docs/dev/opt5_step0_profile.md` §3 measured between the DFA's 3.62
 *     ns/byte and the VM's 0.60 on the same language. It is deliberately the
 *     same shape as the VM's own possessified span loop (§3.2), down to the
 *     three-conjunct `while`, because that shape is the one gcc was measured
 *     compiling into an address-independent loop on this box.
 *   - THE STATE IS NOT UPDATED ON AN EARLY EXIT, and that is not an
 *     omission. Every member of the run has the same exit target and the same
 *     accept bit, so leaving the variable at the HEAD is indistinguishable
 *     from setting it to the true `u_k` — and it is what removes the last
 *     table read from the whole construct.
 */

/* ---- AXIS H: DOES THIS STATE EMIT AN EDGE AT ALL ------------------------
 *
 * The REGION decision, as a D82 selection rather than an `if` inside the
 * walk emitter (manager ruling R1.1, 2026-08-31, from Frank's design
 * question). It is per STATE, which is what `DfaSel.st` exists for, and it
 * is where `-fno-scan-edge` rides the axis machinery: `deny` REMOVES the
 * first candidate and the ordinary walk selects the fallback, exactly as
 * `-fno-anchored-dfa` removes axis G's `unwrapped`.
 *
 * THE DENY BIT IS HERE AND ALSO AT THE PASS, AND THAT IS ONE FACT WITH TWO
 * READERS RATHER THAN TWO MECHANISMS. `src/opt/scanedge.c` reads the same
 * bit because DELETING a run's interior states is not something an emitter
 * filter can undo — a denied build must keep the states the walk needs, so
 * the pass has to see the flag before it removes anything. The filter here
 * is therefore unreachable in a denied build (no state carries an
 * annotation, so `edge_applies` is false anyway) and is kept because the
 * axis is what `--list-axes` reads to name the flag that addresses it;
 * reporting 0 there would tell a caller the axis has no knob. */
struct DfaEdge {
    DfaCand c;
};

static bool edge_applies(const DfaSel *s)
{
    return s->st >= 0 && s->st < s->d->n && s->d->st[s->st].scan_span != 0;
}

static const DfaEdge dfa_edges[] = {
    { { "scan-edge",  PCREC_NO_SCAN_EDGE, edge_applies } },
    { { "table-walk", 0,                  cand_always  } },
};

/* ---- AXIS I: THE EDGE'S RUN-EXTENSION BODY ------------------------------
 *
 * Manager ruling R1.2: the body is its own form axis with representation
 * objects, and D82 bound 3 is satisfied on day one because two REAL forms
 * exist. Both keep the loop-carried register a CURSOR, which is the whole
 * property `docs/dev/opt5_step0_profile.md` §3 measured; they differ in what
 * the class test costs.
 *
 *   `range`   a contiguous byte set, tested by subtract-and-compare against
 *             two IMMEDIATES baked into the instruction stream. No memory
 *             but the subject is touched.
 *   `bitmap`  any other byte set, tested by a 256-byte membership table.
 *             THE LOAD IS VALUE-ADDRESSED, NOT RESULT-ADDRESSED — its
 *             address is `table + the byte this iteration read`, never the
 *             value a previous iteration's load returned — so the cursor is
 *             still the only loop-carried register and the dependency-chain
 *             property the transform exists for is intact. That is the
 *             difference between this table read and the transition table's,
 *             and it is why a bitmap body is a cost rather than a defeat.
 *
 * THE THIRD SLOT IS NAMED AND NOT BUILT. A SIMD run-extension form
 * (`studies/simd1`'s branchless classify + count-leading-zeros, [OPT-SIMD]'s
 * row) belongs at the TOP of this list: a new object plus its `emit_test`
 * body, with nothing above the axis moving — not the criterion, not the
 * stamp, not the deletion, not the gates. Manager ruling R2 (Frank, same
 * day) fixes its CONTRACT as ISA-NEUTRAL: it is "a SIMD run-extension form,
 * per-ISA gated, with the scalar forms always available as the fallback",
 * never an x86 slot — Frank's own machine is aarch64/NEON. Nothing this axis
 * emits today is ISA-conditional, and the two scalar forms are the portable
 * baseline that keeps a per-ISA form optional forever.
 *
 * `bitmap` applies unconditionally and is the list's total fallback (D82
 * rule 1): every byte set has a membership table. Neither object carries a
 * `deny` bit — the FLAG belongs to axis H, which decides whether there is an
 * edge at all, and putting it here as well would let a reader think a body
 * could be denied while the edge survived, which would be a machine with
 * deleted states and no loop to replace them. */
struct DfaScan {
    DfaCand c;
    void  (*emit_test)(StrBuf *c, const DfaForm *f, int head);
    /* NULL == this body needs no table of its own. */
    void  (*emit_tables)(StrBuf *c, const DfaForm *f, int head);
};

static bool scan_range_applies(const DfaSel *s)
{
    return s->st >= 0 && s->st < s->d->n &&
           pcrec_scan_range(s->d, s->d->st[s->st].scan_cls, NULL, NULL);
}

static void scan_test_range(StrBuf *c, const DfaForm *f, int head)
{
    int lo, hi;
    pcrec_scan_range(f->d, f->d->st[head].scan_cls, &lo, &hi);
    if (lo == hi)       sb_printf(c, "%s == %d", f->dir->peek, lo);
    else if (lo == 0)   sb_printf(c, "%s <= %d", f->dir->peek, hi);
    else                sb_printf(c, "(unsigned char)(%s - %d) <= %d",
                                  f->dir->peek, lo, hi - lo);
}

static void scan_test_bitmap(StrBuf *c, const DfaForm *f, int head)
{
    sb_printf(c, "%s_%s_scan%d[%s]", f->p, f->dir->c.name, head, f->dir->peek);
}

static void scan_tables_bitmap(StrBuf *c, const DfaForm *f, int head)
{
    uint8_t set[256];
    int cls = f->d->st[head].scan_cls;
    for (int b = 0; b < 256; b++) set[b] = (uint8_t)(f->d->clsmap[b] == cls);
    char name[PCREC_MAX_EMIT_NAME_LEN + 16];
    snprintf(name, sizeof name, "%s_scan%d", f->dir->c.name, head);
    emit_u8_table(c, f->p, name, set, 256);
}

static const DfaScan dfa_scans[] = {
    { { "range",  0, scan_range_applies }, scan_test_range,  NULL },
    { { "bitmap", 0, cand_always        }, scan_test_bitmap, scan_tables_bitmap },
};

/* THE TWO SELECTIONS, per state. They are the ONLY readers of these lists
 * and every consumer — the emitted test, the emitted table, the artifact's
 * stamp — goes through them, so "the stamp is the chosen object's name"
 * (D82 rule 2) holds structurally rather than by convention. */
static const DfaEdge *dfa_edge_of(Ctx *cx, const Dfa *d, int st)
{
    DfaSel s = { cx, d, NULL, true, st };
    return DFA_SELECT(DfaEdge, dfa_edges, &s, cx->opt->flags);
}

static const DfaScan *dfa_scan_of(Ctx *cx, const Dfa *d, int st)
{
    DfaSel s = { cx, d, NULL, true, st };
    return DFA_SELECT(DfaScan, dfa_scans, &s, cx->opt->flags);
}

static bool dfa_edge_taken(const DfaEdge *e) { return e == &dfa_edges[0]; }

static const char *dfa_scan_body_name(Ctx *cx, const Dfa *d, int st)
{ return dfa_scan_of(cx, d, st)->c.name; }

/* [CHK-2]'s generic walk over axes H and I. They sit HERE rather than with
 * the other six accessors ~150 lines above because that block is written
 * before these two arrays exist; `AXIS_LIST` is `#undef`-ed at the end of
 * that block, so the two calls are spelled out. Adding the ISA-neutral SIMD
 * body object ruling R2 reserves a slot for needs NO edit here, in
 * `axes_dump.c`'s iteration, or in the registry check's row sweep -- only
 * its own `applies` and `emit_test`. */
size_t pcrec_dfa_axis_edge_cands(PcrecAxisCand *out, size_t cap)
{
    return pcrec_dfa_axis_cands(dfa_edges, sizeof dfa_edges / sizeof dfa_edges[0],
                                sizeof dfa_edges[0], out, cap);
}
size_t pcrec_dfa_axis_scanbody_cands(PcrecAxisCand *out, size_t cap)
{
    return pcrec_dfa_axis_cands(dfa_scans, sizeof dfa_scans / sizeof dfa_scans[0],
                                sizeof dfa_scans[0], out, cap);
}

static void scan_test(StrBuf *c, const DfaForm *f, int head)
{
    dfa_scan_of(f->cx, f->d, head)->emit_test(c, f, head);
}

static void emit_scan_edge(StrBuf *c, const DfaForm *f, int head)
{
    const DState *st = &f->d->st[head];
    /* [OPT-5] PERIOD 1 IS ASSERTED, NOT ASSUMED (manager ruling R3). This
     * emitter writes ONE class test per iteration, which is the period-1
     * body; a period-k edge's body is a different axis-I object and would
     * need a class SEQUENCE this `DState` does not carry. A loud internal
     * error is this file's standing preference over emitting a correct
     * matcher with the wrong loop in it. */
    if (st->scan_period != 1)
        ctx_fail(f->cx, 0, "internal error: scan edge with period %d "
                 "(only period 1 is built)", st->scan_period);
    const char *ind = f->dir->bind;
    int span = st->scan_span, nx = st->scan_next;
    int acc  = st->up[UPC_PLAIN].accept != 0;
    int facc = (nx < 0) ? 0 : (f->d->st[nx].up[UPC_PLAIN].accept != 0);

    /* THE COMMENT IS FOUR LINES AND WAS SEVEN. It is emitted once per edge
     * per machine, i.e. up to twelve times per artifact, and MEASURED at ~900
     * bytes of source on `[a-z]*` — an artifact this transform removes no
     * table from. The two facts a reader cannot get anywhere else are kept:
     * what the loop replaces, and why the table cell above says "dead". */
    if (span < 0)
        sb_printf(c, "%s// [OPT-5] SCAN EDGE: every state a run of class %d\n"
                     "%s// would pass IS this state, so count them here rather\n"
                     "%s// than stepping the table once per byte.\n",
                  ind, st->scan_cls, ind, ind);
    else
        sb_printf(c, "%s// [OPT-5] SCAN EDGE: the states between here and state\n"
                     "%s// %d differ only in how many class-%d bytes have been\n"
                     "%s// counted, so they are ONE loop carrying only the cursor.\n"
                     "%s// The class's cell above reads \"dead\" because of this.\n",
                  ind, ind, nx, st->scan_cls, ind, ind);
    /* THE FIRST ITERATION IS PEELED INTO THE GUARD, and it is a MEASURED
     * change rather than a stylistic one. This block sits on the loop's
     * generic path, so it is entered once per iteration whether or not there
     * is a run to count — and the bench's `t-digits-016k` cell is exactly
     * that case at its worst: `[a-z]{0,n}` is nullable, so under the find-all
     * regime the driver issues one `rx_search` per subject byte and NOT ONE
     * of them scans a single byte. MEASURED with the run entered
     * unconditionally: 3.69 -> 5.23 ns/call, a 1.43x regression on a cell
     * that does no scanning at all, from the counter initialiser, the
     * `scan_run_length == span` test and the accept store all executing on a
     * run of length zero. Folding the class test into the guard leaves the
     * empty-run path at a state compare, a bound compare and the class test
     * the loop's own first iteration would have done anyway. */
    sb_printf(c, "%sif (%s == %d && %s && ", ind, f->dir->statev,
              f->repr->cell_of(head, f->d), f->dir->scan_more);
    scan_test(c, f, head);
    sb_puts(c, ") {\n");

    if (span < 0) {
        /* UNBOUNDED (`*` / `+`): no counter, and the state does not move —
         * the run's every position IS this state. */
        sb_printf(c, "%s    %s;\n", ind, f->dir->advance);
        sb_printf(c, "%s    while (%s && ", ind, f->dir->scan_more);
        scan_test(c, f, head);
        sb_printf(c, ") %s;\n", f->dir->advance);
        if (acc)
            sb_printf(c, "%s    %s = %s;   // every position the run passed accepts\n",
                      ind, f->dir->recv, f->dir->posv);
        sb_printf(c, "%s}\n", ind);
        return;
    }

    sb_printf(c, "%s    unsigned long scan_run_length = 1;\n", ind);
    sb_printf(c, "%s    %s;\n", ind, f->dir->advance);
    sb_printf(c, "%s    while (%s && scan_run_length < %dUL\n"
                 "%s           && ",
              ind, f->dir->scan_more, span, ind);
    scan_test(c, f, head);
    sb_printf(c, ") { %s; scan_run_length++; }\n", f->dir->advance);
    sb_printf(c, "%s    if (scan_run_length == %dUL) {\n", ind, span);
    /* THE BOUND WAS REACHED, so the position now holds the FALL-THROUGH
     * state. Its accept bit is recorded from its own bit; the run's bit
     * applies to the position one step behind, which is the last one a chain
     * state occupied. Emitting the run's line only when the fall-through does
     * not already cover it keeps the common `{0,n}` shape (both bits 1) at
     * one line. */
    if (acc && !facc)
        sb_printf(c, "%s        %s = %s;\n", ind, f->dir->recv, f->dir->scan_back);
    sb_printf(c, "%s        %s = %d;\n", ind, f->dir->statev,
              nx < 0 ? f->repr->dead_cell : f->repr->cell_of(nx, f->d));
    if (facc)
        sb_printf(c, "%s        %s = %s;\n", ind, f->dir->recv, f->dir->posv);
    sb_printf(c, "%s    }", ind);
    if (acc) {
        sb_printf(c, " else {\n");
        sb_printf(c, "%s        %s = %s;   // the run stopped inside the edge\n",
                  ind, f->dir->recv, f->dir->posv);
        sb_printf(c, "%s    }\n", ind);
    } else {
        sb_puts(c, "\n");
    }
    sb_printf(c, "%s}\n", ind);
}

/* ---- THE DERIVATION: one machine's whole form, selected once ------------ */

static void dfa_form_derive(Ctx *cx, const Dfa *d, const UnanchStart *us,
                            const DfaDir *dir, DfaForm *f)
{
    DfaSel s = { cx, d, us, !dir->reverse, -1 };
    unsigned flags = cx->opt->flags;

    memset(f, 0, sizeof *f);
    f->cx      = cx;
    f->d       = d;
    f->p       = cx->opt->prefix;
    f->dir     = dir;
    f->repr    = DFA_SELECT(DfaRepr, dfa_reprs, &s, flags);
    f->view    = DFA_SELECT(DfaView, dfa_views, &s, flags);
    f->seed    = DFA_SELECT(DfaSeed, dfa_seeds, &s, flags);
    f->acc     = DFA_SELECT(DfaAcc,  dfa_accs,  &s, flags);
    /* The prefilter is the FORWARD scan's, and that is a clause in each
     * candidate's `applies` rather than a branch here: the reverse machine
     * walks a range the forward scan already proved contains a match, so
     * every real form declines and the list's total fallback `none` — a real
     * object with a NULL emitter — is what it selects. */
    f->pf      = DFA_SELECT(DfaPf, dfa_pfs, &s, flags);
    f->views   = us->views;
    f->viewsel = us->viewsel;
    f->src     = us->viewsel ? dir->viewv : dir->statev;
    f->cand    = us->cand;
    f->ofsk    = &us->ofsk;
    /* The SEARCH scan never skips out of its own start state — the prefilter
     * owns that position. The reverse machine and [ENG-ABS]'s anchored
     * MATCH-HERE machine have no prefilter, so nothing owns theirs. */
    f->nskip   = pick_skip_states(d, dir->prefilter_owns_start ? d->s0 : -1,
                                  f->skip);
    /* [OPT-5] and the scan edges, which are a READ rather than a selection:
     * src/opt/scanedge.c annotated the machine, and a second choice here is
     * exactly the two-derivations-of-one-fact this file keeps a rule against.
     * `pick_skip_states` above already declines a state carrying one, so the
     * two lists are disjoint by construction and the emitted `if` chains
     * cannot both fire at one state. */
    for (int i = 0; i < d->n && f->nscan < PCREC_MAX_SCAN_EDGES; i++)
        if (dfa_edge_taken(dfa_edge_of(cx, d, i))) f->scan[f->nscan++] = i;
    /* [OPT-EDGE] STEP 1 — THE TWO LAYOUT FACTS THE LOOP RESTS ON ARE CHECKED
     * HERE RATHER THAN ASSUMED, and the check is worth having precisely
     * because it CANNOT share a source with what it checks: both facts are
     * produced by `src/opt/scanedge.c` and read by `emit_scan_loop`, and this
     * is the emitter reading back what the pass claims to have done.
     *
     *  (a) THE HEADS ARE THE MACHINE'S TOP ROWS, contiguously and in this
     *      order, which is what makes `is_stop`'s single unsigned compare
     *      test "dead or a head" and nothing else. A head left in the middle
     *      of the row space would make the compare admit ordinary states —
     *      a WRONG ANSWER (the edge path would run at a state with no edge,
     *      fall through the whole `if` chain and rejoin, skipping the stay
     *      skips) rather than a slow one.
     *  (b) NO STATE CARRIES BOTH A STAY SKIP AND A SCAN EDGE, which is what
     *      licenses the edge path NOT replaying the skips. `pick_skip_states`
     *      declines a state carrying an edge, so this is that decline read
     *      back from the other side. */
    for (int k = 0; k < f->nscan; k++)
        if (f->scan[k] != d->n - f->nscan + k)
            ctx_fail(cx, 0, "internal error: scan-edge head %d sits at row %d, "
                     "not at %d — the sentinel range must be the top %d rows",
                     k, f->scan[k], d->n - f->nscan + k, f->nscan);
    for (int k = 0; k < f->nskip; k++)
        for (int j = 0; j < f->nscan; j++)
            if (f->skip[k] == f->scan[j])
                ctx_fail(cx, 0, "internal error: state %d carries both a stay "
                         "skip and a scan edge", f->skip[k]);
    /* [CC-DIFF] (b) THE FOLDS, and this is the ONLY place they are computed.
     * After the repr and acc selections above, because the transition cell's
     * VALUE depends on the representation (pre-multiplied or indexed, and
     * which sentinel means dead) and the wide accept table exists only under
     * `acc->wide_table`. */
    f->tr_fold  = fold_tr(d, f->repr);
    f->acc_fold = fold_acc(d);
}

/* ---- THE TABLES, one path called twice ---------------------------------- */

static void emit_machine_tables(StrBuf *c, const DfaForm *f)
{
    const char *p = f->p, *m = f->dir->c.name;
    char tag[PCREC_MAX_EMIT_NAME_LEN];

    /* [M6-READ] The tables are the artifact's data structures, and each gets
     * a block comment: what it is, how it is indexed, what a cell means, and
     * — where the cells are STATES — a legend naming them. */
    sb_puts(c, f->dir->tbl_hdr);
    emit_class_legend(c, f->d);
    sb_puts(c, "     */\n");
    snprintf(tag, sizeof tag, "%s_byte_class", m);
    emit_u8_table(c, p, tag, f->d->clsmap, 256);

    /* [CC-DIFF] (b) A FOLDED TABLE IS NOT EMITTED AT ALL, and its comment and
     * state legend go with it: the legend names the states a cell could hold,
     * and with no cells left it would document an array that is not there.
     * The fold's own one-line note lives on the accessor, which is where a
     * reader of the emitted C meets the constant. */
    if (!f->tr_fold.folded) {
        f->repr->emit_tr_comment(c, f);
        emit_state_legend(c, f->d, f->dir->reverse);
        sb_puts(c, "     */\n");
        snprintf(tag, sizeof tag, "%s_next_state", m);
        emit_tr_table(c, p, tag, f->d, f->repr);
    }

    if (!f->acc_fold.folded) {
        f->repr->emit_acc_comment(c, f);
        snprintf(tag, sizeof tag, "%s_is_accepting", m);
        emit_acc_table(c, p, tag, f->d, f->repr);
    }

    if (f->acc->wide_table) {
        snprintf(tag, sizeof tag, "%s_is_accepting_by_class", m);
        emit_acc_cls_table(c, p, tag, f->d);
    }
    if (f->seed->table) {
        snprintf(tag, sizeof tag, "%s_seed_state", m);
        emit_seed_table(c, p, tag, f->d, f->d->s1u, f->repr);
    }
    if (f->viewsel) {
        /* The two view tables exist independently of which SELECTOR the
         * machine took: `end+eol` needs both, `eol`/`end` one each. The
         * object's name is the authority on which. */
        if (strcmp(f->view->c.name, "end")) {
            snprintf(tag, sizeof tag, "%s_eol_view", m);
            emit_eol_table(c, p, tag, f->d, f->repr);
        }
        if (strcmp(f->view->c.name, "eol")) {
            snprintf(tag, sizeof tag, "%s_end_view", m);
            emit_end_table(c, p, tag, f->d, f->repr);
        }
    }
    if (f->pf->emit_tables) f->pf->emit_tables(c, f);
    snprintf(tag, sizeof tag, "%s_stay", m);
    for (int k = 0; k < f->nskip; k++)
        emit_stay_table(c, p, tag, f->skip[k], f->d);
    /* [OPT-5] and whatever table each edge's own BODY OBJECT owns — the
     * object is asked here and at the emitted test, so a table can never be
     * emitted for a body that compares against immediates, nor omitted for
     * one that reads a membership table. A body added to `dfa_scans` needs
     * no line here. */
    for (int k = 0; k < f->nscan; k++) {
        const DfaScan *sc = dfa_scan_of(f->cx, f->d, f->scan[k]);
        if (sc->emit_tables) sc->emit_tables(c, f, f->scan[k]);
    }
}

/* ---- THE SCAN LOOP, emitted ONCE and called twice ----------------------- */

/* [OPT-EDGE] STEP 1 — IS THE MACHINE'S START STATE ITSELF A SCAN-EDGE HEAD?
 *
 * TWO readers and they must not be able to disagree, which is why this is a
 * predicate and not a flag computed twice. (1) The candidate-start prefilter
 * fires at `s0` and NOWHERE ELSE (`pf_open` writes its guard), so when `s0`
 * is a head the prefilter belongs on the EDGE path and can never fire on the
 * generic one — it MOVES rather than being replayed, and the generic path
 * keeps no dead compare. (2) The loop's entry has to send a start state that
 * is already a head into the edge path, and by precondition (8) the only head
 * any seed can name is `s0` itself. */
static bool dfa_start_is_scan_head(const Dfa *d)
{
    return d->s0 >= 0 && d->s0 < d->n && d->st[d->s0].scan_span != 0;
}

/* The edge path's two labels. They are per MACHINE, not per artifact: the
 * forward and reverse loops are emitted into ONE function and would collide
 * on a shared name, and `dir->c.name` is the same string the tables and the
 * accessors are already named after. */
static void scan_label(char *buf, size_t n, const DfaForm *f, const char *tag)
{ snprintf(buf, n, "%s_%s_scan_%s", f->p, f->dir->c.name, tag); }

static void emit_scan_loop(StrBuf *c, const DfaForm *f)
{
    const char *ind = f->dir->ind;
    char lv[PCREC_MAX_EMIT_NAME_LEN + 24], le[PCREC_MAX_EMIT_NAME_LEN + 24];
    bool edges = f->nscan > 0;
    bool s0head = edges && dfa_start_is_scan_head(f->d);
    scan_label(lv, sizeof lv, f, "views");
    scan_label(le, sizeof le, f, "edge");

    f->seed->emit_init(c, f);
    /* THE ONE ENTRY, and it costs at most one compare PER SEARCH rather than
     * per byte. `emit_init` is the only writer of the state variable outside
     * the loop, and a start state that is already a head must reach the edge
     * body without the generic path's `if` chain — which no longer exists.
     * Under the `constant` seed the state IS `cell_of(s0)`, so the test folds
     * away entirely and the jump is unconditional; under the `seeded` form
     * the value is a runtime table read whose only head-valued outcome is
     * `cell_of(s0)` (precondition (8) refuses every other seed target as a
     * head), so an equality against that ONE cell is exact. */
    if (s0head) {
        if (f->seed->table)
            sb_printf(c, "%sif (%s == %d) goto %s;\n", ind, f->dir->statev,
                      f->repr->cell_of(f->d->s0, f->d), le);
        else
            sb_printf(c, "%sgoto %s;   // the start state carries a scan edge\n",
                      ind, le);
    }
    sb_printf(c, "%sfor (;;) {\n", ind);
    /* THE EVALUATION ORDER IS AN AXIS, not a tidiness question. Under a view,
     * scan avoidance must run BEFORE the accept evaluation, so that
     * evaluation sees the position the loop is really at: a skip bounded at
     * n-1 can LAND on n-1, and evaluating first would consume that byte
     * without ever taking its view (53 divergences, D11).
     *
     * Without a view the order is a free choice SEMANTICALLY — every position
     * a skip passes has the same state and so the same accept bit — but NOT a
     * free choice in speed. Hoisting the prefilter above the accept check
     * costs 43% on `[01]*1[01]{8}` (158.4 -> 90.8 MB/s, 0 skip states, tight
     * spreads). That asymmetry is the whole reason axis E has a
     * `scalar-plain` object distinct from `scalar-viewed`; do not "simplify"
     * the two into one. */
    if (f->acc->emit_top) f->acc->emit_top(c, f);
    /* [OPT-EDGE] THE PREFILTER MOVES RATHER THAN BEING REPLAYED. It fires at
     * `s0` and nowhere else, and where `s0` is a scan-edge head the generic
     * path never HOLDS `s0` — the state variable holds a head only on the
     * edge path. Emitting it in both places would leave a compare on the
     * generic path that can never be true; emitting it in neither would drop
     * it. So it is emitted exactly once, on the path that can reach it. */
    if (f->pf->emit && !s0head) f->pf->emit(c, f);
    {
        const char *kw = f->pf->emit && !s0head ? "else if" : "if";
        for (int k = 0; k < f->nskip; k++) {
            f->dir->emit_skip(c, f, f->skip[k], kw);
            kw = "else if";
        }
    }
    if (edges) sb_printf(c, "%s  %s:\n", ind, lv);
    if (f->view->emit) f->view->emit(c, f);
    if (f->acc->emit_after_view) f->acc->emit_after_view(c, f);
    f->acc->emit_tail(c, f);
    if (!edges) {
        sb_printf(c, "%s    if (%s_%s_is_dead(%s)) break;   // dead: no match can continue\n",
                  ind, f->p, f->dir->c.name, f->dir->statev);
        sb_printf(c, "%s}\n", ind);
        return;
    }
    /* [OPT-EDGE] STEP 1 — THE SHARED SENTINEL, and this is the whole row.
     *
     * The loop ALREADY paid one state test per iteration here. `is_stop`
     * widens it to "dead OR a scan-edge head" for free (the heads are the top
     * rows and the dead value is above them, so it is the same single
     * compare), and the generic path leaves through the same `continue` the
     * dead test's fall-through was. What used to be `nscan` compares on that
     * path — one `if (state == HEAD && ...)` per edge, evaluated at every
     * state whether or not any edge could fire — is now reached ONLY from
     * here and only when the state really is a head.
     *
     * THE EDGE BLOCK'S OWN TEXT IS UNCHANGED, deliberately: it is still the
     * sequence of independent `if`s in ascending state order, so precondition
     * (7)'s cascade (a chain whose fall-through is another chain's head fires
     * both in one pass) is the same mechanism it always was, and the diff at
     * this landing is a REACHABILITY change rather than a rewrite of the
     * bodies. Running the chain only where the state is a head is exactly
     * what running it everywhere did: at any other state no `if` fires.
     *
     * IT REJOINS AT THE VIEW SELECT, which is where the old placement left
     * off — the edges came after everything that can advance the position and
     * before everything that cannot, and both halves of that still hold
     * (src/opt/scanedge.c's header carries the argument for both paths). */
    sb_printf(c, "%s    if (!%s_%s_is_stop(%s)) continue;   // the generic path\n",
              ind, f->p, f->dir->c.name, f->dir->statev);
    sb_printf(c, "%s    if (%s_%s_is_dead(%s)) break;   // dead: no match can continue\n",
              ind, f->p, f->dir->c.name, f->dir->statev);
    /* THE LABEL IS EMITTED ONLY WHERE SOMETHING JUMPS TO IT, which is the
     * loop's entry and nothing else — the stop test reaches this block by
     * FALLING THROUGH. Emitting it unconditionally is a `-Wunused-label`
     * error in every artifact whose start state is not a head, and generated
     * C is compiled `-Wall -Wextra -Werror` by the harness and by callers.
     * The alternative idiom in this file, `__attribute__((unused))` on the
     * label (`<p>_dead`'s), would say "nothing may jump here" of a label that
     * IS jumped to on the other half of the population. */
    if (s0head) sb_printf(c, "%s  %s:\n", ind, le);
    /* The head's own accept probe. It is the one loop-top statement the edge
     * path genuinely REPLAYS: an edge whose class test fails advances nothing
     * and changes nothing, so without this a head's accepting position would
     * go unrecorded. The stay skips are NOT replayed — `pick_skip_states`
     * declines every state carrying an edge, so no skip can fire at a head —
     * and the prefilter was MOVED here rather than copied where `s0` is one. */
    if (f->acc->emit_top) f->acc->emit_top(c, f);
    if (f->pf->emit && s0head) f->pf->emit(c, f);
    for (int k = 0; k < f->nscan; k++) emit_scan_edge(c, f, f->scan[k]);
    sb_printf(c, "%s    goto %s;\n", ind, lv);
    sb_printf(c, "%s}\n", ind);
}

/* ---- ENG_UNANCH: the assembly ------------------------------------------- */

static void emit_unanchored(Ctx *cx, const char *fn, const char *storage)
{
    Job *job = cx->job;
    StrBuf *c = &job->csb;

    /* [DD-13] THE START ANALYSIS IS `unanch_start`'s, not this function's:
     * the view flags, the candidate set and the prefilter verdict are all
     * read a SECOND time by the artifact's `<PREFIX>_DFA_PREFILTER` stamp,
     * and that function's header states why they may not be derived twice. */
    UnanchStart us;
    unanch_start(cx, &us);

    /* [DD-13] THE ONE EMPTY-ENGINE EXIT, and it is taken BEFORE any token
     * block is emitted so an artifact that matches nothing grows nothing. */
    if (us.empty) {
        emit_search_head(cx, c, fn, storage);
        sb_puts(c, "    (void)subject; (void)subject_length; (void)search_from; (void)capture_spans;\n"
                   "    return 0;\n}\n");
        return;
    }

    /* [OPT-5 STEP 2] AXIS J, and this is its ONE dispatch. The SAME
     * `dfa_search_start_of` call `<PREFIX>_DFA_START`, `rx_info.search_form`
     * and the two stamp folds read, so no reader can name a form this
     * function did not write — `unanch_start`'s own header is the cautionary
     * tale ("M2.7 forked a second copy, and the fork is exactly how the
     * prefilter and skip loops went missing from the `$` path for a whole
     * milestone"). */
    bool pinned = dfa_search_is_pinned(cx);

    DfaForm fwd, rev;
    dfa_form_derive(cx, &job->dfa,  &us, &dfa_dir_forward, &fwd);
    /* THE REVERSE MACHINE'S FORM IS NOT EVEN DERIVED under `pinned`, which is
     * a deliberate step past "derived and not emitted": nothing downstream may
     * read a form for a machine whose text is absent, and leaving `rev`
     * uninitialised is how the compiler enforces that rather than a comment.
     * The reverse machine is still BUILT — skipping the build is a separate
     * compiler-CPU optimization with its own trigger (design note §8 Q5). */
    if (!pinned) dfa_form_derive(cx, &job->rdfa, &us, &dfa_dir_reverse, &rev);
    else         start_pinned_assert_routing(cx, &job->dfa, job->dfa.s0);

    /* LAYER 2, at file scope and above the body: the accessor blocks — one
     * per machine this artifact actually contains — and, [OPT-K], the forward
     * prefilter's own block where its form has one. Same place, same reason:
     * the VM hybrid inlines this emitter's output, so a block emitted here is
     * a block the hybrid gets. */
    fwd.repr->emit_token(c, &fwd);
    if (!pinned) rev.repr->emit_token(c, &rev);
    if (fwd.pf->emit_block) fwd.pf->emit_block(c, &fwd);

    emit_search_head(cx, c, fn, storage);
    emit_machine_tables(c, &fwd);
    if (!pinned) emit_machine_tables(c, &rev);

    sb_puts(c, "    // ---- FORWARD SCAN: where does a match end? ----------------\n"
               "    // One byte per iteration. The loop keeps the LAST accepting\n"
               "    // position rather than stopping at the first, so the longest\n"
               "    // match wins.\n"
               "    size_t scan_position = search_from;\n"
               "    size_t last_accept_position = (size_t)-1;\n");
    emit_scan_loop(c, &fwd);
    if (pinned) {
        /* THE GATE IS LOAD-BEARING AND THE EMITTED COMMENT SAYS SO, which is
         * the point of writing it at all: a reader of a coverage report finds
         * this branch never taken on this corpus and must not conclude it is
         * dead. It is the correct answer on a live input — see below — and
         * "presenting a redundant condition and a load-bearing one as the
         * same claim is how someone eventually simplifies away the wrong
         * half" (this file, about a DIFFERENT gate). */
        sb_puts(c,
            "    // LOAD-BEARING, not belt-and-braces: a search at\n"
            "    // search_from > 0 on a seeded machine can begin in a state\n"
            "    // with no live closure. It records no accept, and \"no match\n"
            "    // begins here\" is the correct answer. Deleting this line\n"
            "    // would report an empty match where there is none.\n"
            "    if (last_accept_position == (size_t)-1) return 0;\n"
            "    // ---- THE MATCH BEGAN AT search_from ----------------------\n"
            "    // [OPT-5 STEP 2] No reverse pass, and no reverse machine in\n"
            "    // this artifact at all. The forward machine's start state\n"
            "    // accepts unconditionally -- at every position, under every\n"
            "    // position view, in every class context -- so D3's\n"
            "    // accept-pruning cut the start-anywhere self-loop out of\n"
            "    // every accepting closure before the first byte was read.\n"
            "    // No later start is ever spawned, so every accept recorded\n"
            "    // above belongs to a thread that began at search_from, and\n"
            "    // a backwards scan would walk back to exactly that\n"
            "    // position. The offset is ABSOLUTE into subject, never\n"
            "    // relative to search_from.\n"
            "    if (capture_spans) { capture_spans[0][0] = (ptrdiff_t)search_from; capture_spans[0][1] = (ptrdiff_t)last_accept_position; }\n"
            "    return 1;\n"
            "}\n");
        return;
    }
    sb_puts(c, "    if (last_accept_position == (size_t)-1) return 0;\n"
               "    {\n"
               "        size_t match_end_position = last_accept_position;\n"
               "        size_t match_start_position = (size_t)-1;\n"
               "        size_t rewind_position = match_end_position;\n");
    emit_scan_loop(c, &rev);
    sb_puts(c, "        if (match_start_position == (size_t)-1) return 0;\n"
               "        if (capture_spans) { capture_spans[0][0] = (ptrdiff_t)match_start_position; capture_spans[0][1] = (ptrdiff_t)match_end_position; }\n"
               "        return 1;\n"
               "    }\n"
               "}\n");
}

/* ---- [ENG-ABS]: THE ANCHORED MATCH-HERE ENTRIES ------------------------- */

/* THE ANCHORED MACHINE'S START ANALYSIS, and the point is how little of one
 * it is (docs/design/anchored_match_unwrapped.md §5.3).
 *
 * `dfa_form_derive` reads an `UnanchStart` for three things: the prefilter
 * verdict, the candidate set, and the position-view flags. The anchored
 * machine HAS no start analysis — it does not search, its start is the
 * caller's `ctx->pos` — so the value it is derived from is built here rather
 * than borrowed:
 *
 *   - `kind` is `DFA_PF_NONE`, `cand` is empty and `ofsk.nsel` is 0,
 *     UNCONDITIONALLY. That is the whole of why axis B selects its total
 *     fallback for this machine, with no branch anywhere and no `applies`
 *     clause that knows this machine exists: every real prefilter candidate
 *     requires `kind != DFA_PF_NONE` or `ofsk.nsel > 0`. A candidate-start
 *     skip CHOOSES WHERE THE SCAN BEGINS, which is sound for a search and
 *     wrong for a match-here.
 *   - the view flags are recomputed from THIS machine alone, where the search
 *     pair shares the artifact-level OR of its two machines. Strictly the more
 *     accurate derivation, and structurally incapable of moving an existing
 *     artifact's bytes because it is a different object: nothing here is
 *     written back into the caller's `UnanchStart`.
 *
 * Taking the caller's `us` as the BASE (rather than zeroing) keeps this
 * function honest about what it does and does not override — a field added to
 * `UnanchStart` tomorrow arrives here with the search's value rather than with
 * a silent zero. */
static void anch_start(const Dfa *ad, const UnanchStart *us, UnanchStart *o)
{
    *o = *us;
    o->kind = DFA_PF_NONE;
    memset(&o->cand, 0, sizeof o->cand);
    memset(&o->ofsk, 0, sizeof o->ofsk);
    o->eol     = dfa_has_eolvar(ad);
    o->endv    = dfa_has_endvar(ad);
    o->viewsel = o->eol || o->endv;
    o->views   = o->viewsel || ad->clsctx;
    o->empty   = false;   /* the caller's candidate already excluded it */
}

/* THE MATCH-HERE BODY. `<prefix>_match` stops being a wrapper around
 * `<prefix>_search` and becomes a scan of its own — the artifact's THIRD
 * machine, run forward from `ctx->pos`, with no reverse pass and no
 * candidate skip. The identity argument (this reports the same length the
 * search-and-filter form reports, on every input) is
 * docs/design/anchored_match_unwrapped.md §3; the four-line summary is:
 *
 *   1. The wrapped forward machine's state is THIS machine's state followed
 *      by the threads of later starts, because the unanchored wrap's
 *      self-loop is the LOWEST-priority branch and subset construction
 *      preserves priority order.
 *   2. D3's accept-pruning drops everything below an accepting thread, so the
 *      instant a `ctx->pos` thread accepts, every later start is gone and the
 *      two machines coincide for the rest of the scan.
 *   3. Hence if this machine accepts anywhere, its LAST accept is the search's
 *      last accept, and the reverse pass would report `ctx->pos` as the start
 *      — the filter passes and both forms report the same length.
 *   4. And if it never accepts, no accepting path from `ctx->pos` exists at
 *      all (it could only have been pruned by an accept of its own), so the
 *      reverse pass reports a later start and both forms report -1.
 *
 * THE LOCAL BINDINGS ARE THE MECHANISM, not tidiness: `subject`,
 * `subject_length` and `search_from` are exactly the names `dfa_dir_anchored`
 * spells its bound, its seed byte and its guard in, so mechanism 4's start
 * dispatch here is the SAME emitted line as the forward scan's, reading the
 * SAME byte (`subject[search_from - 1]`, which for this entry is
 * `subject[ctx->pos - 1]`). */
static void emit_anchored_match_def(StrBuf *c, const DfaForm *f,
                                    const char *matchfn)
{
    sb_printf(c,
        "/* [ENG-ABS] The anchored match-here entry, spec S3.2: a match at\n"
        " * exactly ctx->pos, or -1. It runs the artifact's THIRD machine --\n"
        " * the forward tables WITHOUT the start-anywhere self-loop -- from\n"
        " * ctx->pos, so there is no later start to reject and no backwards\n"
        " * pass to find a start with. A probe that fails stops at the first\n"
        " * byte that cannot continue a match beginning here.\n"
        " *\n"
        " * D49: the give-up codes PROPAGATE rather than collapsing to -1.\n"
        " * Unreachable on this engine -- a DFA artifact has no counter to\n"
        " * exhaust -- and this body cannot produce one at all, which is why\n"
        " * (unlike the search-and-filter form) it has no code to forward. */\n"
        "ptrdiff_t %s(const rx_ctx *ctx)\n"
        "{\n"
        "    const unsigned char *subject = ctx->subject;\n"
        "    size_t subject_length = ctx->len;\n"
        "    size_t search_from = ctx->pos;\n",
        matchfn);
    emit_machine_tables(c, f);
    sb_puts(c, "    // ---- ANCHORED SCAN: where does the match that begins\n"
               "    // at ctx->pos end? Same LAST-accept rule as the forward\n"
               "    // scan, so the longest match wins; no reverse pass,\n"
               "    // because the start is the caller's.\n"
               "    size_t scan_position = search_from;\n"
               "    size_t last_accept_position = (size_t)-1;\n");
    emit_scan_loop(c, f);
    sb_puts(c, "    if (last_accept_position == (size_t)-1) return -1;\n"
               "    return (ptrdiff_t)(last_accept_position - search_from);\n"
               "}\n");
}

/* The capture-delivering sibling. It delegates to `<prefix>_match` rather than
 * re-emitting the scan — one machine, one loop, one place a change lands.
 *
 * IT WRITES THE DEAD GROUPS ITSELF, and that is not optional. On the
 * search-and-filter form those come from `emit_search_head`, which fills
 * slots 1..NCAPS-1 with PCREC_UNSET at entry to `<prefix>_search` (wave G's
 * dead-capture elision: a DFA artifact can promise groups it can never write,
 * because PCRE2 counts them and reports them unset). This form never calls
 * `<prefix>_search`, so the fill has to happen here or those slots would come
 * back as whatever the caller's array held. `RX_NCAPS` is 1 on almost every
 * DFA artifact and the loop then emits nothing at run time.
 *
 * `caps_out[0] == [ctx->pos, ctx->pos + length)` is spec S3.3's own sentence,
 * true here BY CONSTRUCTION rather than by a filter that proved it. On every
 * negative return `caps_out` is UNTOUCHED (A-8's rule) -- every write is
 * below the early return. */
static void emit_anchored_match_caps_def(StrBuf *c, const char *fn,
                                         const char *matchfn, const char *upper)
{
    sb_printf(c,
        "ptrdiff_t %s(const rx_ctx *ctx, ptrdiff_t (*capture_spans_out)[2])\n"
        "{\n"
        "    ptrdiff_t rx_len = %s(ctx);\n"
        "    if (rx_len < 0) return rx_len;\n"
        "    if (capture_spans_out) {\n"
        "        capture_spans_out[0][0] = (ptrdiff_t)ctx->pos;\n"
        "        capture_spans_out[0][1] = (ptrdiff_t)ctx->pos + rx_len;\n"
        "        for (int rx_g = 1; rx_g < %s_NCAPS; rx_g++) {\n"
        "            /* every group this artifact promises is reached only\n"
        "               through a subroutine call or sits under a {0}, so no\n"
        "               match can set it (PCRE2 reports the same) */\n"
        "            capture_spans_out[rx_g][0] = PCREC_UNSET;\n"
        "            capture_spans_out[rx_g][1] = PCREC_UNSET;\n"
        "        }\n"
        "    }\n"
        "    return rx_len;\n"
        "}\n",
        fn, matchfn, upper);
}

/* THE ASSEMBLY, and the only place axis G's two forms are told apart.
 *
 * Layer 2 -- the anchored machine's state-accessor block -- goes at FILE
 * SCOPE above the entry, exactly where `emit_unanchored` puts the search
 * machines' blocks and for the same reason. */
static void emit_anchored_entries(Ctx *cx, StrBuf *c, const GenNames *g)
{
    UnanchStart us, aus;
    DfaForm anch;

    unanch_start(cx, &us);
    anch_start(&cx->job->adfa, &us, &aus);
    dfa_form_derive(cx, &cx->job->adfa, &aus, &dfa_dir_anchored, &anch);

    anch.repr->emit_token(c, &anch);
    emit_anchored_match_def(c, &anch, g->matchfn);
    sb_puts(c, "\n");
    emit_anchored_match_caps_def(c, g->matchcapsfn, g->matchfn, g->upper);
}

/* ---- ENG_ATTEMPT: computed-goto per-start attempt loop ---- */

static void emit_target(StrBuf *c, const char *p, int tgt)
{
    if (tgt < 0) sb_printf(c, "&&%s_dead", p);
    else         sb_printf(c, "&&%s_s%d", p, tgt);
}

static void emit_attempt(Ctx *cx, const char *fn, const char *storage)
{
    Job *job = cx->job;
    Dfa *d = &job->dfa;
    StrBuf *c = &job->csb;
    const char *p = cx->opt->prefix;

    emit_search_head(cx, c, fn, storage);

    /* [DD-13c] THE EMPTY ENGINE, through the SHARED derivation. The condition
     * used to be `d->n == 0` spelled here; it is `dfa_engine_is_empty`'s now,
     * because `<PREFIX>_DFA_SCAN "empty"` is read off the same function and a
     * second copy of the condition is how a stamp and its body drift apart
     * (this file's header, M2.12). Byte-for-byte the same output. */
    if (dfa_engine_is_empty(cx)) {
        /* no live start state: the pattern matches nothing */
        sb_puts(c, "    (void)subject; (void)subject_length; (void)search_from; (void)capture_spans;\n"
                   "    return 0;\n}\n");
        return;
    }

    sb_puts(c, "    /* ---- STATE MACHINE: this engine tries the pattern at one start\n"
               "     * position at a time, and each state is a LABEL rather than a table\n"
               "     * row, so a step is a computed goto.\n"
               "     *\n"
               "     * Byte class of every possible input byte: all 256 values fold into\n"
               "     * the few classes this pattern can tell apart.\n"
               "     *\n");
    emit_class_legend(c, d);
    sb_puts(c, "     */\n");
    emit_u8_table(c, p, "byte_class", d->clsmap, 256);

    /* [M6.2 wave B] this engine's share of §3.6 and §3.8. `acc2` is the
     * class-indexed accept, needed wherever a state's accept depends on the
     * next byte; `seed` is mechanism 4's PER-ATTEMPT start dispatch.
     *
     * ON THIS ENGINE THE SEED IS NOT ONCE PER SEARCH (§3.8.2's own note).
     * ENG_ATTEMPT re-initializes at EVERY attempt — n+1 of them — and only
     * the first begins at `startpos`; the rest begin at `start > startpos`,
     * where the context byte `s[start-1]` is squarely INSIDE the window. So
     * the same dispatch serves both the outside-the-window case this wave
     * exists for and the ordinary interior one, and it composes with the
     * `start == 0` selection this engine already made rather than adding a
     * second. */
    bool acc2 = dfa_has_clsacc(d);
    bool seed = dfa_needs_seed(d);
    /* [M6.2 wave D] TWO questions, not one. `gseed` is "does
     * `start == startpos` differ from `start > startpos` at all"; `gtbl` is
     * "does the `\G` family itself vary with the context byte". Both are
     * needed — `\G\bfoo|bar` has one live interior state for
     * `start > startpos` and three for `start == startpos`, so a single flag
     * emits a constant where a table belongs. */
    bool gseed = dfa_needs_gseed(d);
    /* But `gtbl` is a REFINEMENT of `gseed`, never independent of it, and the
     * `&& gseed` is load-bearing rather than defensive. On a `\G`-free
     * machine `s1g[] == s1u[]` entry for entry, so the loop below answers
     * exactly what `dfa_needs_seed` answers — true on every `\b` and `(?m)`
     * pattern — and without the conjunct those artifacts emit a `gseed[]`
     * table no dispatch ever reads. Found by moving this wave's reference
     * knob to the emitter (see below): with the knob in the analysis both
     * builds emitted the dead table and the byte-identity gate could not see
     * it. */
    bool gtbl = false;
    if (gseed)
        for (int u = UPC_PLAIN + 1; u < UPC_N; u++)
            if (upc_emit_live(u) && d->s1g[u] != d->s1g[UPC_PLAIN]) gtbl = true;
#ifdef PCREC_NO_GSTART
    /* [M6.2 wave D] THE REFERENCE-BUILD KNOB, and its PLACEMENT is the whole
     * point of it. `tests/codegen/run_gstart_identity.sh` builds a compiler
     * with this defined and requires byte-identical output over every
     * `\G`-free corpus pattern; forcing the two flags false HERE makes that
     * build take the pre-wave emitter branches unconditionally, so the
     * reference IS the pre-wave emitter rather than merely an analysis with
     * one fact suppressed.
     *
     * WAVE B's ANALOGOUS KNOB IS PLACED THE OTHER WAY AND THIS WAVE MEASURED
     * WHAT THAT COSTS. `-DPCREC_NO_WORDCTX` pins `has_word` false in
     * `src/ir/dfa.c`, i.e. inside the code a sabotage of that construction
     * edits — and the reference compiler is built from THE SAME (sabotaged)
     * SOURCES. So sabotage S71, which deletes the `if (has_word)` gate on the
     * alphabet refinement, refines in BOTH builds and cancels: measured
     * 2026-08-19, `run_wordctx_identity.sh`'s identity sweep stays
     * 1135/1135 BYTE-IDENTICAL under it, and the script fails only because
     * `has_word` becomes an unused parameter and the reference build emits a
     * warning. That is the project's own recorded check-design failure — a
     * control sharing a source with what it controls — in a new place, and
     * the reason this knob is at the emitter instead. See S71's and S76's
     * annotations; re-placing THOSE two is not this wave's to do.
     *
     * Never defined in a shipped build: under it a `\G` pattern takes the
     * two-way start dispatch, so `\G` can pass only at `start == 0` and
     * compiles to `\A`'s semantics — a WRONG matcher, which is what makes
     * that script's positive control non-vacuous. */
    gseed = false;
    gtbl = false;
#endif
    /* [M6.2 wave C] the class-axis context of a position whose next byte is a
     * newline: the EOL arms below know that byte from their own entry test,
     * so their accept bit is a COMPILE-TIME constant rather than a table read
     * (§3.6.2's composition with the position axis, both indices known). */
    int unl = upc_of_newline(d);
    if (acc2) {
        sb_puts(c, "    /* 1 where a match may end, indexed [state * classes + class]:\n"
                   "     * this machine's accept bit depends on the NEXT byte, so it is a\n"
                   "     * table read rather than a per-state constant. */\n");
        emit_acc_cls_table(c, p, "is_accepting_by_class", d);
    }

    /* [M6-READ] The jump rows are this engine's transition table, one array
     * per state instead of one flat table -- the cells are code ADDRESSES, so
     * a step is an indirect jump rather than a load and a compare. The legend
     * names the states those addresses belong to. */
    sb_printf(c, "    /* Jump targets, one row per state, indexed by byte class.\n"
                 "     * A cell is the label to jump to for that class; %s_dead ends\n"
                 "     * the attempt. %d states, %d classes.\n"
                 "     *\n", p, d->n, d->ncls);
    emit_state_legend(c, d, false);
    sb_puts(c, "     */\n");
    for (int i = 0; i < d->n; i++) {
        sb_printf(c, "    static const void *const %s_targets_%d[%d] = { ",
                  p, i, d->ncls);
        for (int cl = 0; cl < d->ncls; cl++) {
            if (cl) sb_puts(c, ", ");
            emit_target(c, p, d->st[i].tr[cl]);
        }
        sb_puts(c, " };\n");
    }
    if (seed) {
        sb_printf(c, "    static const void *const %s_seed_state[%d] = { ",
                  p, d->ncls);
        for (int cl = 0; cl < d->ncls; cl++) {
            if (cl) sb_puts(c, ", ");
            emit_target(c, p, d->s1u[upc_emit_of_class(d, cl)]);
        }
        sb_puts(c, " };\n");
    }
    /* [M6.2 wave D] `\G`'s own seed table, and it is gated on the `\G` FAMILY
     * varying rather than on `seed`. The two questions are genuinely
     * independent: `\G\bfoo|bar` has one interior state for `start >
     * startpos` (only the `bar` branch survives, and it reads no byte to its
     * left) and three for `start == startpos` (where the `\b` is live). A
     * single `seed` flag would emit a constant where a table is needed. */
    if (gtbl) {
        sb_printf(c, "    static const void *const %s_gstart_seed_state[%d] = { ",
                  p, d->ncls);
        for (int cl = 0; cl < d->ncls; cl++) {
            if (cl) sb_puts(c, ", ");
            emit_target(c, p, d->s1g[upc_emit_of_class(d, cl)]);
        }
        sb_puts(c, " };\n");
    }

    /* [D63] THE CANDIDATE-START PREFILTER, this engine's first instance.
     * Derived by the shared helper; only the LOOP INTEGRATION is here. */
    CandSet cand;
    bool cpre = attempt_cand(d, &cand);

    /* anchored fast path (M2.1): if every interior start state is dead, every
     * branch requires ^, so only start == 0 can ever match.
     * [M6.2 wave B] there is now more than one interior start state, and the
     * fast path needs ALL of them dead — `(?:^|\b)x` has a live one and a
     * dead one. [M6.2 wave C] `(?m)^x` has exactly one live (the newline
     * context), which is what D63's candidate prefilter above is for: the
     * fast path does not apply, and every attempt but the line starts is
     * still provably dead. */
    /* [M6.2 wave D] `start_max` IS A THIRD VALUE NOW, not a wrap toggle
     * (assertions_design.md §4.1, which is DD-4's substantive answer). Read
     * the two interior families together:
     *
     *   s1u dead, s1g dead   every branch needs `^`     -> start_max = 0
     *   s1u dead, s1g LIVE   every branch needs `\G`    -> start_max = startpos
     *   s1u live             something can start later  -> start_max = n
     *
     * The middle row is `\G`'s whole engine cost: ONE attempt, at exactly the
     * position `\G` names, so a `\G`-anchored pattern is O(n) trivially and
     * needs neither a new engine nor `engine_m4.md` §7.3's toggle on
     * `nfa_wrap_unanchored`. ENG_ATTEMPT was already emitting the
     * un-self-looped shape.
     *
     * On a `\G`-free machine `s1g[] == s1u[]` entry for entry, so the middle
     * row is unreachable and the two surviving rows are the pre-wave
     * `anchored ? "0" : "n"` character for character. */
    bool a_bot = dfa_interior_dead(d->s1u);
    bool a_gst = dfa_interior_dead(d->s1g);
#ifdef PCREC_NO_GSTART
    a_gst = a_bot;   /* the reference build's third `start_max` string is
                      * unreachable — see the knob's comment above */
#endif
    bool anchored = a_bot && a_gst;
    sb_printf(c, "    size_t start;\n"
                 "    const size_t start_max = %s;\n",
              anchored ? "0 /* fully ^-anchored */"
                       : a_bot ? "search_from /* fully \\G-anchored */" : "subject_length");
    sb_puts(c, "    for (start = search_from; start <= start_max; start++) {\n");
    if (cpre) {
        /* [D63] LOOP INTEGRATION, ENG_ATTEMPT's shape: an advance BETWEEN
         * attempts, not a skip inside one. It composes with the three-way
         * start dispatch below rather than replacing it — the dispatch still
         * decides WHICH start state an attempt enters; this only skips the
         * starts whose state would be the dead one.
         *
         * `start == 0` is never skipped: it enters `s0`, which this
         * derivation says nothing about (assertions_design.md §3.7.2's
         * "offset 0 or immediately after a newline" is exactly the shape of
         * the two branches here).
         *
         * SOUNDNESS is by construction rather than by argument: a skipped
         * `start` would have jumped straight to the dead label and fallen
         * through `%s_done` with `last == (size_t)-1`, i.e. done nothing at
         * all. This is the one scan-avoidance mechanism in the file that
         * needs no D11 bound, because it skips whole ATTEMPTS rather than
         * positions within a scan, and an attempt records nothing until it
         * runs.
         *
         * THE GUARD READS `s[start - offset]`, IN RANGE BECAUSE `offset >= 1`
         * here: a predecessor-byte candidate set (D63's one new case) and
         * `start > 0` together put that read at `start - 1 <= n - 1`. A
         * future ENG_ATTEMPT caller with `offset == 0` would be reading
         * `s[start]` and needs its own `start < n` bound — which is exactly
         * why the derivation carries `offset` as data instead of the two
         * shapes being two functions.
         *
         * The MEASURED target is the linear non-crossing arm (§3.7.2, R30
         * N3): `(?m)^ERROR` dies in a byte or two per attempt, so the cost is
         * visiting every offset, and this is what removes it. The quadratic
         * crossing arm (§3.7.1) is NOT rescued and D63 accepts that —
         * DD-7's reverse BOT variant is the sequenced fix.
         *
         * [M6.2 wave D] THE LOWER BOUND IS `startpos`, NOT 0, WHENEVER THE
         * MACHINE HAS A `\G` FAMILY — and getting this wrong is a lost match,
         * not a slow one. The derivation reads `s1u[]`, the states an attempt
         * at `start > startpos` enters; the attempt at `start == startpos`
         * enters `s1g[]` instead, which the derivation never looked at. So a
         * pattern with a `(?m)^` branch AND a `\G` branch — `(?m)^a|\Gb`,
         * whose candidate set is the newline definition — would have had its
         * `\G` attempt skipped at any `startpos` not preceded by a newline.
         * `start > startpos` implies `start > 0`, so the bound is a
         * STRENGTHENING of the existing guard rather than a second condition,
         * and every position the skip then passes over is one this
         * derivation's domain covers. Sabotage S82 restores `start > 0`. */
        sb_printf(c, "        if (start > %s && subject[start - %d] != %d) {\n"
                         "            const void *q = memchr(subject + start, %d, "
                         "subject_length - start);\n"
                         "            if (!q) break;\n"
                         "            start = (size_t)"
                         "((const unsigned char *)q - subject) + %d;\n"
                         "        }\n",
                  gseed ? "search_from" : "0",
                  cand.offset, cand.byte, cand.byte, cand.offset);
    }
    sb_puts(c, "        size_t scan_position = start;\n"
               "        size_t last_accept_position = (size_t)-1;\n");

    /* [M6.2 wave D] THE START DISPATCH IS THREE-WAY WHEN `\G` IS PRESENT
     * (assertions_design.md §4.2's table), and the three cases are exactly
     * its three reachable rows:
     *
     *     start == 0          -> s0     (`\A` and `\G` both pass)
     *     start == startpos   -> s1g[]  (`\G` only)
     *     start >  startpos   -> s1u[]  (neither)
     *
     * `start == 0` is tested FIRST and that ordering is load-bearing: it is
     * the row where BOTH hold, and testing `start == startpos` first would
     * route offset 0 into the `\G`-only state and lose every `\A`/`^` branch.
     *
     * The `\G`-free path below is the pre-wave code untouched, three branches
     * and all — the same one-branch-that-reproduces-the-old-string discipline
     * `emit_view_select` is written with, for the same reason. */
    if (gseed) {
        sb_puts(c, "        goto *((start == 0) ? ");
        emit_target(c, p, d->s0);
        sb_puts(c, "\n               : (start == search_from) ? ");
        if (gtbl) sb_printf(c, "%s_gstart_seed_state[%s_byte_class[subject[start - 1]]]", p, p);
        else      emit_target(c, p, d->s1g[UPC_PLAIN]);
        sb_puts(c, "\n               : ");
        if (seed) sb_printf(c, "%s_seed_state[%s_byte_class[subject[start - 1]]]", p, p);
        else      emit_target(c, p, d->s1u[UPC_PLAIN]);
        sb_puts(c, ");\n");
    } else if (seed) {
        sb_puts(c, "        goto *((start == 0) ? ");
        emit_target(c, p, d->s0);
        sb_printf(c, " : %s_seed_state[%s_byte_class[subject[start - 1]]]);\n", p, p);
    } else if (d->s0 == d->s1u[UPC_PLAIN]) {
        sb_puts(c, "        goto ");
        if (d->s0 < 0) sb_printf(c, "*&&%s_dead;\n", p);
        else           sb_printf(c, "*&&%s_s%d;\n", p, d->s0);
    } else {
        sb_puts(c, "        goto *((start == 0) ? ");
        emit_target(c, p, d->s0);
        sb_puts(c, " : ");
        emit_target(c, p, d->s1u[UPC_PLAIN]);
        sb_puts(c, ");\n");
    }

    for (int i = 0; i < d->n; i++) {
        const DState *st = &d->st[i];
        /* labels marked unused: EOL-variant states are entered via their
         * transition tables only, never their own label */
        sb_printf(c, "%s_s%d: __attribute__((unused));\n", p, i);
        /* [M6.2 wave B] Does THIS state's accept depend on the next byte? A
         * per-state question, not a per-artifact one: a `\b` pattern's
         * artifact typically has a handful of such states and keeps the
         * pre-wave text at every other, which is what makes the byte-identity
         * property hold at state granularity rather than at file granularity. */
        bool wsplit = acc2 && state_acc_varies(st);
        if (wsplit) {
            /* THE ORDER FLIPS, and it has to. The pre-wave arms record the
             * accept and THEN test for `pos >= n`, which is sound while the
             * accept bit is a scalar; here the bit at `pos < n` is a function
             * of `s[pos]`, so the end-of-subject case has to be split off
             * first — it is the one position with no next byte, where §3.6.2
             * makes the accept SCALAR. That test is also what makes the
             * `s[pos]` below unreachable at `pos == n`. */
            int endview = st_emit_endvar(st) >= 0 ? st_emit_endvar(st)
                        : st->eolvar >= 0 ? st->eolvar : i;
            sb_puts(c, "        if (scan_position == subject_length) {\n");
            if (d->st[endview].up[UPC_PLAIN].accept)
                sb_puts(c, "            last_accept_position = scan_position;\n");
            sb_printf(c, "            goto %s_done;\n        }\n", p);
            if (st->eolvar >= 0) {
                /* [M6.2 wave C] THE EOL POSITION'S ACCEPT IS CLASS-INDEXED
                 * TOO, and wave B's note here said otherwise. Its reasoning
                 * was right for its own axis and its conclusion is now wrong:
                 * the byte at an EOL position is `\n`, which is indeed not a
                 * word character — so the WORD axis has nothing to add — but
                 * it IS the newline definition, which is precisely what
                 * `(?m)$` reads. `(?m)a(?:$|\Z)` is the shape that needs
                 * both: the `\Z` half makes an EOL view exist, and the
                 * `(?m)$` half makes that view's accept depend on the very
                 * byte the arm's entry test just pinned.
                 *
                 * Pinned, not read: both indices are compile-time facts here
                 * (the view from the position, the class from the arm's own
                 * `s[pos] == newline` test), so this is a constant, not a
                 * table lookup. `unl` is UPC_PLAIN on any machine without a
                 * newline refinement, which is what keeps the pre-wave text
                 * byte-identical. */
                const DState *v = &d->st[st->eolvar];
                sb_puts(c, "        if (scan_position + 1 == subject_length && subject[scan_position] == '\\n') {\n");
                if (v->up[unl].accept) sb_puts(c, "            last_accept_position = scan_position;\n");
                sb_printf(c, "            goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n",
                          p, st->eolvar, p);
                sb_puts(c, "        }\n");
            }
            sb_printf(c, "        {\n"
                         "            unsigned forward_class = %s_byte_class[subject[scan_position]];\n"
                         "            if (%s_is_accepting_by_class[%d + forward_class]) last_accept_position = scan_position;\n"
                         "            scan_position++;\n"
                         "            goto *%s_targets_%d[forward_class];\n"
                         "        }\n",
                      p, p, i * d->ncls, p, i);
        } else if (st_emit_endvar(st) >= 0) {
            /* [M6.2 wave A] THE END VIEW (`\z`), reached on ENG_ATTEMPT only
             * when the pattern also carries a `^`/`\A` — `\Aa\z` is the
             * shape. Three arms in position order, most specific first:
             * `pos == n` takes the END view (and then there is no byte to
             * consume, so it always leaves), `pos + 1 == n && s[pos] == '\n'`
             * takes the EOL view, and everything else is the state itself.
             *
             * A state only reaches this branch when its END view DIFFERS from
             * its EOL view (`endvar >= 0` means exactly that, src/ir/dfa.c) —
             * which is why the `endvar < 0` else-branch below is still the
             * pre-wave text, unchanged, for every state of every pattern that
             * has no `\z`. */
            const DState *endv = &d->st[st_emit_endvar(st)];
            sb_puts(c, "        if (scan_position == subject_length) {\n");
            if (endv->up[UPC_PLAIN].accept)
                sb_puts(c, "            last_accept_position = scan_position;\n");
            sb_printf(c, "            goto %s_done;\n", p);
            sb_puts(c, "        }\n");
            if (st->eolvar >= 0) {
                const DState *v = &d->st[st->eolvar];
                sb_puts(c, "        if (scan_position + 1 == subject_length && subject[scan_position] == '\\n') {\n");
                if (v->up[unl].accept)
                    sb_puts(c, "            last_accept_position = scan_position;\n");
                sb_printf(c, "            goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n",
                          p, st->eolvar, p);
                sb_puts(c, "        }\n");
            }
            if (st->up[UPC_PLAIN].accept)
                sb_puts(c, "        last_accept_position = scan_position;\n");
            /* both arms above returned or consumed, so pos < n here */
            sb_printf(c, "        goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n", p, i, p);
        } else if (st->eolvar >= 0) {
            const DState *v = &d->st[st->eolvar];
            /* at an EOL position ($ passable), use the EOL-view state:
             * its accept is correctly priority-pruned and its table
             * carries the $-gated continuations.
             *
             * [M6.2 wave C] THE TWO EOL POSITIONS CAN CARRY DIFFERENT ACCEPT
             * BITS and the pre-wave text merged them into one arm. They are
             * `pos == n` (no next byte: §3.6.2's SCALAR accept) and
             * `pos + 1 == n && s[pos] == '\n'` (next byte pinned to the
             * newline definition), and until `(?m)$` existed nothing could
             * tell them apart, because the EOL view's accept did not depend
             * on the next byte at all. `(?m)a$` on `"a\n"` is the witness:
             * the view accepts at the newline position and the merged arm
             * would have had to answer for both with one bit.
             *
             * The arms only SPLIT when the two bits differ, so a machine with
             * no newline refinement (`unl == UPC_PLAIN`) emits the pre-wave
             * text character for character. */
            bool a_end = v->up[UPC_PLAIN].accept;
            bool a_nl  = v->up[unl].accept;
            if (a_end == a_nl) {
                sb_puts(c, "        if (scan_position == subject_length || (scan_position + 1 == subject_length && "
                           "subject[scan_position] == '\\n')) {\n");
                if (a_end)
                    sb_puts(c, "            last_accept_position = scan_position;\n");
                sb_printf(c, "            if (scan_position >= subject_length) goto %s_done;\n", p);
                sb_printf(c, "            goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n",
                          p, st->eolvar, p);
                sb_puts(c, "        }\n");
            } else {
                sb_puts(c, "        if (scan_position == subject_length) {\n");
                if (a_end)
                    sb_puts(c, "            last_accept_position = scan_position;\n");
                sb_printf(c, "            goto %s_done;\n        }\n", p);
                sb_puts(c, "        if (scan_position + 1 == subject_length && subject[scan_position] == '\\n') {\n");
                if (a_nl)
                    sb_puts(c, "            last_accept_position = scan_position;\n");
                sb_printf(c, "            goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n",
                          p, st->eolvar, p);
                sb_puts(c, "        }\n");
            }
            if (st->up[UPC_PLAIN].accept)
                sb_puts(c, "        last_accept_position = scan_position;\n");
            /* not an EOL position implies pos < n: consume directly */
            sb_printf(c, "        goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n", p, i, p);
        } else {
            if (st->up[UPC_PLAIN].accept)
                sb_puts(c, "        last_accept_position = scan_position;\n");
            sb_printf(c, "        if (scan_position >= subject_length) goto %s_done;\n", p);
            sb_printf(c, "        goto *%s_targets_%d[%s_byte_class[subject[scan_position++]]];\n", p, i, p);
        }
    }

    sb_printf(c, "%s_dead: __attribute__((unused));\n", p);
    sb_printf(c, "%s_done:\n", p);
    sb_puts(c, "        if (__builtin_expect(last_accept_position != (size_t)-1, 0)) {\n"
               "            if (capture_spans) { capture_spans[0][0] = (ptrdiff_t)start; capture_spans[0][1] = (ptrdiff_t)last_accept_position; }\n"
               "            return 1;\n"
               "        }\n"
               "    }\n"
               "    return 0;\n"
               "}\n");
}

/* ---- [M4.5b] the shared artifact surface ----------------------------------
 *
 * The VM emitter (src/gen/emit_vm.c) produces an artifact with the SAME
 * prologue, the SAME four entry points and — under the hybrid — the SAME DFA
 * engine body as this file's, differing only in what `<prefix>_search` does
 * with them. Everything below that both emitters need is exported through
 * these five functions rather than copied, which is the M2.12 rule ("M2.7
 * forked a second copy, and the fork is exactly how the prefilter and skip
 * loops went missing from the `$` path for a whole milestone") applied to a
 * fork that has not happened yet. */

void pcrec_gen_names(Ctx *cx, GenNames *g)
{
    g->searchfn     = engine_entry_name(cx);
    g->matchfn      = match_entry_name(cx);
    g->matchcapsfn  = match_caps_entry_name(cx);
    g->infoname     = info_entry_name(cx);
    prefix_upper(cx->opt->prefix, g->upper, sizeof g->upper);
}

void pcrec_emit_abi_types(StrBuf *sb) { emit_rx_abi_types(sb); }

void pcrec_emit_c_string_literal(StrBuf *sb, const char *s, size_t len)
{
    emit_c_string_literal(sb, s, len);
}

/* Everything from the pattern comment through the four declarations, in the
 * exact order pcrec_emit_dfa emitted it before this refactor — including the
 * `#include <string.h>` the unanchored engine's memchr prefilter needs, which
 * the VM's hybrid needs for the same reason and its VM-only mode does not. */
/* [M6-READ] THE ORIENTATION BLOCK -- a map of THIS artifact.
 *
 * The plan row's SCOPE RULED block sets what this is and is not: the artifact
 * explains ITSELF. Frank's frame is that a reader coming from a higher-level
 * language loses the larger picture in C's nuts and bolts, and the
 * commentary's job is restoring the altitude C strips away -- saying what a
 * higher-level language would have let the code say itself. So this names the
 * SECTIONS THIS FILE HAS and how one match attempt flows through them. It is
 * not a regex-engine primer, and it must never become one.
 *
 * Everything it says is read off the compiled job, so an artifact without a
 * prefilter does not claim one and a VM artifact describes the VM. A block
 * that described a shape the file does not have would be worse than none. */
static void emit_orientation_block(Ctx *cx, StrBuf *c, const GenNames *g)
{
    Job *job = cx->job;
    bool vm = job->fit.chosen == ENGM_VM;
    bool prefilter = job->fit.prefilter;
    /* [OPT-5 STEP 2] AXIS J, for the map paragraphs below. Asked only where
     * this artifact HAS a DFA scan — on a plain VM artifact `job->dfa` was
     * never built, so the selection would read uninitialised analysis, which
     * is `emit_info_def`'s own reason for guarding its two mirrors. */
    bool pinned = (!vm || prefilter) && dfa_search_is_pinned(cx);
    /* WHICH prefilter shape the forward scan uses is NOT re-derived here. The
     * derivation lives in emit_unanchored, which owns it, and a second copy
     * that agreed today would be a second source of truth about the emitted
     * code -- the shape this project has been bitten by before. This block
     * names the STEP; the prefilter's own emission site describes the form it
     * took, where `use_memchr` is already in hand. */

    sb_puts(c, "/* =====================================================================\n"
               " * HOW THIS MATCHER WORKS -- a map of this file\n"
               " *\n"
               " * This is a complete, self-contained matcher for ONE pattern:\n"
               " *\n *     ");
    /* the pattern itself, rendered safe for a block comment */
    for (const char *q = cx->pat; *q; q++) {
        if (q[0] == '*' && q[1] == '/') sb_puts(c, "*\\/");
        else if (*q == '\n') sb_puts(c, "\\n");
        else sb_putc(c, *q);
    }
    sb_puts(c, "\n *\n"
               " * There is no pattern parser here and nothing to configure. The\n"
               " * pattern was compiled away ahead of time; what is left is the\n"
               " * machinery below and the entry points that drive it.\n"
               " *\n");

    if (!vm) {
        sb_puts(c, " * ONE SEARCH, END TO END:\n *\n"
                   " *   1. FORWARD SCAN. Walk the subject left to right, one byte per\n"
                   " *      step, moving between numbered states by table lookup. Every\n"
                   " *      time the scan lands in an ACCEPTING state, remember the\n"
                   " *      position: a match could end here. This finds where the match\n"
                   " *      ENDS.\n");
        sb_puts(c, " *\n"
                   " *   2. PREFILTER SKIP -- a shortcut that may appear inside step 1.\n"
                   " *      While the scan is still in the start state with nothing\n"
                   " *      found, bytes that cannot begin a match are skipped rather\n"
                   " *      than stepped over. Speed only: it can never change the\n"
                   " *      answer. Its own comment, at the loop below, says which form\n"
                   " *      this artifact uses.\n");
        /* [OPT-5 STEP 2] THE ORIENTATION BLOCK MAY NOT DESCRIBE A PASS THE
         * ARTIFACT DOES NOT CONTAIN, which is the same rule that makes the
         * two stamp folds drop the reverse machine — this paragraph is a
         * READER's map of the file, and a map naming tables that are not
         * there is worse than no map. Read off the SAME `dfa_search_is_pinned`
         * the body was emitted through. */
        if (pinned)
            sb_puts(c, " *\n"
                       " *   3. NO REVERSE SCAN, AND NO REVERSE TABLES IN THIS FILE. For\n"
                       " *      this pattern the forward machine accepts before it reads\n"
                       " *      a byte, so a match exists wherever the search starts and\n"
                       " *      every accept the forward scan records belongs to it. The\n"
                       " *      match therefore BEGINS at the position the caller asked\n"
                       " *      the search to start from, and there is nothing to walk\n"
                       " *      back to. Other patterns' artifacts carry a second set of\n"
                       " *      tables here, built from the same pattern read right to\n"
                       " *      left; this one does not need them.\n *\n");
        else
            sb_puts(c, " *\n"
                       " *   3. REVERSE SCAN. Walk backwards from the end found in step 1,\n"
                       " *      through a SECOND set of tables built from the same pattern\n"
                       " *      read right to left. The furthest-back accepting position is\n"
                       " *      where the match STARTS. The second pass exists because the\n"
                       " *      forward tables record only where a match can END, never where\n"
                       " *      the one that ended there began.\n *\n");
    } else {
        sb_puts(c, " * This pattern reports where its capture groups matched, so the\n"
                   " * matcher is built in two halves that run one after the other:\n *\n");
        if (prefilter && pinned)
            /* [OPT-5 STEP 2] A HYBRID'S INLINED PREFILTER IS THIS EMITTER'S
             * OWN SEARCH BODY, so the elision reaches it and this paragraph
             * must say so — "a pair of scanners" would name a machine the
             * artifact does not carry. */
            sb_puts(c, " *   HALF 1 -- the prefilter. ONE table-driven forward scanner\n"
                       " *     that answers \"is there a match at all, and between which\n"
                       " *     two offsets?\" while ignoring the groups. Its start is the\n"
                       " *     position the search began at -- the machine accepts before\n"
                       " *     it reads a byte -- so it needs no backwards pass and this\n"
                       " *     artifact carries no reverse tables. It never backtracks.\n"
                       " *     What it cannot do is say where the groups fell.\n *\n");
        else if (prefilter)
            sb_puts(c, " *   HALF 1 -- the prefilter. A pair of table-driven scanners,\n"
                       " *     forward then reverse, that answer \"is there a match at all,\n"
                       " *     and between which two offsets?\" while ignoring the groups.\n"
                       " *     It never backtracks. What it cannot do is say where the\n"
                       " *     groups fell.\n *\n");
        sb_puts(c, " *   HALF 2 -- the compiled program. One label per position in the\n"
                   " *     pattern, walked by goto, recording each group's start and end\n"
                   " *     as it passes them. Where the pattern offers a choice it pushes\n"
                   " *     a RESUME FRAME and takes the preferred branch; when a label\n"
                   " *     finds the subject does not match it jumps to the one place\n"
                   " *     that goes backwards, restoring the position and undoing the\n"
                   " *     group writes made since. Running out of frames, trail, steps\n"
                   " *     or work budget returns a distinct \"gave up\" code, which is\n"
                   " *     NOT the same answer as \"no match\".\n *\n");
    }

    /* K38: widened from 96 to the shared emitted-name size for consistency
     * with the emit_vm.c family this constant was introduced for -- content
     * here (prefix + "_next_pos") tops out at 70 bytes at the 60-char
     * prefix maximum and was never observed to truncate, but the DFA
     * emitter's one prefix-carrying fixed buffer should not be sized by a
     * separate hand guess either. */
    char residual[PCREC_MAX_EMIT_NAME_LEN];
    snprintf(residual, sizeof residual, "%s_next_pos", cx->opt->prefix);
    sb_printf(c, " * %s does the work. %s and %s are\n"
                 " * anchored entry points, %s is caller-facing encoding\n"
                 " * residue, and %s describes what this artifact is. Each is\n"
                 " * documented at its definition.\n",
              g->searchfn, g->matchfn, g->matchcapsfn, residual, g->infoname);
    if (!vm || prefilter) {
        /* [OPT-3] The paragraph describes the tables this artifact ACTUALLY
         * carries, read off `dfa_table_name` — the same predicate the loop and
         * the stamp read, never a fourth opinion. The `"indexed"`/`"none"` arm
         * is the pre-[OPT-3] text character for character. */
        const char *form = dfa_table_name(cx);
        sb_puts(c, " *\n"
                   " * READING THE TABLES. Each scanner uses three arrays with the same\n"
                   " * shape: a byte-class table folding all 256 byte values down to the\n"
                   " * few classes this pattern can tell apart; a transition table, one\n");
        if (!strcmp(form, "premultiplied"))
            sb_puts(c, " * row per state and one column per class, whose cell is the state\n"
                       " * to move to ALREADY MULTIPLIED by the column count (so a step is\n"
                       " * one add and one load) or 65535 for \"dead, stop\"; and an\n"
                       " * accepting table marking the states where a match may end,\n"
                       " * indexed by that same multiplied value. Every table below\n"
                       " * carries a legend naming its states or classes.\n");
        else if (!strcmp(form, "mixed"))
            sb_puts(c, " * row per state and one column per class, whose cell is the state\n"
                       " * to move to or a reserved value for \"dead, stop\"; and an\n"
                       " * accepting table marking the states where a match may end. The\n"
                       " * two scanners here use DIFFERENT cell encodings -- each table's\n"
                       " * own comment below says which, and names its dead cell. Every\n"
                       " * table below carries a legend naming its states or classes.\n");
        else
            sb_puts(c, " * row per state and one column per class, whose cell is the state to\n"
                       " * move to or -1 for \"dead, stop\"; and an accepting table marking\n"
                       " * the states where a match may end. Every table below carries a\n"
                       " * legend naming its states or classes.\n");
    }
    sb_puts(c, " * ===================================================================== */\n\n");
}

void pcrec_emit_prologue(Ctx *cx, const GenNames *g, int ncaps,
                         const BufSurface *bs)
{
    StrBuf *c = &cx->job->csb;
    /* [M6.2 wave C] ENG_ATTEMPT joins the list of bodies that can call
     * `memchr`: D63's candidate-start prefilter. The test is `attempt_cand`,
     * the SAME function emit_attempt uses to decide whether to emit the loop
     * — never a restatement of its condition here. */
    bool dfa_body = cx->job->fit.chosen != ENGM_VM || cx->job->fit.prefilter;
    CandSet acand;
    bool need_string_h =
        dfa_body && (cx->job->engine == PCREC_ENG_UNANCH ||
                     (cx->job->engine == PCREC_ENG_ATTEMPT &&
                      attempt_cand(&cx->job->dfa, &acand) && acand.use_memchr));

    if (cx->opt->header_name)
        emit_header(cx, g->searchfn, g->matchfn, g->matchcapsfn, g->infoname,
                    g->upper, ncaps, bs);

    emit_pattern_comment(c, cx->pat);
    emit_feature_comment(c);
    emit_feature_macros(c);
    emit_altcls_macros(c, g->upper, cx->job->altcls_merges, cx->job->altcls_factored);
    if (cx->opt->header_name) {
        sb_printf(c, "#include \"%s\"\n", cx->opt->header_name);
    } else {
        sb_puts(c, "#include <stddef.h>\n#include <stdint.h>\n\n");
        /* file-scope, shared by every engine here; per-engine below */
        emit_rx_abi_types(c);
        sb_putc(c, '\n');
        emit_ncaps_macros(c, g->upper, ncaps);
        emit_buffers_surface(c, g->upper, cx->opt->prefix, bs);
        sb_putc(c, '\n');
        emit_search_decl(c, g->searchfn);
        emit_match_decl(c, g->matchfn);
        emit_match_caps_decl(c, g->matchcapsfn);
        emit_info_decl(c, g->infoname);
        emit_search_in_decl(c, g->searchfn, cx->opt->prefix);
        emit_match_in_decl(c, g->matchfn, cx->opt->prefix);
        emit_match_caps_in_decl(c, g->matchcapsfn, cx->opt->prefix);
        sb_putc(c, '\n');
        emit_residual_decls(cx, c);
    }
    if (need_string_h)
        sb_puts(c, "#include <string.h>\n");
    if (cx->opt->flags & PCREC_EMIT_MAIN)
        sb_puts(c, "#include <stdio.h>\n#include <string.h>\n");
    sb_puts(c, "\n");
    emit_orientation_block(cx, c, g);
}

/* The `.rodata` reflection instance. The VM passes what it ACTUALLY enforces;
 * see emit_info_def's own comment. */
void pcrec_emit_info(Ctx *cx, const GenNames *g, int engine, const char *why,
                     long long budget, long long work, long long frames,
                     long long ceiling, const BufSurface *bs)
{
    InfoStamp st = { engine, why, budget, work, frames, ceiling, bs };
    emit_info_def(cx, &cx->job->csb, g->infoname, g->upper, &st);
}

/* The residual DEFINITIONS, shared by both emitters exactly as the prologue,
 * the ABI types, `rx_info` and `main()` already are. */
void pcrec_emit_residual(Ctx *cx)
{
    emit_residual_defs(cx, &cx->job->csb);
    sb_puts(&cx->job->csb, "\n");
}

void pcrec_emit_dfa_engine(Ctx *cx, const char *fn, const char *storage)
{
    if (cx->job->engine == PCREC_ENG_UNANCH) emit_unanchored(cx, fn, storage);
    else                                     emit_attempt(cx, fn, storage);
}

/* The standalone main(), shared verbatim: it drives `<prefix>_search` through
 * the caps array and prints caps[0], which is engine-independent.
 *
 * [K21 fix] `<prefix>_search`'s return is THREE-VALUED (match_api_m4.md
 * §4.5): 1 match, 0 no-match, or a negative give-up sentinel
 * (PCREC_ERR_STEPS/PCREC_ERR_FRAMES) when a VM artifact exhausts its step budget
 * or backtrack-frame capacity — DFA artifacts never return the sentinels.
 * The prior version tested the result as a boolean, so C truthiness took
 * the match branch on a negative return and printed `caps`, which the
 * give-up path never wrote — uninitialized-stack output reported as a
 * confident match (K21, docs/dev/known_issues.md). Branch on the actual
 * value instead, mirroring tests/fuzz/fuzz_driver.c's three-way
 * discrimination, and give the give-up case its own exit code (3) so it
 * cannot be mistaken for either match (0) or no-match (1) — or for this
 * main()'s own usage error, which already claims 2. */
void pcrec_emit_main(Ctx *cx, const GenNames *g)
{
    sb_puts(&cx->job->csb, "\n");
    sb_printf(&cx->job->csb,
        "int main(int argc, char **argv)\n{\n"
        "    /* Initialized: gcc -O1 false maybe-uninitialized (pcrec K28). */\n"
        "    ptrdiff_t capture_spans[%s_NCAPS][2] = {{0}};\n"
        "    if (argc < 2) { fprintf(stderr, \"usage: %%s <subject>\\n\", argv[0]); return 2; }\n"
        "    int rc = %s((const unsigned char *)argv[1], strlen(argv[1]), 0, capture_spans);\n"
        "    if (rc == 1) {\n"
        "        printf(\"match %%td %%td\\n\", capture_spans[0][0], capture_spans[0][1]);\n"
        "        return 0;\n"
        "    }\n"
        "    if (rc == 0) {\n"
        "        printf(\"nomatch\\n\");\n"
        "        return 1;\n"
        "    }\n"
        /* [counter-K] One arm PER CODE, and a fallthrough that does not claim
         * to know. This block used to end `printf("frames")` for everything
         * that was not a match, a no-match or ERR_STEPS — so when the third
         * bound landed, a work give-up was reported as a FRAME overflow. That
         * is precisely the failure DD-2's "different failures, different
         * diagnoses" exists to prevent, reached from inside our own harness,
         * and it is why the last arm now reports the code instead of guessing
         * at its meaning. */
        "    if (rc == PCREC_ERR_STEPS) {\n"
        "        printf(\"steps\\n\");\n"
        "        return 3;\n"
        "    }\n"
        "    if (rc == PCREC_ERR_FRAMES) {\n"
        "        printf(\"frames\\n\");\n"
        "        return 3;\n"
        "    }\n"
        "    if (rc == PCREC_ERR_WORK) {\n"
        "        printf(\"work\\n\");\n"
        "        return 3;\n"
        "    }\n"
        "    printf(\"giveup %%d\\n\", rc);\n"
        "    return 3;\n"
        "}\n", g->upper, g->searchfn);
}

/* [DD-13] (plan.md [DD-13] "BENCH-DISCOVERED CANDIDATES" (a); pcrec-bench
 * inbox I-3) THE DFA ARTIFACT'S SELECTION FACTS.
 *
 * THE GAP THIS CLOSES. D46 rules every selection point observable. A VM
 * artifact says which engine it is, which prefilter it took and which rungs it
 * used; a DFA artifact said only `RX_ALTCLS_MERGES`/`_FACTORED` — so its
 * candidate-start prefilter, which is the email specimen's headline ~23x
 * mechanism on a megabyte with no `@` in it, was invisible to any consumer
 * that was not reading the emitted loop. pcrec-bench, the optimization loop's
 * customer, bucketed every DFA row by `rx_info.engine` alone until this
 * landed.
 *
 * WHY THE OLD RULE SAID NO, AND WHY IT NO LONGER DOES. §6.3 ruled the D46
 * macros VM-only on the premise that "a DFA artifact has nothing to report"
 * (emit_vm.c's own comment adds the §5.4 byte-identity worry). The premise is
 * false since wave G: this engine makes real, artifact-wide decisions — the
 * scan shape and the prefilter form — and the byte-identity worry is an
 * argument FOR an unconditional stamp rather than against it, because §6.3's
 * own closing warning is that "a consumer that `#if`s on `RX_ENGINE` is
 * writing code that does not compile against half the artifacts". A macro that
 * exists on EVERY artifact is the only shape that warning can be answered
 * with. The identity gates pay for it once, as an `abi` bump and a re-pin
 * (D76/[TT-11]); they do not pay for it again.
 *
 * SCALARS, NOT MASKS, and the test is emit_vm.c's: a mask is for an axis
 * decided PER QUANTIFIER, where a scalar would lie on a mixed artifact. Both
 * facts below are decided ONCE per artifact — `job->engine` at src/core/
 * compile.c's `nfa_has_bot` fork, the prefilter at `unanch_start`/
 * `attempt_cand` — so there is no mixing axis and nothing for a mask to say.
 *
 * THE VALUES ARE READ OFF THE SAME DERIVATIONS THE LOOP IS EMITTED FROM,
 * never a second copy of their conditions: `unanch_start` (ENG_UNANCH) and
 * `attempt_cand` (ENG_ATTEMPT) are each ONE function with two readers, and
 * each says so in its own header. That is what makes the stamp checkable
 * rather than decorative — it cannot disagree with the loop unless the
 * derivation itself is wrong, in which case the loop is wrong too. */
/* [DD-13c] WHICH SCAN SHAPE THE EMITTED BODY IS, in the three words §6.3
 * documents. `"empty"` is FIRST and not a fallback: a body that is one
 * `return 0` has neither of the other two loops in it, whichever emitter wrote
 * it, so answering "which emitter ran" before "is there a loop at all" is the
 * inversion that produced r37 #5. */
static const char *dfa_scan_name(Ctx *cx)
{
    if (dfa_engine_is_empty(cx)) return "empty";
    return cx->job->engine == PCREC_ENG_ATTEMPT ? "attempt" : "unanchored";
}

static const char *dfa_prefilter_name(Ctx *cx)
{
    /* [DD-13c] THE EMPTY ENGINE HAS NO PREFILTER TO NAME, and it does not need
     * a clause here to say so: `attempt_cand` refuses on `d->n == 0` and
     * `unanch_start` returns with `kind == DFA_PF_NONE` on `empty`, so both
     * arms below already answer "none" for exactly the artifacts
     * `dfa_engine_is_empty` identifies. An `if` here would be a THIRD statement
     * of that fact, and the check (tests/codegen/run_dfa_stamps.sh) asserts it
     * from the emitted text instead. */
    if (cx->job->engine == PCREC_ENG_ATTEMPT) {
        /* ENG_ATTEMPT skips whole ATTEMPTS rather than positions inside one
         * (D63's loop-integration split), so it needs no D11 bound and has no
         * bounded form: `attempt_cand` is memchr-or-nothing by charter, and
         * the derivation's own comment says the bitmap instance would be
         * emitted code no pattern reaches. `<PREFIX>_DFA_SCAN` below is the
         * other half of the key: it tells a reader WHICH loop this memchr is
         * in. */
        CandSet acand;
        return attempt_cand(&cx->job->dfa, &acand) ? "memchr" : "none";
    }
    UnanchStart us;
    unanch_start(cx, &us);
    /* THE BOUND IS PART OF THE VALUE, and that is plan.md [DD-13] (b) made
     * readable rather than a distinction invented here. Under `views` — a
     * `$`/`\Z`/`\z` view or a word context — every skip is bounded at `n - 1`
     * and the memchr arm loses its `return 0` early-out, so the SAME
     * candidate table buys measurably less: the bench measured the `(?:P)\z`
     * spelling's skip loop as strictly weaker than the plain form's, and a
     * consumer that could not tell the two apart would attribute the
     * difference to the pattern. The emitter CAN tell (`us.views` is the same
     * flag the emitted `fbound` string is built from), so it says so. */
    /* [ENG-FORM] THE STAMP IS THE CHOSEN OBJECT'S NAME, and the five values
     * are five OBJECTS: the `-bounded` half is a genuinely different emitted
     * loop, not a suffix this function appends, so it cannot disagree with
     * the loop the emitter wrote. */
    return dfa_pf_of(cx, &us)->c.name;
}

/* [DD-13c] WHICH DFA SCAN THIS ARTIFACT CARRIES — the two lines, emitted from
 * ONE place for the TWO artifact kinds that contain a DFA scan.
 *
 * WHICH DFA. The ENG_UNANCH/ENG_ATTEMPT fork is a genuine per-artifact
 * selection point — [OS-4] calls it "already a cartesian split" and is the row
 * that will one day measure it — and it is not derivable from anything else a
 * consumer can read: both shapes stamp `RX_ENGINE "dfa"` and both set
 * `rx_info.engine` to PCREC_ENGINE_DFA. A bench row that times a `^`-anchored
 * pattern and one that times an unanchored one are timing two different loops,
 * and until this line existed the report could not say which. Read off
 * `job->engine` (the field compile.c sets at the fork) through
 * `dfa_scan_name`, so it cannot disagree with which emitter ran, plus
 * `dfa_engine_is_empty` for the body that has no loop at all (r37 #5).
 *
 * WHY A SHARED EMITTER AND NOT TWO CALL SITES, which is `pcrec_emit_engine_stamp`'s
 * argument one level down and r37 #6's finding one level up. The §6.1 HYBRID —
 * a VM artifact whose `fit.prefilter` is on — inlines THIS FILE'S scan as
 * `static <prefix>_prefilter` and carries the whole mechanism: the tables, the
 * memchr/bitmap candidate-start filter, the D11 bound. Until [DD-13c] it
 * stamped nothing about any of it, so the artifact kind that actually ships the
 * specimen's ~23x mechanism was the one kind that could not say so. It now
 * stamps these same two lines, from the same `unanch_start`/`attempt_cand`
 * derivations the inlined loop is emitted from — ONE derivation, THREE readers
 * (the loop, the DFA artifact's stamp, the hybrid's stamp), never a
 * restatement. A NON-hybrid VM artifact contains no DFA scan and stamps
 * neither; docs/spec/match_api.md §6.3 states that iff and
 * tests/codegen/run_dfa_stamps.sh asserts it in both directions.
 *
 * `upper` IS A PARAMETER rather than re-derived here because the two callers
 * already hold it (`GenNames.upper` on the DFA side, `v.up` on the VM side)
 * and they are the same string — the artifact's prefix, upper-cased, once. */
/* [OPT-K] THE OFFSET-k SET, AS A STAMP — and it is a SECOND stamp rather than
 * a widening of `<PREFIX>_DFA_PREFILTER` for one reason. [ENG-FORM]'s rule is
 * that `DFA_PREFILTER`'s value IS the chosen object's `name`, a static string
 * that cannot disagree with the loop because it is the loop's own selection;
 * a value computed from THIS MACHINE's k-set is a different kind of fact and
 * folding it in would put a `stamp()` method back on axis B, which
 * `emitter_form.md` §3's revision deliberately removed.
 *
 * `"none"` on every artifact whose forward scan carries no offset-k skip,
 * which is every DFA artifact before this row and most after it, so the value
 * set is countable by the form census. The scan offset is marked `*`. */
static void dfa_prefilter_offsets(Ctx *cx, StrBuf *out)
{
    /* NO EMPTY-ENGINE CLAUSE, for `dfa_prefilter_name`'s reason one function
     * up: `unanch_start` returns `kind == DFA_PF_NONE` on an empty engine, the
     * selection is then never asked, and `nsel` is zero — so the arm below
     * already answers "none" for exactly those artifacts. A clause here would
     * be a fourth statement of that fact. ENG_ATTEMPT needs its own arm
     * because `unanch_start` is not the derivation it uses. */
    if (cx->job->engine == PCREC_ENG_ATTEMPT) { sb_puts(out, "none"); return; }
    UnanchStart us;
    unanch_start(cx, &us);
    if (dfa_pf_of(cx, &us)->emit_block == NULL) { sb_puts(out, "none"); return; }
    for (int i = 0; i < us.ofsk.nsel; i++)
        sb_printf(out, "%s%d%s", i ? "," : "", us.ofsk.k[us.ofsk.sel[i]].k,
                  i == us.ofsk.scan ? "*" : "");
}

void pcrec_emit_dfa_scan_stamps(Ctx *cx, StrBuf *c, const char *upper)
{
    sb_printf(c, "#define %s_DFA_SCAN \"%s\"\n", upper, dfa_scan_name(cx));
    sb_printf(c, "#define %s_DFA_PREFILTER \"%s\"\n", upper,
              dfa_prefilter_name(cx));
    sb_printf(c, "#define %s_DFA_PREFILTER_OFFSETS \"", upper);
    dfa_prefilter_offsets(cx, c);
    sb_puts(c, "\"\n");
    sb_printf(c, "#define %s_DFA_TABLE \"%s\"\n", upper, dfa_table_name(cx));
    /* [CC-DIFF] Beside `_DFA_TABLE` because it is about the same tables:
     * that one names their ENCODING, this one says how many of them the
     * uniform fold removed. A `"premultiplied"` artifact reading 2 here
     * carries no forward transition or accept table at all -- the encoding
     * is still the selection that was MADE (and still fixes the folded
     * constant: 65535 pre-multiplied, -1 indexed), which is why that stamp
     * keeps its value rather than falling to `"none"`. */
    sb_printf(c, "#define %s_DFA_UNIFORM_FOLDS %d\n", upper,
              dfa_uniform_folds(cx));
    /* [OPT-5] AND THE SCAN EDGE, which belongs in THIS function and not in
     * `emit_dfa_stamps` beside `_DFA_MATCH`: it is a fact about the DFA SCAN,
     * so a VM HYBRID that inlines this emitter's scan has one too and reports
     * it, exactly as it reports `_DFA_TABLE` and `_DFA_PREFILTER`. [DD-13c]'s
     * (a)/(b) split is the rule; the hybrid is where its point shows. */
    sb_printf(c, "#define %s_DFA_SCAN_EDGE \"%s\"\n", upper,
              dfa_scan_edge_name(cx));
    /* [OPT-5 STEP 2] AXIS J, and it belongs in THIS function for the scan
     * edge's reason one line up rather than beside `_DFA_MATCH`: it is a fact
     * about the DFA SCAN's own entry, so a VM HYBRID that inlines this
     * emitter's scan HAS one and reports it. `_DFA_MATCH` is DFA-only because
     * a hybrid's `_match` is the VM's; `_DFA_START` is not, because a
     * hybrid's inlined prefilter IS this body. [DD-13c]'s (a)/(b) split is
     * the rule and this is where its point shows. */
    sb_printf(c, "#define %s_DFA_START \"%s\"\n", upper,
              dfa_search_start_name(cx));
}

static void emit_dfa_stamps(Ctx *cx, StrBuf *c, const char *upper)
{
    sb_puts(c, "/* Engine: dfa */\n");
    pcrec_emit_engine_stamp(c, upper, "dfa", pcrec_engine_sel_name(cx));
    pcrec_emit_dfa_scan_stamps(cx, c, upper);
    /* [ENG-ABS] AXIS G IS STAMPED HERE AND NOT IN `pcrec_emit_dfa_scan_stamps`,
     * and the placement is the fact rather than a filing decision. That
     * function is SHARED with the VM HYBRID, which inlines this file's scan as
     * its prefilter — so everything it stamps is a fact about a DFA SCAN, and
     * both artifact kinds have one. `<PREFIX>_DFA_MATCH` is a fact about the
     * artifact's `<prefix>_match` ENTRY, and on a hybrid that entry is the VM's
     * own anchored body, which this axis does not describe and whose value set
     * it does not share (spec S6.3's (a)/(b) split rules the names
     * engine-specific). So it is stamped on exactly the artifacts this emitter
     * writes `_match` for, and `rx_info.match_form` mirrors NULL elsewhere. */
    sb_printf(c, "#define %s_DFA_MATCH \"%s\"\n", upper, dfa_match_name(cx));
    /* [ART-SIZE] THE TOTAL-BYTES CAP'S EFFECTIVE VALUE, on a DFA artifact too.
     * The cap applies to whatever was emitted rather than to one engine, so by
     * D81 the artifact must say which limit it was built under — a reader
     * cannot otherwise tell an artifact that fitted from one built with a
     * raised cap. The VM's own stamp block carries this plus the three
     * VM-only ones (`_UNROLL_K`, `_UNROLL_K_WHY`, `_MAX_EMIT_CODE_BYTES`);
     * a DFA artifact has no counter rung to have chosen a K for, so only this
     * one is a fact about it.
     *
     * IT WAS MISSING UNTIL THE DELIVERY size_diff, and the gap is worth the
     * comment: `docs/spec/match_api.md` §6.3 and `limits.md` §8 both already
     * SAID this stamp was on both engines while the emitter put it on one, and
     * what surfaced it was 1,185 corpus artifacts moving exactly 0 bytes in a
     * change that was supposed to move every artifact. */
    sb_printf(c, "#define %s_MAX_EMIT_BYTES %llu\n", upper,
              cx->opt->max_emit_bytes
                  ? (unsigned long long)cx->opt->max_emit_bytes
                  : (unsigned long long)PCREC_MAX_EMIT_BYTES);
    sb_puts(c, "\n");
}

void pcrec_emit_dfa(Ctx *cx)
{
    StrBuf *c = &cx->job->csb;
    GenNames g;
    pcrec_gen_names(cx, &g);

    /* RX_NCAPS WAS 1 ON EVERY ARTIFACT THIS EMITTER PRODUCED (D42.2), on the
     * argument that a DFA-compiled pattern never promises more than the
     * whole-match slot. [DD-14 wave G] retires the argument, not the rule
     * behind it: a capture-bearing pattern still forces the VM, but a group
     * that no emitted code can WRITE is not capture-bearing in that sense —
     * PCRE2 counts it and reports it UNSET, and this engine can promise
     * exactly that. `RX_NCAPS > 1` on a DFA artifact therefore means "every
     * promised group is permanently unset", which is the line tests/codegen
     * now checks instead. See `dfa_artifact_ncaps`. */
    /* A DFA artifact can carry no backreference — the construct is VM_ONLY by
     * its twelve registry rows and SR-8 refuses `--engine=dfa` on it by name —
     * so its mask is the unconditional entry alone. */
    cx->job->enc_mask = PCREC_ENCE_NEXT_POS;
    {
        /* [DD-14.FB] spec §10.4: the surface is emitted on a DFA artifact
         * too, INERT. This engine has no resume stack and no trail, so the
         * four sizing facts are 0 and the three `_in` entries below accept a
         * descriptor and ignore it. */
        BufSurface bs = pcrec_bufsurface_inert();
        pcrec_emit_prologue(cx, &g, dfa_artifact_ncaps(cx), &bs);
    }
    /* [DD-13] The selection stamps, in the SAME PLACE the VM writes its own —
     * immediately after the shared prologue and before the engine body — so
     * the two artifact kinds put their engine line at the same point of the
     * file and a reader (or a grep) finds it in one place. */
    emit_dfa_stamps(cx, c, g.upper);
    pcrec_emit_dfa_engine(cx, g.searchfn, "");

    sb_puts(c, "\n");
    /* [ENG-ABS] AXIS G, and this is its ONE dispatch. `dfa_match_of` is the
     * same call `<PREFIX>_DFA_MATCH` and `rx_info.match_form` are written
     * from, so the stamp names the body that was actually emitted rather than
     * a second reading of the predicate that chose it. */
    if (dfa_match_is_unwrapped(cx)) {
        emit_anchored_entries(cx, c, &g);
    } else {
        emit_match_def(c, g.matchfn, g.searchfn, g.upper);
        sb_puts(c, "\n");
        emit_match_caps_def(c, g.matchcapsfn, g.searchfn, g.upper);
    }
    sb_puts(c, "\n");
    emit_in_entry_defs(c, g.searchfn, g.matchfn, g.matchcapsfn, cx->opt->prefix);
    sb_puts(c, "\n");
    pcrec_emit_residual(cx);
    {
        /* The DFA artifact's stamp: it cannot backtrack, cut, or scan
         * frameless, so NONE of the three bounds applies to it and all read
         * as absent rather than as some notional large number. `work_budget`
         * joins `step_budget` in that reading for exactly the same reason —
         * a bound an engine structurally cannot reach is not a bound of 0. */
        BufSurface bs = pcrec_bufsurface_inert();
        InfoStamp st = { 1, NULL, -1, -1, -1, 0, &bs };
        emit_info_def(cx, c, g.infoname, g.upper, &st);
    }

    if (cx->opt->flags & PCREC_EMIT_MAIN)
        pcrec_emit_main(cx, &g);
}
